/* 全库分片 40/43，共 1000 首（chinese-gushiwen / chinese-poetry）*/
window.QUAN_KU_PART_39 = [
  {"t":"花间四友东坡梦・金盏儿","p":"","d":"元代","a":"吴昌龄","c":["你教我惜芳草，罢经文，把一生功案都休论。", "(东坡云)就是小官为媒，(正末唱)笑你个东坡学士做媒人。", "(东坡云)我能坏你十座寺，你休阻我一门亲。", "(正末唱)你道是能坏我十座寺，休阻您一门亲。", "我也曾万花丛里过，争奈我一叶不沾身。", "(东坡云)牡丹，你与那和尚告菩提露去。", "(旦儿云)是，晓得。", "上告我师：和尚一点菩提露，滴在牡丹两叶中。", "(正末云)小僧半点俱无。", "(旦儿云)那师父说半点俱无。", "(东坡云)再告去。", "(旦儿云)上告我师：和尚一点菩提露，滴在牡丹两叶中。", "(正末云)贫僧十五年不下禅床，功行非浅，实是半点俱无。", "(旦儿云)大人，那和尚说十五年不下禅床，功行非浅，实是半点俱无，却不羞杀我牡丹也。", "(东坡云)吾兄，因你不肯，那牡丹烦恼哩。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・南吕/一枝花","p":"","d":"元代","a":"吴昌龄","c":["身虽在东土居，心自解西来意。", "曾传一盏灯，能有几人知？参透禅机，心外事无萦系。", "想昨宵甚道理，那苏子瞻一谜里歪缠，更和着白牡丹有千般标致。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・梁州第七","p":"","d":"元代","a":"吴昌龄","c":["本待要去西方脱除了地狱，我怎肯信东坡泄漏了天机。", "半生苦行修持力，把心猿锁闭，意马收拾，由他闲戏，任你胡为。", "端的个几番家识破皆非，一心要只履西归。", "枉了你玉人儿娇滴滴待枫叶传情，排下个迷魂阵香馥馥似桃花泛蕊，搅的个选佛场乱纷纷做柳絮沾泥。", "怎知俺九年面壁，蚤明心见性蒲团底，到今日出人世。", "笑你个愚滥的东坡尚不知，也只是肉眼凡眉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・隔尾","p":"","d":"元代","a":"吴昌龄","c":["我贫僧呵，半生养拙无人以，你一举成名天下知，这的是名利与清闲各滋味。", "(东坡云)你这出家的怎生？(正末唱)俺躲人间是非，(东坡云)俺为官的怎生？(正末唱)您请皇家富贵。", "(带云)好便好，则为一首［满庭芳］贬上黄州，也怪不着。", "(唱)兀的是那才调清高落来得。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・骂玉郎","p":"","d":"元代","a":"吴昌龄","c":["则被这东坡学士相调戏，可着我满寺里告他准？我如今修心养性在庐山内，怎生瞒过了子瞻赚上了牡丹，却教谁人来替？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・感皇恩","p":"","d":"元代","a":"吴昌龄","c":["你行者休违拗，我须索把你来央及。", "(做跪科)(行者云)师父只当抢了脸也。", "(正末唱)我其实被东坡，闲魔障，厮禁持。", "(行者云)我要赴白莲会去哩。", "(正末唱)你待赴白莲会里，先和那红粉偷期。", "(行者云)老人家没正经，不要我学好，教我偷鸡吃，被人拿住怎么了？(正末唱)却待说，义教我，怎生题？(行者云)师父，我看你欲言不言的意思，要我怎的？常言道：吃乌饭，病黑屎。", "我只是依随着你便了。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・采茶歌","p":"","d":"元代","a":"吴昌龄","c":["你若是肯依随，不羞耻，我比你先争十载上天迟。", "(云)行者，将耳过来。", "(做耳嘱科，唱)你和他共枕同眠成连理，蚤是得些滋味休要着痴迷。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・贺新郎","p":"","d":"元代","a":"吴昌龄","c":["东坡学士解禅机，我怎肯损坏了菩提？恰才是脱身之计。", "他那厮向绒毛毡取扑绵被，尽强如俺入龙华会，兀的不辱没杀释迦的这牟尼。", "不争那牡丹来赴约，和尚去偷期，东坡倒觉的有些不伶俐。", "一个儿待惜花春起蚤，一个儿待爱月夜眠迟。", "(东坡做睡科)(正末云)大人再饮几杯。", "呀！他睡着了，着他大睡一觉，花间四友安在？(旦儿扮四友上，云)妹子们走动，师父呼唤俺姐妹四人，有何分付？(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・哭皇天","p":"","d":"元代","a":"吴昌龄","c":["我唤你无别意，您四人各做准备。", "梅也你轻讴着白雪歌，柳也你与我满捧着紫金杯，桃也你和他共枕同眠，竹也如鱼似水。", "我这里做方做便，陪酒陪歌。", "东坡比那［满庭芳］，［满庭芳］可便省些闲淘气。", "倚伏着神力鬼力，只除是天知地知。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・乌夜啼","p":"","d":"元代","a":"吴昌龄","c":["这是戒和尚念彼观音蜜，自今宵即便与你回席。", "恁四人各同心儿商议：柳也是必速离了隋堤，竹也你是必休恋着湘妃，梅也你两个罗浮山下会佳期，桃也仍；与我武陵溪畔曾相以。", "柳妖娆，桃美丽，梅魂缥缈，竹影依稀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・黄钟尾","p":"","d":"元代","a":"吴昌龄","c":["那学士呵，你才高世上谁堪比，我教你直睡到人间总不知。", "柳也只要你迎过客送行人，开青眼腿黛眉，伴陶潜的见识。", "竹也只要你摇龙头摆风尾，敲翠节弄清音，引王猷的兴味。", "桃也只要你烘晓日渲朝霞，飘红雨笑东风，赚刘展的旖旎。", "梅也只要你散冰魂呈素魄，欺冻雪傲严霜，腻何郎的妩媚。", "不许你扑剌剌惊破他一枕晨鸡，只要你四人呵，美甘甘迷着他南柯梦儿里。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・月儿高","p":"","d":"元代","a":"吴昌龄","c":["漫折长亭柳，情浓怕分手。", "欲跨雕鞍去，扯住罗衫袖。", "问道归期，端的是甚时候？泪珠儿点点鲛鱼肖透。", "唱彻《阳关》重斟美酒，美酒解消愁。", "只怕酒醉还醒，这愁怀又依旧。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・正宫/端正好","p":"","d":"元代","a":"吴昌龄","c":["晚风轻，霜华重，云淡晚风轻，露冷霜华重，转瑶阶月色朦胧。", "你看那花间四友相搬弄，斗起他那春心动。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・滚绣球","p":"","d":"元代","a":"吴昌龄","c":["俺这里步苍苔攀怪松，靠湖山凌翠峰，正和那五春堂相共。", "俺只索悄冥冥蹑是潜踪，上阶基，近窗孔，见四个小鬼头将端明来簇捧。", "竹梅呵满泛着金钟，那一个舞低杨柳楼心月，那一个歌罢桃花扇底风，饮兴方浓。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・上小楼","p":"","d":"元代","a":"吴昌龄","c":["您了悟那色空，且与吾师是昆仲。", "你伴着那嫩柳夭桃，翠竹红梅，暗约私通，(东坡云)小官止一人在此并无别的陪伴。", "(松神唱)这的是你自去自来。", "相随相从。", "(带云)那花间四友呵。", "(唱)比不得出红妆主人情重。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・尧民歌","p":"","d":"元代","a":"吴昌龄","c":["奸笑你端明学士忒汰朦胧，全不想酒阑人散夜将终，怎还许花间四友僻从容。", "东坡也，不须埋怨我大夫松，这的是禅宗，禅宗，都归一个空，只柯那伊蒲供。", "(松神赶四友下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・耍孩儿","p":"","d":"元代","a":"吴昌龄","c":["想东坡曾受金莲宠，直恁般痴呆懵懂。", "则去那树头树底觅残红，恨不的添一对照道纱笼。", "今宵剩把银缸照，犹恐相逢是梦，这聪明成何用？本待要醉魔佛印，倒做了寤寐周公。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・水仙子","p":"","d":"元代","a":"吴昌龄","c":["俺本是庐山长老恰升堂，(旦儿云)你的是东林寺。", "(正末唱)倒做了普救寺莺莺来闹道场。", "(旦儿云)你出家人比不得唐三藏。", "(正末唱)你道俺出家人不及那往西天的唐三藏，却原来你是曲江头黄四娘。", "(旦儿云)我只待坚心招你做新郎。", "(正末唱)你道是坚心儿招俺做新郎，(旦儿云)留了方丈，和你同归洞房。", "(正末唱)你教我留了方丈，同归那个洞房，(带云)那里有和尚做女婿的？(唱)俺可甚么帽儿光光。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・落梅花","p":"","d":"元代","a":"吴昌龄","c":["你素魄儿十分媚，慧心儿百和香，更压着魏紫姚黄。", "(旦儿云)牡丹花摘将来胆瓶儿里供养者。", "(正末唱)你道是牡丹花摘将来胆瓶里堪供养，休、休、休，只怕耽阁你浅斟抵唱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・风入松","p":"","d":"元代","a":"吴昌龄","c":["你道是离花街柳陌不为娼，(旦儿云)一心待弃贱要从良。", "(正末唱)你一心待弃贱要从良，(旦儿云)输情愿嫁你个山和尚。", "(正末唱)输情愿嫁这山和尚，兀的不是那画堂中别样风光？你明明的把禅机问答，怎知俺暗暗的把春色包藏？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・川拨棹","p":"","d":"元代","a":"吴昌龄","c":["想昨夜在玉春堂，与东坡曾共赏。", "这一个竹影悠扬，这一个柳叶芬芳，这一个梅蕊馨香，这一个柳絮颠狂。", "都是咱使的伎俩，故将你嘶魔障。", "(东坡云)小官已醉矣，委实不认的四位小娘子。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・七弟兄","p":"","d":"元代","a":"吴昌龄","c":["你道是醉乡。", "(东坡云)敢是做梦哩。", "(正末唱)又道是梦乡，也不似这等忒乖张。", "昨夜个喜孜孜灯下相亲傍，今日里假惺惺堂上问行藏。", "可是你困腾腾全不记娇模样。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・梅花酒","p":"","d":"元代","a":"吴昌龄","c":["呀！你从来有些技痒，你从来有些技痒。", "正夜静更长，对月貌花庞，饮玉液琼浆。", "一个个逞歌喉歌婉转，一个个垂舞袖舞郎当。", "只教你似刘伶怎惜的酒量？似李白怎爱的诗章？似周郎待按着宫商？似宋玉待赴着高唐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・收江南","p":"","d":"元代","a":"吴昌龄","c":["呀！这的是主人情重出红妆，怎做得司空见惯只寻常？不由你不坐中狂客恼柔肠。", "一句句对当，一句句对当，总不离一曲［满庭芳］。", "(东坡云)佛印从来多调笑，到被花枝夸俊俏。", "(正末云)高烧银烛照红妆，灯光不把自身照。", "(东坡云)果然是真僧，问他不倒。", "苏轼从今忏悔，情愿拜为佛家弟子。", "(正末云)学士请尊重。", "(行者云)上告我师和尚，行者特来问禅。", "(正末云)速道。", "(行者云)搂住牡丹，胜坐莲台。", "师父咳嗽，徒弟便来。", "(正末云)痴迷性改，分毫不来。", "色即是空，空即是色。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花间四友东坡梦・鸳鸯煞尾","p":"","d":"元代","a":"吴昌龄","c":["从今后识破了人相我相众生相，生况死况别离况，永谢繁华，甘守凄凉。", "唱道是即色即空，无遮无障。", "笑杀东坡也忏悔春心荡，枉自有盖世文章，还向我佛印禅师听一会讲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黄钟・人月圆为细君寿","p":"","d":"元代","a":"魏初","c":["冷云冻雪褒斜路，泥滑似登天。", "年来又到，吴头楚尾，风雨江船。", "但教康健，心头过得，莫论无钱。", "从今只望，儿婚女嫁，鸡犬山田。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・仙吕/赏花时","p":"","d":"元代","a":"无名氏","c":["好斗打相争俺这厮，(关胜云)我不曾重打他，则一拳就打倒了。", "(正旦唱)但吃亏了肛儿他可早推诈死，(关胜云)倘若死了呵，怎了也？(正旦唱)遮莫他血泊内倘着横尸。", "(关胜云)他是官宦人家伴当，姐姐便放了我去，只怕他还要到宫府里告我哩！(正旦唱)你安心波壮士，俺可也便怎肯容的到官司？(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・仙吕/点绛唇","p":"","d":"元代","a":"无名氏","c":["我这里着眼偷瞧，教人耻笑。", "(搽旦做扯净手、按脖子科，云)偌长的身子，则怕人看见。", "你低着腰，把那脚抬得轻着。", "这等的差法，也着人教你。", "赤、赤、亦。", "(正旦唱)怎觑那乔躯老，屈脊低腰，款那步轻抬脚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・混江龙","p":"","d":"元代","a":"无名氏","c":["有一日官人知道，将这一双儿泼男女怎耽饶。", "若知他暗行云雨，敢可也乱下风雹。", "那瓦罐儿少不的井上破，夜盆儿刷杀到头臊。", "妆体态。", "并娇娆，共伴当，做知交，将家长，厮瞒着。", "可正是阎王不在家，着这伙业鬼由他闹。", "我今夜着他个火烧袄庙，水淹断了蓝桥。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・油葫芦","p":"","d":"元代","a":"无名氏","c":["你晌午后先吃了人一顿拷，怎又将他来扯拽着？(搽旦云)奶奶，你倒说的好，他是个贼，见了怎不拿住？(正旦唱)哎！你个贤妇也不索絮叨叨。", "则这一条大官道又不是梁山泊。", "则这一座小店儿又不是沙门岛。", "前面可也下着客人，后面是咱的老小。", "(丁都管云)您孩儿前后执料去，拿住这厮，正是个贼。", "(搽旦云)我现在稍房里拿住他，看他那贼鼻子，贼耳朵，贼脸贼骨头，可怎么还不是贼哩？(上旦唱)似倾下一布袋野雀般喳喳的叫，大古里是您人怨语声高。", "(丁都管云)嗨！拿住了贼，倒说不干我事。", "(搽旦云)我两个来这里收拾。", "一推开门。", "就拿住他，怎么不是贼？(丁都管云)这厮正是贼！(正旦云)且不问他是贼不是赋。", "我只是问你两个。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・天下乐","p":"","d":"元代","a":"无名氏","c":["您做事可甚人不知鬼不觉？他把这房也波门房门可早关闭了，你可便走将来轻将这门扇敲。", "(云)你到这稍房儿里去做甚么？(搽旦云)我在这里拌草料喂马来。", "(正旦唱)这取又无他那盛料盆，又无那喂马槽，妹子也，你可甚空房中来和草？(搽旦云)他在这里正是贼！(正旦云)你道他是贼，知他谁是贼！(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・村里迓鼓","p":"","d":"元代","a":"无名氏","c":["他又不曾杀人放火，他又不曾打家截道，他这般伏低也那做小，(搽旦云)姐姐，常言道：贼汉软如绵。", "休信他。", "(正旦唱)他可便紧叉手连忙陪笑。", "(搽旦云)他笑里有刀哩。", "正是赋，(正旦云)你道他是贼呵！(唱)他头顶又不、又不曾戴着红茜巾、白毡帽。", "他手里又不曾拿着粗檀棍、长朴刀，他身上又不穿着这香绵衲袄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・元和令","p":"","d":"元代","a":"无名氏","c":["做甚道使绳子便绑缚？妹子也到官司要发落。", "(云)我心里待要救那壮士，则除是这般。", "兀那壮士，你姓甚名谁？(徐宁云)我不是歹人，我是徐宁。", "(搽旦云)哦，徐宁正是贼。", "(正旦云)你敢是徐胜？(徐宁云)呸！我是徐胜，是徐胜。", "(正旦唱)你那里没来由则把领头稍，哎！和人寻唱叫。", "则这徐宁、徐胜两个字相差较，妹子你莫耳朵背错听了。", "(云)你近前来，我自认你咱！(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・上马娇","p":"","d":"元代","a":"无名氏","c":["我这里观了相貌，觑了眼脑，不由我忿气怎生消！甚风儿今夜吹来到？也是天对付，可教我和兄弟厮寻着。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・胜葫芦","p":"","d":"元代","a":"无名氏","c":["兄弟，我是你姑舅姐姐李千娇，你见我怎生来不肯屈驴腰？(徐宁云)那壁厢是姐姐哩，受你兄弟两拜咱。", "(搽旦云)不中。", "他是徐宁哩！(正旦唱)喜得间别来身快乐，做甚买卖？度的昏朝，敢则是靠些赌官博。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・幺篇","p":"","d":"元代","a":"无名氏","c":["你道赤手空拳本利少，怕见我面情薄，往日家私甚过的好。", "敢则是十年五载，四分五落，直这般踢腾了些旧窝巢！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・赚煞尾","p":"","d":"元代","a":"无名氏","c":["我与你这金钗儿做盘缠，你去那银铺里自回倒，休得嫌多道少。", "你姐夫那做官处和兄弟厮撞着，这赍发休想是薄。", "你姐夫虽然他便权豪，向亲眷行怎肯妆幺？你姐夫从来贫不忧愁富不骄。", "你可怜见我耽烦受恼，你可怜见我无依少靠。", "兄弟也你若是得工夫，频探望两三遭。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・中吕/粉蝶儿","p":"","d":"元代","a":"无名氏","c":["我生长在大院深宅，便烧个灰骨儿断不了我这幽闲体态，尽着他放荡形骸。", "我可也万千事，不折证，则我这心儿里忍耐。", "遮莫他翻过天来，则你那动人情四般儿不爱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・迎仙客","p":"","d":"元代","a":"无名氏","c":["你不守着那小妮子，闲伴养这死尸骸。", "夜深的向我房里、我房里更做甚么来？你只恁的好不风流，只恁的不自在。", "(带云)我猜着你也。", "(唱)你则道我不肯将门开，多管是你壁听在这窗儿外。", "(云)相公，你在我那门首鞋底鸣，脚步响，你则道我不开这门。", "相公，你则休躲了我，我自开开这门。", "(做开门科)(花荣入门科)(正旦云)可不说来，相公，你躲了我也。", "到天明你可休寻我的不是。", "我依旧关上这门者。", "(做见科，云)兀的不唬杀我也！(花荣云)娘子休惊莫怕，我不是歹人。", "(正旦云)壮士要的金珠财宝，你都将的去，则留着我的性命咱。", "(花荣云)娘子，我不是歹人。", "(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・红绣鞋","p":"","d":"元代","a":"无名氏","c":["唬的我战钦钦系不住我的裙带，慌张张兜不上我的罗鞋，身难整脚难那手难抬。", "见一个偌来大一条汉，直撞入我这卧房来。", "(云)壮士，你从那里来？(花荣云)我越墙而来。", "(正旦唱)可兀的是侯门深似海。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・斗鹌鹑","p":"","d":"元代","a":"无名氏","c":["俺又不留弄月嘲风，怎揽下这场愁山闷海？(孤云)那贼汉怎生般中注模样？(正旦唱)我则见灯影下英雄，(孤云)他拿着些甚么？(正旦唱)谁知他手中有这器械，(孤云)他姓甚名谁？(正旦云)知他姓甚么那？(孤云)你不说他名姓，张千拣大棒子乐。", "将他打着者。", "(正旦云)等我想咱。", "我想起来了也。", "(唱)想起他弓手花荣是说来。", "(孤云)住、住、住，弓手花荣正早梁山上强盗，便与我拿住。", "(正旦云)他走了也、(孤云)我则问你要。", "(正旦唱)这公事怎百刂划？(孤云)他走了更待干罢。", "便与我画影图形，拿捉将来。", "(正旦唱)他沿门儿画影图形，直着我面皮上可也无颜的这落色。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・上小楼","p":"","d":"元代","a":"无名氏","c":["你待教我从实取责，我又不敢当厅抵赖。", "恰待分说，又道叫家不伏烧埋。", "(孤云)你不招呵，俺这里必不干罢。", "(正旦唱)我但有那勒喉咙，抹嗓子，裙力搂带，就在这受官厅自行残害。", "(搽旦云)大人，这赖肉顽皮，不打不招。", "拿那大棒子着实的打上一千下，他才招了也。", "(孤云)张千，与我打着者。", "(张千做打科，云)快招！快招！(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・幺篇","p":"","d":"元代","a":"无名氏","c":["他、他、来如砍瓜，似劈柴。", "棒子着处，血忽淋刺。", "肉绽皮开。", "这般苦禁持，恶抢白，怎生宁奈，(孤云)这妇人的罪犯，情理太重也。", "(正旦唱)只索便一刀两段倒大来迭快。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・快活三","p":"","d":"元代","a":"无名氏","c":["昏惨惨云雾埋。", "疏剌剌的风雨筛。", "我一灵儿直到望乡台，猛听的招魂魄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・二煞","p":"","d":"元代","a":"无名氏","c":["我可也堪恨这个泼短命，堪恨这个歹贱才，我恨不的一枷稍打碎那厮天灵盖。", "他将我那一双儿女拖将去，苦被那祗候公人把我拽过来。", "你后来要还我这脓血债！倚仗着你那有官有势，忒欺负我无靠无挨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・煞尾","p":"","d":"元代","a":"无名氏","c":["那妮子又不知三年乳哺恩，那里晓怀耽十月胎。", "他将我这一双业种阴图害，可正是拾得孩儿落的摔。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・金蕉叶","p":"","d":"元代","a":"无名氏","c":["我一灵儿悲风内喧喧聒聒，我一灵儿怨云里招招磨磨。", "(关胜云)姐姐，苏醒者。", "(正旦唱)是谁人唤姐姐不离了耳朵，(花荣云)千娇姐姐，苏醒者。", "(正旦唱)是谁人将我这小名儿口店题着唤我？(花荣云)千娇姐姐，是您兄弟救你来。", "(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・调笑令","p":"","d":"元代","a":"无名氏","c":["是谁将我来救活？原来是您三个呀！间别来兄弟每安乐波？你刀尖儿抹的他皮肤破，到官司百般摧挫。", "那妮子一尺水翻腾做一丈波，怎当他只留支剌信口开合。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・秃厮儿","p":"","d":"元代","a":"无名氏","c":["如今这杀丈夫的这般结果，有奸夫的可怎生折磨？兄弟也，我吃了那无情棒可也图甚么？如今那做官的，那里是萧何，也波，真个。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・圣药王","p":"","d":"元代","a":"无名氏","c":["我可也千不合，万不合，一时间做事忒多罗。", "没来由结识这个，认义那个。", "我正是识人多者是非多，舌也罗，平地起风波。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・收尾","p":"","d":"元代","a":"无名氏","c":["则被他送我一场亡身祸，今日个将功劳折过。", "那一日卧房里撞着他，(带云)好兄弟也，(唱)今日个法场上救了我。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・乔牌儿","p":"","d":"元代","a":"无名氏","c":["这杯酒也非是俺故意的推，只为出不的俺心头气。", "你若是拿的来那两个泼奴婢，我就甘心做醉死鬼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・雁儿落","p":"","d":"元代","a":"无名氏","c":["我是粉鼻凹柳盗跖，偏爱吃人心肺。", "把这厮剐割的七事子，判了个十分罪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・得胜令","p":"","d":"元代","a":"无名氏","c":["呀！我则要乘兴两三杯，做一个家好筵席。", "休准备别茶饭，(关胜云)姐姐，你要甚么茶饭？(正旦唱)我则待烧一块人肉吃。", "(花荣云)姐姐看了俺弟兄的面皮，单饶了你姐夫一个罢。", "(正旦唱)您兄弟每今日待劝我回心意，自到官来当日，我便与他没面皮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・侧砖儿","p":"","d":"元代","a":"无名氏","c":["只见他揎拳扌果袖，生情发意，将两个小业种领窝来提。", "我这里急慌忙那身起，大走到向他根底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・竹枝歌","p":"","d":"元代","a":"无名氏","c":["好说话将孩儿放了只，当不的他打瓮墩盆乔样势。", "我主意儿不认这负心贼，您三人直吓的，俺两个做夫妻。", "跷蹊，这关节儿到来的疾。", "(花荣云)将小厮丢在涧里去。", "(正旦云)住、住、住。", "休摔杀孩儿，我认则便了也。", "(关胜)既姐姐认了姐夫，咱每见宋江哥去来。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"争报恩三虎下山・随尾","p":"","d":"元代","a":"无名氏","c":["谢得你梁山泊上多忠义，救了咱重生在世。", "若不是您好弟兄再三央，怎能勾我歹夫妻依旧美？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・南吕/一枝花","p":"","d":"元代","a":"詹时雨","c":["浮云敛太虚，好雨澄清霁。", "碧大悬翡翠，明月漾玻璃。", "昏雾霏霏，百蕊飘花气。", "可怜今宵能有几？兀的般一刻千金，说甚么三从四德。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・隔尾","p":"","d":"元代","a":"詹时雨","c":["(唱)后园中别是一样新天气，妾言方知是与非。", "月色如银牲白日。", "就万花亭这壁，下数著大棋。", "谁弱谁强胜负比。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・牧羊关","p":"","d":"元代","a":"詹时雨","c":["自从尧曾置，丹朱教演习，黑白著阴偶阳奇。", "造化有亿万千端，疆路止三百六十。", "错综周天数，列布浑天仪。", "千古万穷秘，神仙不测机。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・隔尾","p":"","d":"元代","a":"詹时雨","c":["采樵烂柯光阴逝，呕血成图妙算奇。", "死里逃生个中意。", "若是谂知，这个就理，胜固欣然败亦喜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・牧羊关","p":"","d":"元代","a":"詹时雨","c":["袖手傍观易，临输悔后迟，但当局个个著迷。", "守成要顾后瞻前，用战在征东击西。", "未做眼防点破，才得手便斜飞。", "门有总关处，棋无两面持。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・骂玉郎","p":"","d":"元代","a":"詹时雨","c":["寻思使得心肠碎，宵废寝，昼忘食，知难见可观乎势。", "局面危，拈上难，冲开易。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・感皇恩","p":"","d":"元代","a":"詹时雨","c":["撞着劲敌，谁肯伏低。", "用机谋，相数算，厮骗欺。", "逢生勿击，遇劫先提。", "满备赢，一著错，便差池。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"对弈・采茶歌","p":"","d":"元代","a":"詹时雨","c":["得便宜，便收拾，成功一路是强的。", "十九纵横白与黑，多人迷误少人知。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕・一半儿","p":"","d":"元代","a":"周文质","c":["多承苏氏肯怜才，终是双生不在囗。", "羞禁奶娘掩面色，耍开怀，一半儿殃及一半儿买。", "写愁词赋自伤悲，传恨琵琶人共知。", "司马哭痛如商妇泣，泪沾衣，一半儿才干一半儿湿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越调・小桃红","p":"","d":"元代","a":"周文质","c":["当时罗帕写宫商，曾寄风流况。", "今日樽前且休唱，断人肠，有花有酒应难忘。", "香消夜凉，月明枕上，不信不思量。", "彩笺滴满泪珠儿，心坎如刀刺。", "明月清风两独自，暗嗟咨，愁怀写出龙蛇字。", "吴姬见时，知咱心事，不信不相思。", "咏桃东风有恨致玄都，吹破枝头玉。", "夜月梨花也相妒，不寻俗，娇鸾彩凤风流处。", "刘郎去也，武陵溪上，仙子淡妆梳。", "群芳争艳斗开时，公子王孙至。", "邀我名园赏春思，探花枝，任君各自簪红紫。", "诸公肯许，老夫头上，插朵粉团儿。", "偏嫌桃杏染胭脂，我爱丁香囗。", "恨杀蔷薇有多刺，怨垂丝，梨花带雨伤春思。", "海棠过了，荼コ开遍，都不似粉团儿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越调・寨儿令","p":"","d":"元代","a":"周文质","c":["分凤鞋，剖鸾钗，薄情自来年少客。", "义断恩乖，雨冷云埋，痴意尚怜才。", "风不定花落闲阶，云不蔽月满楼台。", "燕归也人未归，雁来也信悭来。", "才，不得休约到海棠开。", "弹玉指，觑腰枝，想前生欠他憔悴死。", "锦帐琴瑟，罗帕胭脂，则落的害相思。", "曾约在桃李开时，到今日杨柳垂丝。", "假题情绝句诗，虚写恨断肠词，嗤！都扯作纸条儿。", "鸾枕孤，凤衾余，愁心碎时窗外雨。", "漏断铜壶，香冷金炉，宝帐暗流苏。", "情不已心在天隅，魂欲离梦不华胥。", "西风征雁远，湘水锦鳞无，吁！谁寄断肠书？蟾影边，凤台前，箫声为谁天外远？欹枕情牵，倚槛无言，血泪洒寒烟。", "自薄情别后经年，想嫦娥不念孤眠。", "葡萄架梧桐井，杨柳院海棠轩。", "天！陡恁月儿圆。", "斟玉波，对金荷，新来自觉酒尚可。", "带解金罗，胥淡双蛾，月枕共谁歌？从别后必定心薄，待归来说甚愁多。", "枕边憔悴我，灯下可憎他。", "睃，腰柳瘦因何？莺燕友，凤鸾俦，尽今生猛可里不到头。", "被底温柔，枕上风流，一笔尽都勾。", "明知道泼水难收，争忍说和味合休。", "沈腰偏着丑，潘貌不藏羞。", "愁，人问瘦因由。", "挑短檠，倚云屏，伤心伴人清瘦影。", "薄酒初醒，好梦难成，斜月为谁明？闷恹恹听彻残更，意迟迟盼杀多情。", "西风穿户冷，檐马隔帘鸣，叮，疑是佩环声。", "踏草茵，步苔痕，忆宫妆懒观蝶翅粉。", "桃脸香新，柳黛愁颦，谁道不消魂！海棠台榭清晨，梨花院落黄昏。", "卷帘邀皓月，把酒问东君。", "春，偏恼少年人。", "清景幽，水痕收，潇潇几株霜后柳。", "往日追游，此际还羞，新恨上眉头。", "丹枫不返金沟，碧云深锁朱楼。", "风凉梧翠减，露冷菊音浮。", "秋，妆占许多愁。", "彻骨杓，满怀学，只因爱钱心辨不得歹共好。", "杨柳妖娆，兰蕙丰标，禁不过烂银锹。", "旧人物不采分毫，新女婿直恁风骚。", "攀不得龙虎榜，品不得凤鸾箫。", "猫，不信不敛儿哮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・折桂令过多景楼","p":"","d":"元代","a":"周文质","c":["滔滔春水东流，天阔云闲，树渺禽幽。", "山远横眉，波平消雪，月缺沉钩。", "桃蕊红妆渡口，梨花白点江头。", "何处离愁，人别层楼，我宿孤舟。", "咏蟠梅梨雪旋绕东风，谁屈冰梢，怪压苍松？绿萼含香，枯根层结，春信重封。", "清味远嫌蝶妒蜂，老枝寒舞凤蟠龙。", "夜月朦胧，疏蕊纵横；瘦影交加，碎玉玲珑。", "二色鞋儿轻摇环佩丁东，半露新荷，半掩芙蓉。", "花柳些些，霞绡点点，锦翠弓弓。", "绿绫扇轻拈落红，茜萝尖微印苔踪。", "心恨难通，裙底鸳鸯，出落雌雄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・清江引咏笑靥儿","p":"","d":"元代","a":"周文质","c":["一窝粉香堪爱惜，近眼花将坠。", "添他百媚生，动我千金费。", "春风小桃初破蕊。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・落梅风","p":"","d":"元代","a":"周文质","c":["眉间恨，心上苦，口难言把脚尖儿分付。", "乌靴上半痕鞋下土，忍轻将袖梢儿挪去。", "楼台小，风味佳，动新愁雨初风乍。", "知不知对春思念他，倚阑干海棠花下。", "新秋夜，微醉时，月明中倚阑独自。", "吟成几联肠断诗，说不尽满怀心事。", "鸾凤配，莺燕约，感萧娘肯怜才貌。", "除琴剑又别无珍共宝，则一片至诚心要也不要？风流士，年少客，花无名帽檐羞带。", "新来颇觉略分外，相思病等闲不害。", "乾坤内，山共水，论风流古杭为最。", "北高峰离不得三二里，回头看镂金铺翠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・庆东原","p":"","d":"元代","a":"周文质","c":["闲评论，猛三思，想海神庙错断了乔公事，则合赚他每烧钱裂纸，则合任他每焚香扣齿，不合信他每插状供词。", "人都说桂英痴，则我道王魁是。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"不知宫调・时新乐","p":"","d":"元代","a":"周文质","c":["千里独行关大王，私下三关杨六郎，张飞忒煞强，诸葛军师赛张良。", "暗想，这场，张飞莽撞，大闹卧龙冈，大闹卧龙冈。", "金妆宝剑藏龙口，玉带红绒皇宣授。", "男儿得志秋，旌旗影里骤骅骝。", "满斟，玉瓯，笙歌齐奏，喧满凤凰楼，喧满凤凰楼。", "人活百岁七十稀，百岁光阴能几日，光阴积渐催，穿了吃了是便宜。", "唱著，舞著，终日沉醉，不饮是呆痴，不饮是呆痴。", "迓鼓童童笆篷下，数个神翁年高大。", "糍糕著手拿，磁瓯瓦带浑滓。", "铺下，板踏，萝卜两把，盐酱蘸梢瓜，盐酱蘸梢瓜。", "霎时相见便流恋，俊俏庞儿少曾见。", "一朵白玉莲，端端正正在湖边。", "细看，可怜，香风拂面，真乃是前缘。", "套数。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"大石调・青杏子元宵","p":"","d":"元代","a":"周文质","c":["明月镜无瑕，三五夜人物喧哗，水晶台榭烧银蜡。", "笙歌杳杳，金珠簇簇，灯火家家。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・命文友步京华，看天涯往来车马，对景伤情诉说别离话。一番提起，","p":"","d":"元代","a":"周文质","c":["数年往事，几度嗟呀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"好观音・见一簇神仙香风飒，春娥舞绛烛笼纱。一个多俊多娇好似他，堪","p":"","d":"元代","a":"周文质","c":["描画，笑吟吟重把金钗插。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・行至侵云鳌峰下，却原来正是俺那娇娃。怕不待根前动问咱？人奸诈，","p":"","d":"元代","a":"周文质","c":["拘钤得无半点儿风流暇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越调・斗鹌鹑咏小卿","p":"","d":"元代","a":"周文质","c":["释卷挑灯，攀今览古；妒日嫌风，埋云怨雨。", "因观金斗遗文，故造绿窗新语。", "自忖度，有窨腹，好做得是也有钞茶商，好行得差也能文士夫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫花儿・苏娘娘本贪也欲也，冯员外既与之求之，双解元怎羡乎嗟呼？但","p":"","d":"元代","a":"周文质","c":["常见酬歌买笑，谁再睹沽酒当垆。", "哎！青蚨，压碎那茶药琴棋笔砚书。", "今日小生做个盟甫，改正那村纣的冯魁，疏驳那俊雅的通叔。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"调笑令・那其间美女，搂着村夫，怎做得贤愚不并居？便休题书中有女颜","p":"","d":"元代","a":"周文质","c":["如玉，偏那双通叔不者也之乎？他也曾悬头刺股将经史读，他几曾寻得个落雁沉鱼？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秃厮儿・双渐正瑶琴自抚，冯魁正红袖双扶。双渐正弹成满江肠断曲，冯","p":"","d":"元代","a":"周文质","c":["魁正倒金壶，饮芳醑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"圣药王・双渐正眉不疏，冯魁正兴未足。双渐正闷随江水恨吞吴，冯魁正","p":"","d":"元代","a":"周文质","c":["乐有余。", "双渐正愁怎除，冯魁正写成今世不休书。", "双渐正嫌杀影儿孤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・寻思两个闲人物，判风月才人记取：将俊名儿双渐行且权除，把俏字","p":"","d":"元代","a":"周文质","c":["儿冯魁行暂时与。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・新水令思忆","p":"","d":"元代","a":"周文质","c":["落红风里不闻声，叹东君渐成薄幸。", "却艳冶，又飘零，叶底残英，刚留住惜花性。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风入松・笑将风月好前程，轻付与俊书生。奈春情庭院关不定，被东风吹","p":"","d":"元代","a":"周文质","c":["满宸京。", "隐隐仙姬去也，悠悠环佩无声。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"拨不断・柳青青，竹亭亭，观绝楼头潇潇景，想尽花间怯怯情，添沉心上","p":"","d":"元代","a":"周文质","c":["厌厌病，都只为剖钗分镜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭歇指煞・相逢常约西厢事，到来不奉东墙命。无言暗省，秦楼何夕彩","p":"","d":"元代","a":"周文质","c":["云回，瑶琴昨日冰弦断，碧天今夜孤星耿。", "露寒衣袂轻，风定帘栊静，偏觉更长漏永。", "香消不暖梦蝶魂，月明应搅幽禽宿，灯青偏照离鸾影。", "谁将才子情，说与佳人听？今夜里休来俺梦境。", "从知道枕儿单，也填不得被儿冷。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・蝶恋花悟迷","p":"","d":"元代","a":"周文质","c":["杨柳楼台春萧索，庭院深沉，不把相思锁。", "睡去犹然有梦合，愁来无处容身躲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"神曲缠・咱彼各，休生间阔，便死也同其棺椁。虽然未可，妻夫过活，且","p":"","d":"元代","a":"周文质","c":["遥受亲爱的哥哥。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"二・猛可，折锉，蓝桥路千里烟波，桃源洞百结藤萝。细寻思冰人颇可，","p":"","d":"元代","a":"周文质","c":["好前程等闲差错。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三・鼓盆歌，寂寞，天差我从新庚和，盼芳容同栖绣幄。奈儒风难立鸣珂，","p":"","d":"元代","a":"周文质","c":["叹书生轻别素娥，看佳人输与拔禾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四・分薄，连枝树柯，斫来烧祆庙火。病魔，心如刀锉，对青铜知鬓皤。","p":"","d":"元代","a":"周文质","c":["画阁，更深罗幕，伴灯花珠泪落。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"离亭宴尾・着迷本是伊之祸，辜恩非是咱之过，如之奈何？朱门深闭贾充","p":"","d":"元代","a":"周文质","c":["香，兰房强揣郑生玉，青楼空掷潘安果。", "壶中筹掣做签，盘内棋排成课，待卜个他心怎么。", "界残妆枕上哭，扣皓齿神前咒，启檀口人行唾。", "纸如海样阔，字比针关大，也写不尽衷肠许多。", "和恨染志诚他，连愁书负心我。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・仙吕/点绛唇","p":"","d":"元代","a":"杨梓","c":["便待将韩魏平吞，逼的赵正逃遁。", "偏咱呵安稳，则待要独霸乾坤，全不怕后代人评论。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・混江龙","p":"","d":"元代","a":"杨梓","c":["休为-朝之忿，不思量旋踵丧其身。", "上个尊周朝皇帝，下不闻阃外将军，独自兴心独门立，却不道半山天子半由臣。", "待驱兵领将，积草屯粮。", "平白地要把邻邦困。", "可不道己所不欲，勿施于人。", "(智云)豫让，你言差矣。", "想晋国卿相，惟我居首，兵多人盛，又得韩魏二子。", "协心助翊。", "今合兵攻伐。", "他若拒敌，一鼓成擒；他若不拒守，决水围灌，无有不成功者。", "你倒来替他回护，触恼我心。", "(正末云)巨闻忠臣不怀情于君；孝子不畏死于父；存忠尽节，受斧钺而无怨。", "主公，今上有周朝天子，不尊王命，无故索地，与咱是人情，不与是正理。", "今日无故称兵，大不祥也。", "(智云)如今天王法令不行，周祚衰微，天下诸侯，互相吞并，强者霸，弱者亡，我不乘时，非为智也。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・油葫芦","p":"","d":"元代","a":"杨梓","c":["今门周室虽微礼尚尊。", "(智云)某为晋国陪臣，位列正卿，不为小也。", "(正末唱)咱则是臣下臣，怎敢侵夺他境界起烟尘？便待要开堤灌水把军围闲，攻城掠野把民蒿混。", "却不道德不孤，必有邻。", "(智云)我削除赵氏，谁不服我？(正末唱)便待要除根剪草绝了髫龀，做的个安门己损他人(智云)我立下些基业，贻厥孙谋也。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・天下乐","p":"","d":"元代","a":"杨梓","c":["我则怕远在儿孙近在身。", "(智云)我兵车较多，三倍于赵，又合韩魏之兵甲，屠灭赵氏，亦何难哉？(正末唱)自古为君先爱民。", "圣人道不患寡而患不均。", "若是近大臣，远佞人，则这的是经纶天下本。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・哪吒令","p":"","d":"元代","a":"杨梓","c":["为甚魏柜子，但言的便允？为甚韩康子，但索的便肯？为共赵襄子不辞而便奔？见他外面而服，非咱中心臣顺，都是些假热佯亲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・鹊踏枝","p":"","d":"元代","a":"杨梓","c":["主公是智超群，也不合势威人。", "全不肯去暴除邪，发政施仁。", "好勇兴兵起军，全不肯偃武修文。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・寄生草","p":"","d":"元代","a":"杨梓","c":["平白地恩翻成怨，善变做嗔。", "不寻思治国安邦论，常怀着篡位同谋衅，偶兴败国亡家忿。", "主公呆民伐罪仿成汤，推位让国学尧舜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・醉扶归","p":"","d":"元代","a":"杨梓","c":["则为他好奢侈行谗佞，剔孕妇削贤心，因此上吕望兴师过孟津，血浸朝歌郡。", "为甚把武王扶持做了至尊？这的是法正天心顺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・金盏儿","p":"","d":"元代","a":"杨梓","c":["扭回身，上阶跟。", "(智云)豫让，你又来了，再若阻当我，一剑挥之两段。", "(正末唱)见他恶哏哏画色十分愠，剑横秋水气凌云。", "折末尸骸横百段，热血污黄尘。", "忠臣个怕死，怕死不忠臣。", "(智云)左右，与我拿下豫让，斩讫报来。", "(众拿科)(韩、魏劝，云)主公不可。", "今欲早伐，先斩家臣，于军不利。", "待平了赵氏，斩之未迟。", "(智云)看二君之面，教豫让权寄下这一颗头，待除了赵氏，不道肯轻饶了你哩。", "(正末云)谢我主不杀之恩。", "主公不听豫让之言，后悔之晚也。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・赚煞","p":"","d":"元代","a":"杨梓","c":["少不的有国不能投，有家应难奔，无粮草先逃下庶民，血沥沥尸横刀门刎。", "少不的事君能致其身，把我这志常存，须有用着我的时辰，主公呵咫尺征袍渍血痕。", "直等到外无救军，内遭危困，那时节一腔鲜血报君恩。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・正宫/端正好","p":"","d":"元代","a":"杨梓","c":["雨初睛，风才定，风雨过正是三更，一轮皓月如悬镜，万里长天静。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・滚绣球","p":"","d":"元代","a":"杨梓","c":["稍公呵你与我慢慢行，悄悄的听，好教我把心不定。", "驾着个小船儿如履薄冰。", "外面是军护着堤，卫而是水浸着城，教找那里寻捷径？急煎煎无计逃生，我想那晋阳城下千寻水，便是智伯胸中百万兵，虎斗龙争。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・倘秀才","p":"","d":"元代","a":"杨梓","c":["你待顺襄子谈兵说兵，你背智伯是无情有情。", "(韩、魏云)某岂敢背主事仇？(正末唱)您恰才对天因何歃血盟？(韩、魏云)俺才说分了赵氏，当誓死以报智伯。", "(正末唱)你如何要整队伍，出军营，做的个弊幸？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・笑和尚","p":"","d":"元代","a":"杨梓","c":["恁恁恁忒言清行不清，恁恁恁拚死命敌活命，恁恁恁自行病自医病，恁恁恁莫打挣，恁恁恁休折证。", "恁恁恁别了俺阃外将军令。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・倘秀才","p":"","d":"元代","a":"杨梓","c":["俺不是智伯家差来的使命。", "(韩魏云)不是智伯差来，却是那里来的？(正末唱)俺是赵襄子使将来察探事情，特地向君侯行借些救兵。", "(韩魏云)如今水势浩大，城廓不保，不时陷没。", "生民鱼鳖。", "就有救兵，如何救的？(正末唱)且休说淹城邑，损生灵，岂不闻唇寒齿冷？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・滚绣球","p":"","d":"元代","a":"杨梓","c":["俺襄子便有罪尔，便令该正刑，也合可怜见虚飘飘满城百姓，浑一似缀露飞萤。", "家家灶产蛙，处处水刷做坑，众军民往来奔竞，咫尺间海角飘零。", "投至得闹炒炒阵面上逃了生性，便是番滚滚波心捞月明，感叹伤情。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・倘秀才","p":"","d":"元代","a":"杨梓","c":["臣不才虽然无能，二主公宁心试听，济不济君侯再察情。", "说着呵无凭验，做着呵有实减，非是自矜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・滚绣球","p":"","d":"元代","a":"杨梓","c":["休和他觅斗争，厮奚竞，杀下守堤吏教他自窝里厮并，您把中军掩映处潜形。", "您外面将堤坝来撅，俺城中把金鼓鸣。", "正是外合里应，教智伯才知水火无情。", "教那帐前旌节门前戟，都做了风里杨花水上萍，直教他一事无成。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・倘秀才","p":"","d":"元代","a":"杨梓","c":["往常你统着兵车百乘，如今却落不的折箭中茎，却甚不动刀枪自太平。", "你也忒跋扈，忒狰狞，你便噤声。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・滚绣球","p":"","d":"元代","a":"杨梓","c":["当日个宴兰台酒二觥，要不阳一座城，与不与更教水围军并，平白地虎斗龙争。", "开汾绛两道河，平韩魏万灶兵，筑高堤有如山岭，四周围抵多少万丈深坑。", "当时待把人推入，今日你被人推更不轻，罪合当刑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・尾声","p":"","d":"元代","a":"杨梓","c":["早则去除了桓子心头病，斩砍了韩康眼内丁。", "扫荡浮尘门月明，剪灭妖氛宇宙清。", "道寡称孤事不成，霸业图正令不行，智们从来好战争，更做你能行离不了影。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・紫花儿序","p":"","d":"元代","a":"杨梓","c":["滴溜溜拥身飞过，赤力力镇动花梢，扑簌簌惊起栖鸦。", "悄蹙蹙的潜踪蹑足。", "七林林的约柳分花。", "谁敢停时霎。", "转过牡丹槛荼足兼洞木香架，早来到沉香亭直下。", "银汉初斜，谯鼓才罢。", "(云)进的这园西隅，是一所厕房，门窗半掩。", "我且入内藏伏，再作计较。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・小桃红","p":"","d":"元代","a":"杨梓","c":["两双脚轻将地皮踏，把台榭兰干抹，见个矮阔阔阶墓将板门儿亚。", "靠着檐压，撮身飞入无惊怕，静悄悄厕楼内等他。", "黑洞洞上墙匡直下，又没甚斜月照窗纱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・东原乐","p":"","d":"元代","a":"杨梓","c":["鞋履鸣穿花径，银烛焚烧绛蜡。", "我举目抬头观赡罢，向灯影里凹着狠鼻凹，梆嗽自矜夸，可知道气昂昂的敢轻俺臣下。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・雪里梅","p":"","d":"元代","a":"杨梓","c":["则听的人语闹交杂，呼左右快搜咱，他道乞丕丕心惊，我恶狠狠跳出，(外等捉拿正末上，正末唱)斗将我嗔忿忿捉拿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・紫花儿序","p":"","d":"元代","a":"杨梓","c":["将我扑鲁鲁的横拖倒拽，闹炒炒的后拥前推，我急煎煎独力难加，我不能勾剜心摘胆，只办个咬齿嚼牙。", "(赵云)你是甚人？黑夜入我园中，非奸即盗，如何不跪？(正末唱)教我跪膝着他，折末斩便斩敲便敲剐便剐。", "我其实不怕。", "(赵云)这厮不直说，左右取刑具来，打着问他。", "(正末唱)既待舍死忘生，怕甚么吊拷棚扒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・络丝娘","p":"","d":"元代","a":"杨梓","c":["只为你乱军，上坏下智伯，更将他家小灭伐。", "我将你赵襄子就宫禁中待把你亲身刺杀，更将玉殴珠楼片瓦根椽宜教火焚下罢。", "这足兼豫间更别无甚别话。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・酒旗儿","p":"","d":"元代","a":"杨梓","c":["俺主公贪疆土，自是伤风化。", "你不合将他天灵盖饮流霞，我说与你众人试鉴察咱，襄子这的是你毒害那他独霸，既你个赵襄子兴心问咱，你将俺主人凌迟处死，漆骨为樽，因此上结的似上海冤仇大。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・调笑令","p":"","d":"元代","a":"杨梓","c":["这答儿和咱话不投机一句差。", "他虽不是万乘主千乘君上驾，你可甚有德行的赵主官家？哎，蒺藜也开沙上花，真乃是井底之蛙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・鬼三台","p":"","d":"元代","a":"杨梓","c":["休则管高声骂，相惊唬，看的咱似木楂。", "你有福我无缘，你稳坐龙床凤榻。", "若不是厕房中众人拿住咱，我报冤仇志酬非是假。", "若是我有分成功，咱这无明火发。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・圣药王","p":"","d":"元代","a":"杨梓","c":["一只手将嗓子掐，一只手将脚腕来拿，滴溜扑摔个仰剌叉，将匕首拔，觑着你软肋上扎。", "教古鲁鲁鲜血浸寒沙，看你今夜宿谁家？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・眉儿弯","p":"","d":"元代","a":"杨梓","c":["谁恋你官二品，车驷马，待古有德行的富贵荣华。", "想着俺那有恩义的主人公放不下，我故来报答。", "报答的没合煞，到惹一场傍人笑话。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・耍三台","p":"","d":"元代","a":"杨梓","c":["我这一片为主胆似秋霜烈日，觑那做官心似野草闲花。", "(赵云)豫让为主报仇，真义士也！左右放了他，随他那里去罢。", "(正末唱)和你是剜心摘胆两事家，怎肯有喜悦和洽？我活呵谨防着断头分尸，我死后你放心称孤道寡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・中吕/粉蝶儿","p":"","d":"元代","a":"杨梓","c":["本待向赵王宫里斩虎诛龙，空惹的市曹巾小儿每侮弄，那里也大将军八面威风。", "吞炭呵掏下咽喉，漆身呵伤了皮肉；主人呵更怕我声扬我这疼痛。", "奔走四东，行言语便推哑中。", "(众小儿推抢科，正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・醉春风","p":"","d":"元代","a":"杨梓","c":["把我抢了脸向前推，扌光破头往后拥，这伙刁大厥地小敲才，只管把我来哄哄哄。", "不辨贤愚，不分高下，不知轻重。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・迎仙客","p":"","d":"元代","a":"杨梓","c":["当初是尧社稷，让了舜封疆。", "舜又命禹王将天下一统。", "伊尹有相汤的贤，武王有伐纣的功。", "想当初风虎云龙，做下一枕南柯梦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・上小楼","p":"","d":"元代","a":"杨梓","c":["说着呵心头怒拥，无处发送，恨塞长空，气结秋云，泪洒西风。", "将俺主公头作器皿，筵前使用。", "则你道波俺这为臣的痛也不痛？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・尧民歌","p":"","d":"元代","a":"杨梓","c":["嗨，不想乞答的顿！下金锁虐蛟龙，我若得手呵，敢教你浑身血染战袍红。", "你和俺主人公敢一般消洒月明中，七魄三魂卉无踪，如同潇潇落叶风，最你成何用？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・耍孩儿","p":"","d":"元代","a":"杨梓","c":["今日个会兵机的襄子夸英勇，显的没下梢的将军落空。", "你将他碜可可斩在乱军中，把一个死尸骸暴露霜风。", "划地漆头为器斟琼液，可甚翠袖殷勤捧玉钟。", "未出语心先痛，杀人可恕，情理难容！(赵云)你前来刺我，我饶了你；今日又来刺我，却饶不得你也。", "(正末云)明主不弃仁义之臣，愿得脱下的衣服，与主报怨，死亦无憾。", "(赵云)既如此，将这一件衣服与他，看他何用。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・三煞","p":"","d":"元代","a":"杨梓","c":["豁不下我这满腹冤，干休了半世功，急煎煎独力难敌众。", "(拔剑将襄子衣服碎剁科，云)罢，罢，我今日剑锉了你这衣服，就和杀了你一般，死亦无恨。", "(唱)虽不能勾碎分肢体诛了襄子，烂锉下这件衣服便是报下俺主公。", "至如把残生送，下埋黄土，仰问苍空。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・二煞","p":"","d":"元代","a":"杨梓","c":["士为知己死，女为悦己容。", "(云)豫让蒙俺主君知爱超出流辈，今日安忍背主事仇！(唱)我怎肯做诸侯烈士每相讥讽？我怎肯躬身叉手降麾下？我宁可睁眼舒头伏剑锋。", "枉子你闲唧哝，折末宫高一品，禄享千钟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忠义士豫让吞炭・尾声","p":"","d":"元代","a":"杨梓","c":["我不想声闻在人世间名标在史记在你把我主人公葬在麒麟冢，谁受你徼买人情赵王宠！(自刎下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・仙吕/赏花时","p":"","d":"元代","a":"武汉臣","c":["我为甚将二百锭征人的文契烧？也只要将我这六十载无儿冤业消。", "(带云)婆婆，我可似个甚么那？(唱)我似那老树上今日个长出些笋根苗。", "(带云)婆婆，小梅这妮子呵，(唱)你心中可便不错，(云)婆婆，小梅这妮子，他可似甚么？那如同那生菜儿一般，他只要新水儿洒者波。", "婆婆，(唱)你是必休将兀那热汤浇。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・仙吕/点绛唇","p":"","d":"元代","a":"武汉臣","c":["将本求财，在家出外，诸般儿快。", "拥并也似钱来，到底个还不彻冤家债。", "(云)那一日婆婆人情去了，小梅这妮子忽的走到面前道：\"爹爹，小梅有句话，可是敢说么？\"老夫便道：\"有甚么话，你说波。", "\"他道：\"小梅有半年身孕。", "\"老夫便道：\"小鬼头，休胡说！婆婆听得呵枉打死你。", "\"他道：\"您孩儿不敢说谎。", "\"老夫道：\"是真个么？\"他道：\"是真个。", "\"我便教人请稳婆去。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・混江龙","p":"","d":"元代","a":"武汉臣","c":["请来凭脉，(云)一投的凭罢那脉也，婆婆道：\"老的，你索与我换上盖咱。", "\"老夫便道：\"你与我说了，我与你。", "\"他便道：\"老儿，你贺喜者。", "\"(唱)他道小梅行必定是个厮儿胎。", "不由我不频频的加额，落可便暗暗的伤怀。", "但得一个生忿子拽布披麻扶灵柩，索强似那孝顺女罗裙包上筑坟台。", "往常我瞒心昧己，信口胡开，把神佛毁谤，将侩道抢白。", "因此上折乏的儿孙缺少，现如今我筋力全衰。", "人说着便去，人唤着忙来，看经要火罪，舍钞要消灾。", "我急煎煎去把那稳婆和老娘寻，恨不得曲躬躬将他土块的这砖头来拜。", "(带云)我想：儿孙的福分，非同小可也。", "(唱)使不着人强马壮，端的是鬼使神差。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・油葫芦","p":"","d":"元代","a":"武汉臣","c":["有那等守护贤良老秀才，他说的来、狠利害。", "(云)他每都道是，刘从善那老子空有钱，则恁般割舍不的使。", "若是个女儿呵罢论，若是个小厮儿呵，耻辱那老子一场。", "(唱)他待将这老头儿监押去游街。", "(带云)小梅，你若真个得个儿呵，(唱)我情愿谢神天便把那香花赛，请亲邻便把猪羊宰。", "遮莫他将蹇卫迎，草棍捱。", "但得他不骂我做绝户的刘员外，只我也情愿湿肉伴干柴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・天下乐","p":"","d":"元代","a":"武汉臣","c":["我可便得一个残疾的小厮儿来，问甚么兴也波衰，总是那天数该。", "(云)天那，倘是我小梅这妮子分娩了，你觑这早晚多早晚也，莫不是小厮儿生得毒么(唱)则他那时辰儿问甚么好共歹，我但得把他摇车儿上缚，便把我去墓子里面埋，我便做一个鬼魂儿，可便也快哉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・那吒令","p":"","d":"元代","a":"武汉臣","c":["哎！你是个主家的，(云)偌大年纪，亏你不害那脸羞。", "(卜儿云)我又不曾放屁，我怎么脸羞？(正末唱)你兴心儿妒色，你是个做女的，(云)不学些三从四德，俺一家儿簇捧着你为甚么来？(唱)你从心儿的放乖。", "更着你个为婿的，(云)万贯家缘都在你手里，你在那钱眼里面坐的。", "兀自不足哩！(唱)你贪心儿爱财。", "(做哭云)痛杀老夫也。", "(卜儿笑科，云)呸！我又不曾捻杀他，又不曾掐杀他，他惶恐自害羞走了，你张开着口哭些甚么？(正末唱)怎着我空指望，空宁耐，落得这苦尽甘来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・鹊踏枝","p":"","d":"元代","a":"武汉臣","c":["你可便道他歪，不思量我年迈。", "(卜儿云)说道走了个只身的小妮子，打甚么不紧？则管里絮絮聒聒的。", "(正末唱)他可便虽则只身，那里也是那重胎。", "(带云)张郎，(唱)则被你坏了我也，当家的这娇客！(云)我原来错怨了人也，都不干你事。", "(唱)天那，则被你便送了我也，转世的浮财。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・寄生草","p":"","d":"元代","a":"武汉臣","c":["你不将我人也似觑，倒着我谜也似猜。", "(带云)你听，我说与你，(唱)道不的二十上有志呵人都爱，三十上有命呵人还待。", "到的这四十上无子呵，可便人不拜。", "我想着那未分男女的腹中胎，(卜儿云)我只拣那年纪小，生得好的，替你再娶一个，你也还养得出哩。", "(正末唱)谁问你那不施脂粉天然态？(云)张郎，你到家便将那好钞拣下一二千锭者。", "(卜儿云)敢是你那里看上了一个，你待取来做小老婆也。", "(正末云)我是娶一个，也由的我那。", "(卜儿云)休道你娶一个，便娶十个，我是大，他也则索扶侍我。", "(正末云)为甚么扶待你？(卜儿云)怎么不扶侍我？(正末云)你不曾与俺刘家立下嗣来。", "(卜儿云)休道立下寺，我连三门都与你盖了。", "(正末云)张郎，你去四门头出下帖子，但是有等贫难的人，明日绝早到开元寺内，我散钱去也。", "天那，刘从善今日悔过了也。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・青哥儿","p":"","d":"元代","a":"武汉臣","c":["他敢把咱来烧香，烧香礼拜，恰便似祖先，祖先看待。", "(卜儿云)你便这般救苦怜贫，舍财布施，做下功德，只是年纪高大，也没多几时在世，有那一个知道你的？(正末云)婆婆，你道他每不知道我么？(唱)你道我日暮桑榆事可哀，将我死后尸骸，向古道悬崖，浅葬深埋，松柏多栽。", "则恐怕后人不解，垒座砖台，镌面碑牌，写的明白。", "等过往人来觑了伤怀，都道是开元寺散家财的这刘员外。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・赚煞尾","p":"","d":"元代","a":"武汉臣","c":["我在这城中住六十年，做富汉三十载。", "无倒断则是营生的计策，今日个眼睁睁都与了补代。", "那里也是我的运拙时乖。", "(带云)婆婆，(唱)我这里自裁划，也不索垒七波追斋。", "则那两件事敢消磨了我这半世的灾：我也再不去图私利狠心的放解，我也再不去惹官司瞒心儿举债。", "(云)这两桩儿咱都不做了，难道天是没眼的？(唱)可敢也一天好事奔人来。", "(同众下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・正宫/端正好","p":"","d":"元代","a":"武汉臣","c":["则被你引的我来半生忙，十年闹，无明夜攘攘劳劳。", "则我这快心儿如意随身的宝。", "哎，钱也，我为你呵，恨不的便盖一座家这通行庙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・倘秀才","p":"","d":"元代","a":"武汉臣","c":["那其间我正贫困里，可便夺的一个富豪，今日个上户也，可怎么却无了下稍？也是我幼年间的亏心，今日才老来报。", "(带云)哎，钱也，我为你呵。", "(唱)也曾昧著心说咒誓，今日个睁着眼犯天曹，孜孜的窨约。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・呆骨朵","p":"","d":"元代","a":"武汉臣","c":["则俺这做经商的，一个个非为不道，那些儿善与人交。", "都是我好贿贪财，今日个折乏的我来，除根也那翦草。", "我今日个散饯波，把穷民来济，悔罪波，将神灵来告：则待要问天公赎买-个儿，(卜儿云)我明日再别替你娶一个罢，有你也不愁无儿。", "(正末唱)也等我养小来防备老。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・脱布衫","p":"","d":"元代","a":"武汉臣","c":["今日今散钱呵，您不合闲焦，看我面也，合道是耽饶。", "他主着意和人硬挺，便睁着眼大呼小叫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・小梁州","p":"","d":"元代","a":"武汉臣","c":["他骂-声绝户的穷民怎敢放刁，则一句道的我便肉战也身摇。", "(做悲科，云)兀的不痛杀我也。", "(唱)我伤心有似热油浇，他那里忙陪笑，敢这厮笑里暗藏刀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・幺篇","p":"","d":"元代","a":"武汉臣","c":["元来是父亲行请过了孩儿又要，您怎么不寻思枉物难消。", "(刘九儿云)从小里惯了孩儿也。", "(正末唱)你从小里也该把这孩儿教，怎生由他恁撒拗？道不的家富小儿骄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・倘秀才","p":"","d":"元代","a":"武汉臣","c":["你有钱时待朋友每日家花花草草，你今日无钱也，(带云)索央亲眷每呵，爹爹，奶奶，有盘缠与些儿波。", "(唱)便这般烦烦也那恼恼。", "(带云)哎，儿也，(唱)也是你贫不忧愁富不骄，则待经商寻些资本，则不如依本分教些村学，那的也便了。", "(引孙云)您孩儿一径的来问伯伯、伯娘，借些本钱做些买卖。", "(正末云)引孙孩儿也，则不如读书好。", "(引孙云)伯伯，则不如做买卖。", "(正末云)引孙孩儿也，则不如读书好。", "(引孙云)伯伯，则不如做买卖好。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・煞尾","p":"","d":"元代","a":"武汉臣","c":["在生呵奉养父母何须道，死后呵祭奠那先灵你索去学。", "缺少儿孙我无靠，拜扫坟茔是你的孝。", "他处求人沽酒浇，乡内寻钱买纸烧，一日坟头与我走一遭。", "一句良言说与你听着：你若是执性愚顽不从我教，引孙也，我着你淡饭黄齑，一直饿到你老。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・越调/斗鹌鹑","p":"","d":"元代","a":"武汉臣","c":["你看祭台和这坟台，砖墙也那土墙，长出些个棘科和这荆科，那里有白杨也那绿场？(带云)婆婆，恰才不有人上坟来那，(唱)上坟的是女儿和这侄儿，还是近房也那远房。", "婆婆，哎，你觑那光塌塌的坟墓前，湿津津的田地上，不闻的肉腥和这鱼腥，那里取茶香也那酒香？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・调笑令","p":"","d":"元代","a":"武汉臣","c":["则俺这一双老枯桩，我为无那儿孙不气长。", "百年身死深埋葬，坟穴道尽按着阴阳。", "咱两个死时节便葬在兀那绝地上，(带云)婆婆，到那冬年节下、月一十五，婆婆也，(唱)谁与咱哭啼啼的烈纸烧香？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・小桃红","p":"","d":"元代","a":"武汉臣","c":["则咱这弟兄儿女总排房，向这一个坟茔里葬。", "辈辈流传祭祖上，(带云)引孙。", "(唱)俺两口儿须大如您爹娘。", "(卜儿做劝科，云)老的也，你休打他。", "(正末唱)哎，你个莲子花放了我这过头杖。", "(带云)我不打这厮别的。", "(唱)这嘶祭祖先可怎生无些儿家大量，则这个便是上坟的小样。", "(卜儿云)老的也，你说了呵打。", "(正末云)婆婆，我打了呵说。", "(卜儿云)你说了呵打。", "(正末云)婆婆，你放手。", "(唱)因此上便先打了后商量。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・紫花儿序","p":"","d":"元代","a":"武汉臣","c":["哎，你个择邻的孟母，休打这刻木的丁兰，(云)婆婆放手，这干那女婿甚么事？(唱)且问你那跨虎的杨香。", "(卜儿云)孩儿，我为甚么打你几下，您父烦恼哩！孩儿也，你为甚么不穿些好衣服？(旦儿云)则这般罢波。", "(卜儿云)将钥匙来。", "着下次孩儿每取衣服去。", "(张郎云)浑家，中么？(旦儿云)不妨事，奶奶向着俺哩。", "兀的钥匙。", "(卜儿做拿钥匙科，云)你两个贱人，再也休上我门来。", "老的，你十三把钥匙，我都赚将出来了也。", "(正末唱)哎，女婿着出舍，闺女着回房，相当。", "得意梁鸿引着你这孟光，炒闹了一个太公庄上。", "你也再休踹我刘门，我今也靠不着你个张郎。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・秃厮儿","p":"","d":"元代","a":"武汉臣","c":["着女婿别无指望，做女的也合斟量。", "则这家私里外您尽掌，孝父母，奉蒸尝，也波周方。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・圣药王","p":"","d":"元代","a":"武汉臣","c":["这一场，胡主张，您须热闹俺荒凉。", "您行短，俺见长，姓刘的家私着姓刘的当。", "女儿也，不索便怨爹娘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・收尾","p":"","d":"元代","a":"武汉臣","c":["你可便休和他折证，休和他强。", "自古道：女生外向。", "他到门日且休题，只着他上坟时自思想。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・双调/新水令","p":"","d":"元代","a":"武汉臣","c":["一杯寿酒庆生辰，则我这满怀愁片言难尽。", "只因那几贯财，险缠杀我百年人。", "我受了万苦千辛，我受了那一生骂半生恨。", "(张郎同旦儿上，云)自家张郎的便是。", "今日父亲生日，俺两口儿拜父亲去。", "早来到门首也。", "小舅，(引孙云)那里一阵穷气？姐夫，你那里去来？(张郎云)我道你不是个受贫的人么，俺来拜父亲哩。", "(引孙云)姐姐、姐夫，我报复去。", "(报科云)父亲，有姐姐、姐夫在于门首。", "(正末云)谁在门首？(引孙云)是姐姐、姐夫哩。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・清江引","p":"","d":"元代","a":"武汉臣","c":["你道是女儿、女婿都在门，我可为甚么不容他进？你只问他使的是那家钱，上的是那家坟？(带云)他今日又上俺门来。", "(唱)显的俺两口儿无气分。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・落梅风","p":"","d":"元代","a":"武汉臣","c":["你道他本贤达，能孝顺，只我个老无知偏生嗔忿。", "谁着他信夫妇的情，就忘了我养育的恩？(云)引孙，你对他说去，都不干我事。", "(唱)这都是他自做来有家难奔。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・雁儿落","p":"","d":"元代","a":"武汉臣","c":["原来这亲的则是亲，我当初恨呵须当恨。", "那女夫便是各白的人，那女儿也该把俺刘家认。", "(卜儿云)老的，谁想刘员外自家有了孩儿也？(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"散家财天赐老生儿・得胜令","p":"","d":"元代","a":"武汉臣","c":["婆婆，咱早则绝地上不安坟，则咱这孝堂里有儿孙。", "你今日个得病如医病，(旦儿云)父亲，今日有了孩儿也，休忘了您女孩儿。", "(正末唱)姐姐，我怎肯知恩不报恩？(引孙云)今日有了儿也，十三把钥匙还了伯伯，您孩儿则做的一日财主。", "(正末唱)你一世儿为人，这的是大富十年运，咱三口儿都亲。", "(带云)俺女儿、侄儿和这孩儿，(唱)我把这泼家私做三分儿分。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"大石调・六国朝收心","p":"","d":"元代","a":"睢景臣","c":["长江浪险，平地风恬。", "恨世态柳颦频眉，顺人情花笑靥。", "乌兔东西急，白发重添；寒暑往来侵，朱颜退染。", "穿花蝶愁扃绿锁，营巢燕恨簌朱帘。", "蝶入梦魂潜，燕经秋社闪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"摧拍子・拜辞了桃腮杏脸，追逐回雪鬓霜髯，死灰绝焰。腹难容曩日杯盘，","p":"","d":"元代","a":"睢景臣","c":["身怎跳而今坑堑？去奢从俭。", "六桥云锦，十里风花，庆赏无厌。", "四时独占，花溪信马，莲浦乘舟，菊绽霜严，雪残梅堑。", "鸟呼人至，鹤送猿迎。", "酒肴随分，费用从廉，就清流洗痕濯玷。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・烟花簿敛，风尘户掩，再谁曾制关抽店？尽亚仙嫁了元和，由苏氏放","p":"","d":"元代","a":"睢景臣","c":["番双渐。", "罢思绝念，忘却旧游。", "魔女魂香，野狐涎甜，觉来有验。", "抽箱罗帕，倒袋香囊，将俺拘钳，做科撒阽，浮花浪蕊。", "胜馥残豪，你能搽抹，谁敢粘沾，倒榻鬼赖人支{坫瓦}！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"归塞北・呆娇艳，自要苦厌厌。觅见银山无采取，寻着钱树不揪ㄎ，典卖","p":"","d":"元代","a":"睢景臣","c":["尽妆奁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・零替了家私怕搜检，缺少了些人情我应点。情瞒儿出尖，谁负债拿着","p":"","d":"元代","a":"睢景臣","c":["我还欠？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"般涉调・哨遍高祖还乡","p":"","d":"元代","a":"睢景臣","c":["社长排门告示，但有的差使无推故。", "这差使不寻俗，一壁厢纳草也恨，一边又要差夫，索应付。", "又言是车驾，都说是銮舆，今日还乡故。", "王乡老执定瓦台盘，赵忙郎抱着酒胡芦。", "新刷来的头巾，恰糨来的绸衫，畅好是妆么大户。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"耍孩儿・瞎王留引定火乔男女，胡踢蹬吹笛擂鼓。见一风彡人马到庄门，","p":"","d":"元代","a":"睢景臣","c":["匹头里几面旗舒：一面旗白胡阑套住个迎霜兔，一面旗红曲连打着个毕月乌，一面旗鸡学舞，一面旗狗生双翅，一面旗蛇缠胡芦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四・辕条上都是马，套顶上不见驴，黄罗伞柄天生曲。车前八个天曹判，","p":"","d":"元代","a":"睢景臣","c":["车后若干递送夫。", "更几个多娇女，一般穿着，一样妆梳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三・那大汉下的车，众人施礼数，那大汉觑得人如无物。众乡老展脚舒腰","p":"","d":"元代","a":"睢景臣","c":["拜，那大汉那身着手扶。", "猛可里抬头觑，觑多时认得，险气破我胸脯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"二・你须身姓刘，您妻须姓吕，把你两家儿根脚从头数。你本身做亭长耽","p":"","d":"元代","a":"睢景臣","c":["几盏酒，你丈人教村学读几卷书。", "曾在俺庄东住，也曾与我喂牛切草，拽坝扶锄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一・春采了桑，冬借了俺粟，零支了米麦无重数。换田契强秤了麻三秤，","p":"","d":"元代","a":"睢景臣","c":["还酒债偷量了豆几斛。", "有甚胡突处？明标着册历，见放着文书。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・少我的钱，差发内旋拨还；我的粟，税粮中私准除。只道刘三，谁肯","p":"","d":"元代","a":"睢景臣","c":["把你揪ㄏ住？白甚么改了姓更了名唤做汉高祖！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"商角调・黄莺儿寓僧舍","p":"","d":"元代","a":"睢景臣","c":["秋色，秋色，几声悲怆，孤鸿出塞。", "满园林野火烘霞，荷枯柳败。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"踏莎行・水馆烟中，暮山云外，泊孤舟古渡侧。息风霾，净尘埃，宝刹清","p":"","d":"元代","a":"睢景臣","c":["凉境界。", "僧相待，借眠何碍？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"垂丝钓・风清月白，有感心酸不耐。更触目凄凉，景物供将愁闷来。月被","p":"","d":"元代","a":"睢景臣","c":["云埋，风鸣在籁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"应天长・僧舍窄，蚊帐矮，独拥单衾，一宵如半载。旧恨新愁深似海。情","p":"","d":"元代","a":"睢景臣","c":["缘在，人无奈，几般儿可怪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"随煞・促织絮恼情怀，砧杵韵无聊赖。檐马奢殿铎鸣，疏雨滴西风煞，能","p":"","d":"元代","a":"睢景臣","c":["断送楚台云，会禁持异乡客。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"正宫・黑漆弩村居遣兴","p":"","d":"元代","a":"刘敏中","c":["长巾阔领深村住，不识我唤作伧父。", "掩白沙翠竹柴门，听彻秋来夜雨。", "闲将得失思量，往事水流东去。", "便宜教画却凌烟，甚是功名了处。", "吾庐却近江鸥住，更几个好事农父。", "对青山枕上诗成，一阵沙头风雨。", "酒旗只隔横塘，自过小桥沽去。", "尽疏狂不怕人嫌，是我生平喜处。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・上小楼","p":"","d":"元代","a":"李文蔚","c":["家住在深日旷野，又无有东邻西舍，好吃的是野杏山桃，淡饭黄齑，竹笋茶叶。", "俺那里人烟稀，鸟声绝，灯消火灭，伴了些树梢头晓星残月。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・上小楼","p":"","d":"元代","a":"李文蔚","c":["家住在深山里头，好吃的是牛肉羊肉，闲来时打家截盗，剜墙□窟，盗马偷牛。", "枪杆子，大闷棍，鹅卵石头，这的是俺出家人苦修争斗。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・上小楼","p":"","d":"元代","a":"李文蔚","c":["不怕你王法有条，也不怕丹书来召，也不怕昼夜，十二个时辰，涌出枪刀。", "一毒蛇，二大虫，豺狼当道，也不怕猛狮子狼熊虎豹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・上小楼","p":"","d":"元代","a":"李文蔚","c":["休笑我贪花恋酒，酒里头把玄机参透，酒中得道，花里神仙，自古传留。", "炼丹砂，九转成，通身不漏，直修的来无生死与天齐寿。", "(云)贫道是这无天之外，有影无形，风里来，云里去，闻不见，摸不着，道号扯虚，表字托空是也。", "今日无甚事，游山玩水，走一遭去。", "(做见正末科，云)此人乃是张良，忠孝双全，迷踪失路。", "我指与他一条大路者。", "(正末云)这一会儿雪越大了也，又无一个人来往，不知那里是人行的大路，雪迷了遍野，可怎生了也！(正末见虎惊科，云)兀的不是个斑斓大虫？谁人救的我性命也呵！(乔仙做唤科，云)张良，你怕么？你敢迷踪失路？我是大罗活神仙也。", "(正末云)师父，救小生性命咱。", "(乔仙云)你要我救你性命？你可也有缘，我救你。", "（正末云）师父是那一位神仙？(乔仙云）你不认的我，我是上八洞神仙。", "(正末云)师父指与我个正路，又有大虫拦路，怕伤了我的性命，师父救我的性命咱！(乔仙云)你要我救你，我有个曲儿，是〔朝天子〕。", "我临了那一句，我说\"你要我救你么\"？你说\"要你救我\"，我就救你。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・醉扶归","p":"","d":"元代","a":"李文蔚","c":["我见一个老叟亲来到，(太白云)兀那张良，你的性命，实是难逃也！(正末唱)他道我性命怎生逃，(太白云)便着人拿住张良者。", "(正末云)老尊长救性命咱。", "(唱)唬的我胆战心惊魂魄消。", "(太白云)兀那张良，这等风雪，如何不行动些？(正末唱)我这里迷却经尘道，(太白云)你来到俺这里，你走如何的往那里去？(正末唱)告你个老尊长将咱来且饶。", "(太白云)张良，我待救你这一命，你可是如何？(正末云)若是救了我的性命呵，(唱)久以后将你这救我命的恩临报。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・后庭花","p":"","d":"元代","a":"李文蔚","c":["五世在韩邦衣紫袍，俺端的可便受深恩享重爵，都则为赢政收俺家国，(云)谁想击之不中也。", "(唱)我因此上我便离乡可也背井逃。", "(太白云)你再有何所干？(正末唱)我这里说根苗，我如今迷了他这大道。", "我向这土坡前膝跪前，可怜见咱命夭，衣不遮身上薄，食不能腹内饱，食不能腹内饱。", "(太白云)张良，我说与你，千经万典，不如忠孝为先。", "你既省的，你说，我试听者。", "张良，你尽忠可是如何也？(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・青哥儿","p":"","d":"元代","a":"李文蔚","c":["尽忠呵，须把这皇恩、皇恩答报，(太白云)尽孝呵，可是怎生？(正末唱)尽孝呵，想着我哀哀父母劬劳。", "尽忠呵，也则要竭力侍君王辅圣朝，敢则要俺动合王道。", "正直臣僚，禄重官高，伞盖飘飘，播万古千秋、万古千秋的把名标。", "这的是为臣子行忠孝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・尾声","p":"","d":"元代","a":"李文蔚","c":["疾便的践程途，寻俺那下邳的长安道，岂避这路远山高水迢，又不比蜀道嵯峨山险恶。", "若是留的我性命坚牢，有一日作臣僚，独步青霄，方显男儿志气高。", "凭着我满胸襟踊跃，有一日运通时到。", "(云)异日时运通达呵，(唱)你看我便笑谈间，束带立于朝。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・南吕/一枝花","p":"","d":"元代","a":"李文蔚","c":["我本是一个贤门将相才，逃难在他乡外。", "空学的满腹中锦绣文，天也，则我这腹内恨几时开？忧的我鬓发斑白，甘贫贱，权宁耐，兀的不屈沉杀年少客！不能够揭天关，稳坐在青霄怎生来，忧的这俊英杰容颜渐改。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・梁州","p":"","d":"元代","a":"李文蔚","c":["几时得居八位，封侯可便建节？几时能够列三公画戟门排？我如今孤身流落在天涯外，本是个守忠义贤臣良将，倒做了背恩宠逆子之才。", "见如今沿门乞化，抵多少日转他那千阶！也是我命里合该，大刚来天数安排。", "我、我、我，几时得受皇恩，为卿相，列朝班，奉君王，独步金阶？我、我、我，几时得承宣命，封重职，坐都堂，镇边关的那境界？我、我、我，可几时能够居帅府，悬金印，持虎符，气昂昂走上坛台？凭着我胸襟气概，则我这风云庆会何年再？暂时困，权宁奈，倚仗着我这冠世文章星斗才，胸卷江淮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・隔尾","p":"","d":"元代","a":"李文蔚","c":["小生深蒙长者多怜爱，则你那救困的恩临我可也常在杯，(云)长者，似你这般仁德之心，无人可比也。", "(唱)你胜如那赵盾的心情将我似灵辄待。", "有一日若用我安邦的手策，但得一个微名的县宰，长者也，我答报你个布德施恩大贤客。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・牧羊关","p":"","d":"元代","a":"李文蔚","c":["你将那《周易》从头论，将我这贵与贱仔细排，(福星云)张良，你问贵贱？这贫与富，是人之所作；贫者不善之因，富者积善所致也。", "此乃是贫富之因。", "(正末唱)我问官禄子息和这家财。", "你看我命里有，可是我去未通达，盖因是命里无，这年月上不该。", "(福星云)你如今多大年纪？何年何月何日何时建生？你说将来。", "(正末唱)我拙年恰三十岁，我是那五月午时胎。", "且将我今岁行年算，先生也，你将我这贫与贵一一开。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・四块玉","p":"","d":"元代","a":"李文蔚","c":["我这里便缓步行，来到这圯桥侧。", "(黄石公做见科，云)兀的不是孺子张良？我唤他一声。", "(做唤科，云)兀那孺子张良！(正末唱)是谁人便道姓呼名自疑猜，我索与你探行藏问端的何妨碍。", "(黄石公做笑科)(正末云)我试望咱。", "是谁唤我也呵！(做回身科)(黄石公又笑科)(正末云)呀呀呀！一个须发尽白的老先生，好道貌也！(唱)我见他年高两鬓苍，他髭须一似银丝般白，他生来实丰彩。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・牧羊关","p":"","d":"元代","a":"李文蔚","c":["你着我待忍来如何忍，他看承的我如小哉，不由我嗔忿忿气夯破我这胸怀。", "我仿学那豫让般忠孝无嗔，我似那廉颇般避车路，我索与你躬身儿下阶。", "(云)张良也，你是个看书的人，岂不闻圣人云：\"老者安之，少者怀之，朋友信之？\"此乃为人之所作也。", "(唱)古人言敬老幼，恤孤困。", "(云)想小生离了家乡，逃难到于途中，迷踪失路，神灵指引，着我往下邳避灾，\"必有教授你之师\"。", "今日长街市上算了一卦，说道我今朝日当卓午，必遇名师也。", "(唱)这一个老先生敢是那教训我的祖师来。", "想着我离故邦受辛苦言难尽，张良也你正是成人的可也不自在。", "(黄石公云)孺子，与我取上履来者。", "(正末做取履科)(黄石公做伸足穿履科，云)此子可教，则除是恁的。", "(觑正末科，云)兀那孺子张良，你可也有缘，我与你约五日之期，再来此圯桥等候。", "我要为你徒弟，我传与你安身之法，休失其信也。", "我去也，我去也。", "(下)(正末云)师父言道，与我约五日之期，再来此圯桥相会，要传我安身显耀之术。", "张良，你信他做甚么？此言难以凭信。", "天色晚了也，我索还家去。", "(下)(黄石公再上，云)贫道黄石公是也。", "与张良约五日之期，再来圯桥相会，可早五日也。", "则怕张良等待，贫道行动些。", "孺子张良！(做怒科，云)此孺子好无礼也。", "我要教授他做徒弟，约五日之期，来此圯桥相会，传与他安身显耀之法，不想此孺子不曾来，好是无缘也。", "我待回去来，此子则说我失信。", "喑！我且等他片时。", "(正末上，云)小生张良，自五日之前，见了那个先生，他口口声声唤我做\"孺子、孺子\"，约我五日之期，要传与我安身之法。", "我待去来，着人便道他是个风魔先生，他有甚么安身之法？我待不去来，则怕那个先生等待我。", "不可失信，我索行动些。", "说话中间，可早来到圯桥也。", "(做见惊科，云)兀的不是那个风魔先生？果然在此，好是奇怪也。", "(黄石公做见正末怒科，云)兀那孺子张良，我约你五日之期，早来这圯桥相会，我要你为徒弟。", "不想你这厮无缘，这早晚才来，好无恭敬之念也！(正末云)师父息怒、息怒。", "(黄石公元)兀那孺子，你听者！我再约你五日之期，径来此圯桥相会，我传与你安邦定国之书，久已后可为万代之师。", "我着你声播千邦，名扬天下。", "这一遍若是再来的迟，二罪俱罚，我也不饶你！我去也。", "(下)(正末云)先生去了也。", "张良也，要你寻思，你道他是风魔先生来，他说如此般良言。", "头一遍偶遇，第二遍来的迟了。", "师父言称道：\"孺子张良，再约五日之期，来圯桥相会，我传与你安邦定国之书，久已后可为万代之师。", "我着你声播千邦，名扬天下。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・乌夜鸣","p":"","d":"元代","a":"李文蔚","c":["又不曾梦非熊得遇文王侧，莫不是鬼使神差，不由我喜笑盈腮。", "今日个蛰龙须得济时来，谢吾师展脚舒腰拜。", "(云)小生张良，异日发达，此训授之恩，必当重报也。", "(唱)我若是得发达身安泰，有一日春雷信动，枯木花开。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・鹌鹑儿","p":"","d":"元代","a":"李文蔚","c":["又不曾效傅说版筑在岩墙，偶然遇殷高到来，我若是立国安邦，可用这兵书战策，我学那周武八元以承八恺，调鼎鼐，明盛衰。", "有一日胸卷江淮，平步金阶，把日月重揩，肃靖边界，扶持着治世的明君，保祚的乾坤永泰。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・尾声","p":"","d":"元代","a":"李文蔚","c":["罢、罢、罢，我则索用工夫看彻了黄公策，我与你无明夜时时的温故知新不放怀。", "谢尊师，承顾爱，教训咱，意无歹。", "漫天机，我将做谜也似猜。", "想当初报韩仇，命运乖，则我这尽忠心，意长在。", "那时节离家乡，躲避灾。", "至下邳，有谁睬。", "我今日遇神师，得术册，(云)若是我投于任贤之处，若委用我呵，(唱)我看我辅皇朝，定边塞，保乾坤，整世界，展江山，平四海。", "则我胸中学，腹内才，辨风云，知气色。", "我若是作臣僚，为元帅，掌军权，在阃外，抚黔黎，定蛮貊，逞英雄，显气概，播声名，传万载。", "遂了我这平生志，拂满面尘埃，恁时节才识这晓经纶安宇宙这一个困穷儒也一个少年客。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・仙吕/赏花时","p":"","d":"元代","a":"李文蔚","c":["则我这行色匆匆去意紧，饮过这钱祖香醪杯数巡。", "(长者云)贤士，这一去必然称平生之愿也。", "(正末云)张良异日峥嵘呵，(唱)我若是得志节遂风云，(云)长者之恩，高如华岳，深如沧海，岂敢忘也？(长者云)不必挂念，岂望贤士报乎？(正末唱)我说的言辞落可便有准，(云)长者言之当也。", "但念善犬有展草之恩，良马有垂缰之报，禽兽尚然如此，何况为人而不知恩乎？(长者云)贤士休说如此言语，不劳持意，稳登前路也。", "(正末唱)我报答你个救困苦的这个大恩人。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・正宫/端正好","p":"","d":"元代","a":"李文蔚","c":["我今为宰职便做都堂，我端的便受极品为卿，扫奸邪平定边疆。", "我本是整乾坤安宇宙良将，保祚的这万里山河壮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・滚绣球","p":"","d":"元代","a":"李文蔚","c":["想着我当年时离了俺那父母乡，报韩仇那一场，也是那命运乖祸从天降。", "我今日遂风云称平生显身荣节志昂昂，第一来与韩邦报了恨仇，第二来扶炎刘名姓香。", "你看我整风俗遵礼乐治安乾象，我今日乘肥马衣轻裘，享天恩紫绶金章，本是个股肱才辅弼平蛮貊，扫荡了八面烟尘可兀的定四方，后世名扬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・倘秀才","p":"","d":"元代","a":"李文蔚","c":["我待学那周八士安八表封官也那受赏，(萧何云)军师再学那一个也？(正末唱)我似那舜五人立清政显声名播千古，着万人可便论讲。", "(萧何云)再学那个也？(正末唱)我胜如纣比干田穰苴，报国存忠壮帝乡。", "(萧何云)军师，说此申阳足智多谋，难以擒拿也。", "(正末唱)俺有道伐无道，(萧何云)军师，小官须索整点英雄将士，里应外合擒拿他，有何不可也？(正末唱)擒逆子不索动刀枪，(萧何云)军师言道不用军将人马，此人好生英勇，则怕有失，怎了也？(正末唱)非是我自夸也那自奖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・滚绣球","p":"","d":"元代","a":"李文蔚","c":["论三略呵，我可也动干戈起战场，(韩信云)军师论六韬呵怎生？(正末唱)论六韬，我学那定山河保乾坤伐无道的姜吕望，(韩信云)论机见可学谁也？(正末唱)论机见呵，我似那齐孙膑报冤仇在马陵川夜擒了那一员虎将，(韩信云)论敢勇可学谁也？(正末唱)论敢勇呵，我似那楚伍员伏盗跖赴临潼举金鼎欺文武保诸侯逞英豪状貌堂堂，(韩信云)军师论慷慨呵学谁？(正末唱)论慷慨，仿李牧守塞北慑西戎镇夜郎，(韩信云)论志气可学谁也？(正末唱)论志气呵，我胜如管夷吾霸诸侯那手策威名不让，(韩信云)敢问军师，论节义可学谁也？(正末唱)论节义呵，我学那存忠孝施正礼行仁道治纲常伊尹扶汤，(韩信云)论勇跃学谁也？(正末唱)论勇跃，我不让蔺相如在渑池会展雄才施威烈可那般志轩昂，(韩信云)论战敌可学谁也？(正末唱)论战敌呵，我不让齐田单火牛阵，施遁甲用奇术，排军校驱虎将。", "他收那即墨城开，我着他拱手降，(韩信云)此言壮哉也。", "(正末唱)非是我自说高强。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・倘秀才","p":"","d":"元代","a":"李文蔚","c":["我这里便鞠躬躬将谦词礼讲，(申阳云)兀那先生，你姓甚名谁也？(正末唱)他那里问姓字先生可便何往，我可也行不更名本姓张。", "(申阳云)你敢是张良么？(正末云)然也，然也。", "(陆贾云)此人是说客，元帅休得饶他也。", "(申阳云)兀那张良，你是喉舌之人，你佐于沛公手下为将，你来俺这里做甚么？(正末云)贫道非是沛公之将，乃韩国阜城人氏，因打此处经过，闻知元帅才德，特来见访也。", "(申阳云)小校，与我拿住张良，我决无轻恕也。", "(正末唱)他一回儿嗔忿忿冲牛斗，施勇烈逞高强，(申阳云)大小众将，与我围住张良者！(正末唱)他显八面虎狼般气象。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・呆骨朵","p":"","d":"元代","a":"李文蔚","c":["枉了我那区区千里亲身降，(申阳云)兀那张良，你心怀徼幸，有所害俺之意，如何饶免的你也！(正末唱)我又不曾怀奸谗徼幸的心肠。", "(申阳云)想汝实是无礼，我和你素不相识，你既不为说客，你来俺这里，有何事干？更待干罢也！(正末唱)他一回儿忿怒生嗔，心劳意穰。", "(申阳云)你恰才所言申包胥哭秦亭一事，侯嬴收赵，文简受资，图财图国，言中之计，话内之机，你比这三人更不同也！在某根前，如何说的过？(正末唱)我又不比那邹文简共侯嬴两个奸雄将，(申阳云)你既为不说客，你来俺这里，有甚么勾当也？(正末唱)我端的可便为贤才到于鸟兽邦，(申阳云)你何处而来也。", "(正末唱)因此上便访忠良离帝乡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・货郎儿","p":"","d":"元代","a":"李文蔚","c":["猛听的吹画角悠悠的便嘹亮，他道俺接应的军排战场。", "(陆贾云)项庄将军，俺一同的见鲁公去来。", "(正末唱)他那里探知就里可便问其详。", "大将军何名姓？(陆贾云)项庄将军，俺用千般之计，拿住张良，献与鲁公，请功受赏也。", "(正末唱)他拿住的是张良。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・脱布衫","p":"","d":"元代","a":"李文蔚","c":["他教我言端的细说行藏，(陆贾云)张良勿得多言，见鲁公受降去来。", "(正末唱)休言语献楚投降。", "(云)将军饶性命咱。", "(唱)我这里忙哀告饶咱性命，(陆贾云)既然拿住你也，怎生饶的过！(正末唱)他道既拿住怎生轻放。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・醉太平","p":"","d":"元代","a":"李文蔚","c":["他那里孜孜觑当，(灌婴云)军师休怕，申阳陆贾二将，如何出得俺手也。", "(正末唱)唬的我战兢兢手脚慌张。", "(灌婴云)此将中俺之计也。", "(正末唱)说道是中吾计不索再商量，(灌婴云)俺韩元帅领大势雄兵来接应也。", "(正末唱)又道是兵多将广，(灌婴云)此陆贾并无疑虑之心也。", "(正末唱)你道是申阳陆贾别无恙，(灌婴云)若到半途，必然下手也。", "(正末唱)到半途暗暗拿雄将。", "(灌婴云)想二将不知俺暗定其计也。", "(正末唱)他本待要望福禄，不想到这脑背后起灾殃。", "我则待坚心扶立明圣主，我播一个《史记》内便书名，可着人慢慢的讲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・尾声","p":"","d":"元代","a":"李文蔚","c":["俺今日敲金镫将得胜歌必索齐声唱，俺须索践程途喜孜孜军兵出战场。", "则今番有名望，擒收了三猛将，将功劳上表章，把军情慢慢的讲。", "功勋籍写数行，入凌烟金榜上，作臣僚入庙堂，恁时节受爵封官，那其间论功赏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・双调/新水令","p":"","d":"元代","a":"李文蔚","c":["则俺这一班儿整乾坤众英豪，都是那股肱才要保安宗庙。", "论机术效管乐，论智勇有谁学，千古名标。", "我则待行仁德，顺天道。", "(云)说话中间，可早来到帅府门首也。", "小校报复去，道有张良在于门首也。", "(卒子云)理会的。", "(做报科，云)喏，报的元帅得知，有军师来了也。", "军师路途辛苦，擒拿二将用心也。", "(正末云)元帅守府不易也。", "(韩信云)军师请见众将也。", "(正末做见众将科，云)您众将都来全了也。", "近前来，今日元帅奉命宴赏，各论其功也。", "(韩信云)军师，韩信敢问么？当日您众将辞了朝，到的洛阳，怎生用智收捕二将？军师，你试说一遍咱。", "(正末云)小官当日离了丞相、元帅，到的洛阳，见了申阳，将微言所说，未曾举口，申阳半军可早怒生两肋，发乍冲冠。", "申阳将军言道：\"项羽有命：拿住张良者，千金加赏，万户封侯！\"就将某献与项羽，请功受赏。", "小官略使小计，遣数将定计铺谋，吊申阳擒出陆贾也。", "为贤良千里驱驰，用千般智略心机。", "申阳你若是秉忠贞坚心辅佐，陆贾我着您承恩禄荫子封妻。", "(韩信云)军师，想着你于国尽忠，多有功劳也。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・沉醉东风","p":"","d":"元代","a":"李文蔚","c":["我若是忠心报君恩重爵，立功勋《史记》名标。", "灵禽相良木栖，辅圣主行仁道，俺则愿的泰阶平，风雨时调。", "见如今四海黎民歌舜尧，俺可便共享升平到老。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张子房圯桥进履・水仙子","p":"","d":"元代","a":"李文蔚","c":["金杯满注捧香醪，品味珍羞盘内托，则听的仙音一派多奇妙，比俺那凯歌声音韵好。", "受天恩赐宴难消。", "君主德过禹舜，正人伦尊礼乐，恩宽厚胜似汤尧。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕・解三酲","p":"","d":"元代","a":"真氏","c":["奴本是明珠擎掌，怎生的流落平康？对人前乔做作娇模样，背地里泪千行。", "三春南国怜飘荡，一事东风没主张，添悲怆，那里有珍珠十斛，来赎云娘！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・仙吕/赏花时","p":"","d":"元代","a":"无名氏","c":["我和这货卜的先生可在这路上逢，他恰才上下端详观了我这面容。", "(太白云)据富贵不在石崇之下也。", "(正末唱)他道我据富贵若石崇，(太白云)争奈你寿夭也。", "(正末唱)争奈我其寿可也不永，(太白云)你有多资财，则是少个儿童也。", "(正末唱)他又道我多财禄更少个儿童。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・仙吕/点绛唇","p":"","d":"元代","a":"无名氏","c":["我本是个巨富的明儒。", "开着座济贫的典库为财主。", "贯满京都，掌着那万万贯的这多财物。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・混江龙","p":"","d":"元代","a":"无名氏","c":["想咱这人贫人富，原来这天公暗里自乘除。", "(带云)想咱这世间人，有钱的却天子，有子的却无钱。", "婆婆，这个道理，你省的么？有甚么难见处。", "(唱)贫的每多生些子嗣，咱这富的每便广积些金珠。", "则为那贫无这谄以误收的些存子的法，咱则被富之余也兀的不明放着一个杀身的术。", "这世里甘贫的无虑，越富的贪图，饥贫的广有，猛富的多余。", "我想那嫌贫的彼富。", "爱富的愚夫，固穷的不滥，靠富的空虚。", "我则待守清贫得乐矣在其中，端的可便不义富我道来于我也则是如云雾。", "咱这人眼前贫波富，可则也则是兀那枕上的这荣枯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・天下乐","p":"","d":"元代","a":"无名氏","c":["噤声！贼也，岂不闻道财上分明大丈夫。", "(云)比喻说到今月初一日，把这号改到那月初二来赎。", "你这厮！(唱)但那日数儿过来波余，你休想道肯放那赎，(云)初二日来赎，道员外不在解典库里，明日来。", "不付能到那初三日来赎，你道员外人情去了，不在家。", "(唱)这厮兀那爱钱的心他百般里推些个事故。", "(卜儿云)老的，他为甚么那？(正末唱)他则待日要所增，(云)初三日不赎与那人，初四合当赎与那人，你又不赎与他。", "婆婆，你知道他那初四日不赎与那人的缘故么？(卜儿云)可更是怎生？(正末唱)这厮直熬到个月不过五，(云)过了五个日头。", "索你怎生问他要一个月的利钱？贼丑生也！(唱)你倚仗着我这几贯钱索则么以扌勒的些穷人家每着他无是处。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・那吒令","p":"","d":"元代","a":"无名氏","c":["你待陪千言万语，托十亲九故，娶三妻两妇，待望一男半女。", "(卜儿云)老的，你娶一个罢波。", "(正末云)日月逝矣，岁不我延。", "(唱)我青镜晓来看，则这白发添无数，(云)我如今不小也。", "(唱)我如今暮景桑榆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・鹊踏枝","p":"","d":"元代","a":"无名氏","c":["我要一个家厮儿无，我要一个家女儿无。", "(云)天若可怜见刘弘，或儿或女，降与刘弘一个。", "果若刘弘无那儿女的分福，索一头的生将下来，就在那褥草上便着天厌了者波。", "(唱)天也，我问甚么那跛臂瘸臁，者么他那眼瞎头秃。", "(卜儿云)员外甫能得一个，又眼瞎头秃，不如不要也。", "(正末云)婆婆，你道的差了也。", "(唱)则但能够便替咱去上坟波祭祖，大嫂也，也强如咱眼睁睁鳏寡孤独。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・醉中天","p":"","d":"元代","a":"无名氏","c":["我这里先把封皮来去，展放开他这个寄来的书。", "(云)大嫂，不曾掉下一张？(卜儿云)员外，不曾掉下。", "(正末云)小大哥，你近前来，我问你，则这一封书，索别有书呈？(李春郎云)伯父，止则是这一封书，别无书呈。", "(正末云)既是这等呵，你且靠后些。", "好是奇怪也呵！(唱)却怎生彻尾从头一字无？(云)李克让也，你既是我的兄弟呵。", "(唱)你却怎生不把这寒温来叙？你将着这雪白纸呵？也好，也好，咱知他的意趣，你那满怀的心腹事，这汉向我行十分的诉。", "(云)婆婆，你省的这个礼么？则这一张白纸，我便见出那人的心来。", "白纸二字，白者是素也，纸者是居也。", "他与我素不相识，着他写甚么的是。", "纸者是居也，正意的那则是托妻寄子与我。", "婆婆，市廛中那老先生道甚么来？他道着俺行好事，积阴功。", "今日这般善事上门也，咱不可以不行也。", "(卜儿云)员外，凡百的事，则随你主意也。", "(正末云)则除是这般。", "小大哥，近前来，你休作疑惑，听我说与你。", "想你那亡父在时节，曾和我作经商买卖，一席酒之间，我和他言行相投。", "他曾拜我八拜，我为兄，他为弟，不想今日兄弟不幸身亡了也。", "您子母儿每，来的正好，休别处去，则在家里住。", "(李春郎云)谢了伯父。", "(正末云)你那亡父的灰榇儿在那里？(李春郎云)见在南薰门外报恩寺里寄着哩。", "(正末去)王秀才，你便与我南薰门外将那李克让的骨榇儿取将来，高原选地，破木造棺，建起坟茔呵，我自有个祭祀的礼物。", "(净王秀才云)下次小的每，便去南薰门外报恩寺里，取将李克让那把骨殖来。", "若取将来，我自有个埋殡的道理。", "(正末云)小大哥，你那清德唤做甚么？(李春郎云)您孩儿是李春郎。", "(正末云)这个是你的胎讳，你那清德呢？(李春郎云)伯父跟前，怎敢称呼表德？(正末云)怕做甚么。", "(李春郎云)您孩儿李彦清。", "(正末云)好、好、好。", "你那亡父在时节，曾叫你学甚么艺业来？(李春郎云)亡父在日，着您孩儿攻书来。", "(正末云)便好道万般皆下品，惟有读书高。", "(李春郎云)不是您孩儿说大言，天下文章一石，您孩儿颇揽九斗九升在怀。", "(净王秀才云)好哥，你快走。", "管的他穿，管不的他吃。", "(正末云)怎的？(净王秀才云)你不听的他说，他那一顿吃九斗九升哩。", "(正末云)他说他那文章哩。", "(净王秀才云)三个夏布做一顶。", "(正末云)怎的？(净王秀才云)你说蚊帐。", "(正末云)他说他那文字哩。", "(净王秀才云)这两日虼蚤丁出屁来，又蚊子。", "(正末云)小大哥，或诗或词，作一首来我看。", "(李春郎云)伯父指甚为题？(正末云)单指着您子母二人投奔我，便是。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・尾声","p":"","d":"元代","a":"无名氏","c":["咱人这生死也在于天，端的这善恶也由人做，我则是可怜见他孤寒的子母。", "(云)洛阳城中许多的财主，他怎生不别人家去？(唱)岂不闻投人须投大丈夫，(卜儿云)着他子母二人回去罢。", "(正末唱)不争咱赶离了门显的咱也不辨一个贤愚。", "(卜儿云)员外，赍发他些钱物，着他回去罢。", "(正末唱)我本待与些钱物，也则是济惠他这穷儒，则这的便是将有余儿可也补不是。", "(卜儿云)员外，似俺两口儿这等受用快活，可也强似他子母每也。", "(正末云)婆婆，咱两口儿为人，不如他子母儿每，他子母儿每强似咱。", "(唱)我如今空盖下他这般画堂锦屋，眼前面折罚的咱来灭门波绝户。", "(云)古人言：有钱无子非为贵，他这等有子无钱的，也不是贫。", "咱人一日死到头来，休说是这些个家缘，(唱)便设若堆金到那北斗，(云)婆婆，咱死时节，将的去么，(唱)可则那的也待何如。", "(正末同众下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・中吕/粉蝶儿","p":"","d":"元代","a":"无名氏","c":["那相士观觑了我这容仪，他道我寿不及那五十余岁，(带云)天那！想刘弘两口儿为人，也不曾行那歹也。", "(唱)莫不我与人交有甚么言行相违？(带云)不是我自谄。", "(唱)俺一家儿夫怜贫，更和这妻敬老，俺又不曾道是欺瞒着天地。", "天网恢恢。", "我一会家想穹苍也有一个偏僻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・醉春风","p":"","d":"元代","a":"无名氏","c":["既不索可怎生短命死了颜回，却怎生延年老了盗跖？我想那鹤长凫短不能齐，(云)想咱这世间的人，有钱的却无子，有子的却无钱。", "婆婆，这个道理，你省的么？(唱)百般的参不透这个道理。", "况这世里完备有几，刘弘我道来绝嗣的不似你。", "当日那伯道无儿，似这等古人也乏嗣，何况道是小生我这些个绝继。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・白鹤子","p":"","d":"元代","a":"无名氏","c":["这孩儿为无钱缺着葬礼，他卖身体置那坟围。", "这孩儿他知重情可便敬那爷娘，这孩儿孝感意便惊大地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・幺篇","p":"","d":"元代","a":"无名氏","c":["这孩儿赛杨香跨虎心，有贾氏斩龙计。", "方信道赵贞女罗裙包土可也筑坟台，我可寻那曹蛾女觅父投江水。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・上小楼","p":"","d":"元代","a":"无名氏","c":["大嫂也你从来可便三从四德。", "这孩儿他千娇百媚。", "你看那牙似瓠犀，颈若蝤蛴，手似柔荑。", "你看他那绀发齐，绿鬓堆，高盘云髻，(带云)一天的那秀气，都生在这个姐姐身上。", "(唱)则是一个玉天仙可便降临在凡世。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・幺篇","p":"","d":"元代","a":"无名氏","c":["你那梳洗处着架手巾，筵席上系护衣。", "你待着他担水运浆，搬茶供饭，你又待着他过盏波擎杯。", "这孩儿，则恁的，闲立地，呵，更那堪他便娇柔波无力？(带云)你好是狠毒也呵。", "(唱)怎下的着他拈轻掇重，可便扫床也波叠被？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・快活三","p":"","d":"元代","a":"无名氏","c":["则这陪缘房是咱的志气，配良姻是我的阴骘。", "咱这般疏财仗义礼当宜，(带云)咱两口儿做着这般善事，着那外人说出去呵。", "(唱)显的我这夫克己你个妻贤惠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・朝天子","p":"","d":"元代","a":"无名氏","c":["白纸上虽无甚么墨迹，既然他每寄子波那托妻，今日个便伊同咱两个便为了这交契。", "(带云)既是和咱做了亲眷，也索。", "(唱)俺必索那倾心吐胆将他厮惠济。", "(带云)一个婚姻，一个是死葬，咱将着那金子银子，那里寻这般好勾当做去来也。", "(唱)若是我便顺着人的情呵，也是我便合着这天意。", "(旦儿做悲科，云)伯伯、伯娘，媳妇儿也不敢要，则今日辞别了伯伯、伯娘，俺子母二人回去也。", "(正末云)婶子儿，并不曾说甚么言语，我和您伯娘，商量小姐的奁房断送，并不曾说甚么言语，婶子儿省烦恼。", "(正末做见卜儿科，云)我问你，这凡百的一家人家，有个家长么？莫不俺这男子汉主了的这桩勾当，信着你这等的言语，肯则那等干罢了么？我做了的那好勾当，着你这几句话波，兀的不坏尽了也。", "我问你，那的是你那三从四德？则这的便是你那三从四德不是？为孩儿每这些喜庆的勾当，你则再言语，我就不信也。", "(卜儿云)俺和他是甚么亲？(正末云)婶子儿，可止不过您伯娘有些闲言剩语道了呵，我肯依的他来？李春郎孩儿也，咱本是一重儿亲来，因着小姐面上，咱越亲波越厚了也。", "(唱)从今后你个婶子儿，(带云)春郎，(唱)和你个侄儿咱可都是一家一计。", "(卜儿扳正末科，云)凡百事好歹有个商量。", "(正末唱)你好不会做那人也，则到如今也索更争甚么我波那共你。", "(净王秀才云)我本待不说来，气忄敝破我这肚皮。", "他姓甚么？你姓甚么？(正末云)贼丑生，干你甚事？(唱)论甚么姓刘也那姓李，(净王秀才云)他在那里住？你在那里住？(正末唱)不在于你，也者么他住在江南也那塞北，(净王秀才云)拿将一张白纸来，知他是甚么亲眷，也不似你忒独主。", "(正末云)噤声，贼丑生也。", "(唱)岂不闻道四海内皆是兄弟？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・耍孩儿","p":"","d":"元代","a":"无名氏","c":["即来托我为交契，我不曾见伊家面皮。", "你和咱素日不相识，知道也那临危向妻子行留遗。", "(云)你和我做兄弟。", "(唱)凭着这半张白纸为交友，隔着这千里关山厮认义。", "我明知你是容妻子安身计，他知我恤孤念寡，救困扶危。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・四煞","p":"","d":"元代","a":"无名氏","c":["一封书寄与咱，你夫情我尽知。", "今日红妆共秀才，您两个为门对。", "岂不闻书中有女颜如玉，路上行人口胜碑。", "君子喻于义，也强如巡寺院布施与钱物，绕庙宇祷告神祗。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・三煞","p":"","d":"元代","a":"无名氏","c":["他祖宗是官宦家，他父亲为宰相职。", "他今日卖身不幸到咱家里，与你个贤达的婶子儿为儿妇，我配你个清俊的书生作正妻。", "你可休觑的微贱看的容易，莫把这堂中珍宝，你可休看承做墙上泥皮。", "(李春郎云)则今日好日辰，上朝求官应举，走一遭去。", "(正末云)春郎，到的帝都阙下，则要你着志者。", "(李春郎云)放心，你儿这一去，好歹要中科名也。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・二煞","p":"","d":"元代","a":"无名氏","c":["想着那对寒窗受苦辛，跳龙门夺富贵。", "九经三史从头垒，万言长策朝中献，一举成名天下知。", "有一日身及第，头直上打一轮皂盖，马头前列两行朱衣。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・尾声","p":"","d":"元代","a":"无名氏","c":["则要你频频的我根前寄一纸书。", "(李春郎云)伯父，孩儿知道，(正末云)你若到的帝都阙下，缺少盘缠，怕你写不及书信呵，你则道个口信来，老夫也教人捎些盘缠去。", "(唱)则要你常常的教我这两口儿知。", "(云)贪烦恼，却忘了安复婶子。", "婶子儿，这些时衣服茶饭供给不到处，是必休怪也。", "(唱)这些时应不到处可也是俺自家的礼，(李春郎云)伯父，此恩异日必当重报也。", "(正末云)孩儿，你休那般说。", "(唱)这恩念报不报知不知，哎，儿也，那的可不在于你。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・越调/斗鹌鹑","p":"","d":"元代","a":"无名氏","c":["则俺这顽子奇童，学儒人的秀士。", "他从那乳龀里胎龆，敢则是朝经暮史。", "他可便受辛苦十年，望功名也则半纸。", "这个小厮，是个好儿，他可便广览群书，多知故事。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・凭栏人","p":"","d":"元代","a":"无名氏","c":["今夜观书不待孜，忽的神魂好着我难动止。", "比及到更深宿睡时，我权且曲肱而枕之。", "(做睡科)(李逊同裴使君上)(李逊云)按落云头，可早来到也。", "尊神请。", "(裴使君云)尊神请。", "(李逊云)刘弘刘元溥。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・调笑令","p":"","d":"元代","a":"无名氏","c":["裴使君便是兰孙是你女孩儿，(裴使君云)俺一径的来报恩答义也。", "(正末唱)您两个为报恩临来到此。", "(李逊云)则为你夭寿乏嗣也。", "(正末唱)为咱家夭寿乏其嗣，(裴使君云)俺天庭上奏准明白了也。", "(正末唱)您去那天宫上保奏青词。", "从昨宵亲奉玉帝旨，(云)一个是增福神。", "(唱)这个为土地判断阴司。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・尾声","p":"","d":"元代","a":"无名氏","c":["若是你为官称了平生志，有一日大限临头那时。", "若你个小解元得为官，将你这双老爷娘放心死。", "(同众下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・双调/新水令","p":"","d":"元代","a":"无名氏","c":["人皆养子可便望聪明，俺孩儿自从那蒙童儿里上朝取应。", "当日那寒审下熬煎杀俺那小秀才，今日个贡院里欢喜杀俺老公卿。", "圣旨教御笔标名，俺孩儿白身里受朝命。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・水仙子","p":"","d":"元代","a":"无名氏","c":["龙楼凤阁九重城，新筑沙堤宰相行。", "白身世八位中除参政，将皇家俸禄请，十年前谁识你个书生。", "扫荡的蛮夷静，揩磨的日月明，从今后天下咸宁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・沽美酒","p":"","d":"元代","a":"无名氏","c":["多亏你个李彦清，(李春郎云)我举保奇童兄弟来。", "(正末唱)你便保举俺这小匡衡，则俺这张元伯多亏你个范巨卿。", "可俺托赖着当今圣明，依随着汉陈平。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・太平令","p":"","d":"元代","a":"无名氏","c":["将俺似王粲、梁鸿比并，把俺似那苏秦共傅说般看承，可俺又无那闵损、颜渊德行，端的更胜似吕望、甘罗封赠。", "(李春郎云)加你为洛阳县令之职也。", "(正末唱)遥受着洛京，县令，职名，圣人道积善之家必有余庆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"施仁义刘弘嫁婢・折桂令","p":"","d":"元代","a":"无名氏","c":["俺一家儿祭赛你个城隍增福威灵，(二神云)奇童皆是俺二神之功也。", "(正末唱)保护的俺十三岁蒙童，金榜上标名。", "(李逊云)吾神又将小女桂花，配与奇童为妻。", "则为你恤孤念寡，敬老怜贫，因此感动天地也。", "(正末唱)想当初都只为这个刘弘，腾云驾雾，直至天庭。", "(李逊云)奉上帝敕令，特来增福延寿也。", "(正末唱)您两个奏上帝把咱家寿增，保举的俺辈辈儿峥嵘。", "(云)圣贤那。", "(唱)量这一个愚鲁的鲰生，无德无能，俺一家儿礼拜磕头，感谢神明。", "(李逊、裴使君云)则为你积功累行阴功厚，布德施恩神天祜。", "则为你行尽仁义礼智信，今日个保全你那妻财子禄寿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・仙吕/赏花时","p":"","d":"元代","a":"王实甫","c":["俺姐姐针线无心不待拈，脂粉香消懒去添。", "春恨压眉尖，若得灵犀一点，敢医可了病恹恹。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・仙吕/点绛唇","p":"","d":"元代","a":"王实甫","c":["相国行祠，寄居萧寺。", "因丧事，幼女孤儿，欲将从军死。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・油葫芦","p":"","d":"元代","a":"王实甫","c":["憔悴潘郎鬓有丝；杜韦娘不似旧时，带围宽清减了瘦腰肢。", "一个睡昏昏不待观经史，一个意悬悬懒去拈针指；一个丝桐上调弄出离恨谱，一个花笺上删抹成断肠诗；一个笔下写幽情，一个弦上传心事：两下里都一样害相思。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・天下乐","p":"","d":"元代","a":"王实甫","c":["方信道才子佳人信有之，红娘看时，有些乖性儿，则怕有情人不遂心也似此。", "他害的有些抹媚，我遭着没三思，一纳头安排着憔悴死。", "却早来到书院里，我把唾津儿润破窗纸，看他在书房里做甚么。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・元和令","p":"","d":"元代","a":"王实甫","c":["金议敲门扇儿。", "(末云)是谁？(红唱)我是个散相思的五瘟使，俺小姐想着风清月朗夜深时，使红娘束探尔。", "(末云)既然小娘子来，小姐必有言语。", "(红唱)俺小姐至今脂粉未曾施，念到有一千番张殿试。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・上马娇","p":"","d":"元代","a":"王实甫","c":["他若是见了这诗，看了这词，他敢颠倒费神思。", "他拽扎起画皮来：\"查得谁的言语你将来，这妮子怎敢胡行事！\"他可敢嗤、嗤的扯做了纸条儿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・幺篇","p":"","d":"元代","a":"王实甫","c":["你看人似桃李春风墙外枝，卖俏倚门儿。", "我虽是个婆娘有志气。", "则说道：\"可怜见小子，只身独自！\"恁的呵，颠倒有个寻思。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・后庭花","p":"","d":"元代","a":"王实甫","c":["我则道拂花笺打稿儿，元来他染箱毫不构思。", "先写了儿句寒温序，后题着五言八句诗。", "不移时，把花笺锦字，叠做个同心方胜儿。", "忒聪明，忒敬思，忒风流，忒浪子。", "虽然是假意儿，小可的难到此。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・青歌儿","p":"","d":"元代","a":"王实甫","c":["颠倒写鸳鸯两字，方信道\"在心为志\"。", "(末云)姐姐将去，是必在意者；(红唱)看喜怒其间觑个意儿。", "放心波学士！我愿为之，并不推辞，自有言词。", "则说道：\"昨夜弹琴的那人儿，教传示。", "\"这简帖儿我与你将去，先生当以功名为念，休堕了志气者！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・煞尾","p":"","d":"元代","a":"王实甫","c":["沈约病多般，宋玉愁无二，清减了相思样子。", "只你那眉眼传情未了时，中心日夜藏之。", "怎敢因而，\"有美玉于斯\"，我须教有发落归着这张纸。", "凭着我舌尖儿上说词，更和这简帖儿里心事，管教那人儿来探你一遭儿。", "(一下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・快活三","p":"","d":"元代","a":"王实甫","c":["分明是你过犯，没来由把我摧残；使别人颠倒恶心烦，你不惯，谁曾惯？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・朝天子","p":"","d":"元代","a":"王实甫","c":["张生近间、面颜，瘦得来实难看。", "不思量茶饭，怕待动弹；晓夜将佳期盼，废寝忘餐。", "黄昏清旦，望东墙淹泪眼。", "(旦云)请个好太医看他症侯咱。", "(红云)他症侯吃药不济。", "病患、要安，则除是出几点风流汗。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・四边静","p":"","d":"元代","a":"王实甫","c":["怕人家凋犯，\"早共晚夫人见些破绽，你我何安。", "\"问甚么他遭危难？撺断得上竿，掇了梯儿看。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・脱布衫","p":"","d":"元代","a":"王实甫","c":["小孩儿家口没遮拦，一迷的将言语摧残。", "把似你使性子，休思量秀才，做多少好人家风范。", "(红做拾书科)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・小梁州","p":"","d":"元代","a":"王实甫","c":["他为你梦里成双觉后单，废寝忘餐。", "罗衣不奈五更寒，愁无限，寂寞泪阑干。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・幺篇","p":"","d":"元代","a":"王实甫","c":["似这等辰勾空把佳期盼，我将这角门儿世不曾牢拴，则愿你做夫妻无危难。", "我向这筵席头上整扮，做一个逢了口的撮合山。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・石榴花","p":"","d":"元代","a":"王实甫","c":["当日个晚妆楼上杏花残，犹自怯衣单，那一片听琴心清露月明间。", "昨日个向晚，不怕春寒，几乎险被\"先生馔\"，那其间岂不胡颜。", "为一个不酸不醋风魔汉，隔墙儿险化做了望夫山。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・斗鹌鹑","p":"","d":"元代","a":"王实甫","c":["你用心儿拨雨撩云，我好意儿传书寄简。", "不肯搜自己狂为，则待要觅别人破绽。", "受艾焙权时忍这番，畅好是奸。", "\"张生是兄妹之礼，焉敢如此！\"对人前巧语花言：--没人处便想张生，--背地里愁眉泪眼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・上小楼","p":"","d":"元代","a":"王实甫","c":["这的是先生命悭，须不是红娘违慢。", "那简帖儿倒做了你的招状，他的勾头，我的公案。", "若不是觑面颜，厮顾盼，扭饶轻慢，先生受罪，礼之当然。", "贱妾何辜？争些儿把你娘拖犯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・满庭芳","p":"","d":"元代","a":"王实甫","c":["你休要呆里撒奸，你待要恩情美满，却教我骨肉摧残。", "老夫人手执着棍儿摩挲看，粗麻线怎透得针关。", "直待我拄着拐帮闲钻懒，缝合唇送暖偷寒。", "待去呵，小姐性儿撮监入火，消息儿踏着泛；待不去呵，(末跪哭云)小生这一个性命，都在小娘子身上。", "(红唱)禁不得你甜话儿热趱：好着我两下里做人难。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・耍孩儿","p":"","d":"元代","a":"王实甫","c":["几曾见寄书的颠倒瞒着鱼雁，小则小心肠儿转关。", "写着道西厢待月等得更阑，着你跳东墙\"女\"字边\"干\"。", "元来那诗句儿里包笼着三更枣，简帖儿里埋伏着九里山。", "他着紧处将人慢，您会云雨闹中取静，我寄音书忙里偷闲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・四煞","p":"","d":"元代","a":"王实甫","c":["纸光明玉板，字香喷麝阑，行儿边湮透非春汗？一缄情泪红犹湿，满纸春愁墨未干。", "从今后休疑难，放心波玉堂学士，稳情取金雀鸦鬟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・三煞","p":"","d":"元代","a":"王实甫","c":["他人行别样的亲，俺跟前取次看，更做道孟光接了梁鸿案。", "别人行甜言美语三冬暖，我跟前恶语伤人六月寒。", "我为头儿看：看你个离魂倩女，怎发付掷果潘安。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・二煞","p":"","d":"元代","a":"王实甫","c":["隔墙花又低，迎风户半拴，偷香手段今番按。", "怕墙高怎把龙门跳，嫌花密难将仙桂攀。", "放心去，休辞惮；你若不去呵，望穿他盈盈秋水，蹙损他淡淡春山。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・双调/新水令","p":"","d":"元代","a":"王实甫","c":["晚风寒峭透窗纱，控金钩绣帘不挂。", "门阑凝暮霭，楼角敛残霞。", "恰对菱花，楼上晚妆罢。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・驻马听","p":"","d":"元代","a":"王实甫","c":["不近喧哗，嫩绿池塘藏睡鸭；自然幽雅，淡黄杨柳带栖鸦，金莲蹴损牡丹芽，玉簪抓住荼蘼架。", "夜凉苔径滑，露珠儿湿透了凌波袜。", "我看那生和俺小姐巴不得到晚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・乔牌儿","p":"","d":"元代","a":"王实甫","c":["自从那日初时想月华，捱一刻似一夏，见柳梢斜日迟迟下，早道\"好教贤圣打\"。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・搅筝琶","p":"","d":"元代","a":"王实甫","c":["打扮的身子儿诈，准备着云雨会巫峡。", "只为这燕侣莺俦，锁不住心猿意马。", "不则俺那姐姐害。", "那生呵，二三日来水米不粘牙。", "因姐姐闭月羞花，真假、这其间性儿难按纳，一地里胡拿。", "姐姐这湖山下立地，我开了寺里角门儿。", "怕有人听俺说话，我且看一看。", "(做意了)偌早晚傻角却不来，赫赫赤赤，来。", "(末云)这其间正好去也，赫赫赤赤。", "(红云)那鸟来了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・沉醉东风","p":"","d":"元代","a":"王实甫","c":["我则道槐影风摇暮鸦，原来是玉人帽侧乌纱。", "一个潜峰在曲槛边，一个背立在湖山下；那里叙寒温，并不曾打话。", "(红云)赫赫赤赤，那鸟来了。", "(末云)小姐，你来也。", "(搂住红科)(红云)禽兽，是我，你看得好仔细着，若是夫人怎了。", "(末云)小生害得眼花，搂得慌了些儿，不知是谁，望乞恕罪！(红唱)便做道搂得慌呵，你也索觑咱，多管是饿得你个穷神眼花。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・乔牌儿","p":"","d":"元代","a":"王实甫","c":["你看那淡云笼月华，似红纸护银蜡，柳丝花朵垂帘下，绿莎茵铺着绣榻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・甜水令","p":"","d":"元代","a":"王实甫","c":["良夜迢迢，闲庭寂静，花枝低亚。", "他是个女孩儿家，你索将性儿温存，话儿摩弄，意儿谦洽；休猜做败柳残花。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・折桂令","p":"","d":"元代","a":"王实甫","c":["他是个娇滴滴美玉无瑕，粉脸生春，云鬓堆鸦。", "恁的般受怕担惊，又不图甚浪酒闲茶。", "则你那夹被儿时当奋发，指头儿告了消乏；打叠起嗟呀，毕罢了牵挂，收拾了忧愁，准备着撑达。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・锦上花","p":"","d":"元代","a":"王实甫","c":["为甚媒人，心无惊怕，赤紧的夫妻每，意不争差。", "我这里蹑足潜踪，悄地听咱：一个羞惭，一个怒发。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・幺篇","p":"","d":"元代","a":"王实甫","c":["张生无一言，呀，莺莺变了卦。", "一个悄悄冥冥，一个絮絮答答。", "却早禁住隋何，迸住陆贾，叉手躬身，装聋作哑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・清江引","p":"","d":"元代","a":"王实甫","c":["没人处则会闲嗑牙，就里空奸诈。", "怎想湖山边，不配\"西厢下\"？香美娘处分破花木瓜。", "(旦)红娘，有贼。", "(红云)是谁？(末云)是小生。", "(红云)张生，你来这里有甚么勾当？(旦云)扯到夫人那里去！(红云)到夫人那里，怕坏了他行止。", "我与姐姐处分他一声。", "张生，你过来跪着！你既读孔圣之书，必达周公之礼，夤夜来此何干？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・雁儿落","p":"","d":"元代","a":"王实甫","c":["不是俺一家儿乔作衙，说几句衷肠话。", "我则道你文学海样深，谁知你负胆有天来大？(红云)你知罪么？(末云)小生不知罪。", "(红唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・得胜令","p":"","d":"元代","a":"王实甫","c":["谁着你夤夜入人家，非奸做贼拿。", "你本是个折桂客，做了偷花汉；不想去跳龙门，学骗马。", "姐姐，且看红娘面饶过这生者！(旦云)若不看红娘面，扯你到夫人那里去，看你有何面目见江东父老？起来！(红唱)谢小姐贤达，看我面遂情罢。", "若到官司详察，\"你既是秀才，只合苦志于寒窗之下，谁教你夤夜辄入人家花园，做得个非奸即盗。", "\"先生呵，准备着精皮肤吃顿打。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・越调/斗鹌鹑","p":"","d":"元代","a":"王实甫","c":["则为你彩笔题诗，回文织锦，送得人卧枕着床，忘餐废寝，折倒得鬓似愁潘，腰如病沈。", "恨已深，病已沉，昨夜个热脸儿对面抢白，今日个冷句儿将人厮侵。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・天净沙","p":"","d":"元代","a":"王实甫","c":["心不存学海文林，梦不离柳影花阴，则去那窃玉偷香上用心。", "又不曾得甚，自从海棠开想到如今。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・调笑令","p":"","d":"元代","a":"王实甫","c":["我这里自审，这病为邪淫；尸骨岩岩鬼病侵。", "更做道秀才们从来恁，似这般干相思的好撒口吞！功名上早则不遂心，婚姻上更返吟复吟。", "(红云)老夫人着我来，看哥哥要甚么汤药。", "小姐再三伸敬，有一药方送来与先生。", "(末做慌科)在那里？(红云)用着几般儿生药，各有制度，我说与你；。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・小桃红","p":"","d":"元代","a":"王实甫","c":["\"桂花\"摇影夜深沉，酸醋当归浸。", "(末云)桂花性温，当归活血，怎生制度？(红唱)面靠着湖山背阴里窨，这方儿最难寻。", "一服两服令人恁。", "(末云)忌甚么物？(红唱)忌的是\"知母\"未寝，怕的是\"红娘\"撒沁。", "吃了呵，稳情取\"使君子\"一星儿\"参\"。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・鬼三台","p":"","d":"元代","a":"王实甫","c":["是下其实啉，休装口吞。", "笑你个风魔的翰林，无处问佳音，向简帖儿上计禀。", "得了个纸条儿恁般绵里针，若见玉天仙怎生软厮禁？俺那小姐忘恩，亦紧的偻人负心。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・秃厮儿","p":"","d":"元代","a":"王实甫","c":["身卧着一条布衾，头枕着三尺瑶琴；他来时怎生和你一处寝？冻得来战兢兢，说甚知音？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・圣药王","p":"","d":"元代","a":"王实甫","c":["果若你有心，他有心，昨日秋千院宇夜深沉；花有阴，月有阴，\"春宵一刻抵千金\"，何须\"诗对会家吟\"？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・东原乐","p":"","d":"元代","a":"王实甫","c":["俺那鸳鸯枕，翡翠衾，便遂杀了人心，如何自赁？至如你不脱解和衣儿更怕甚？不强如于执定指尖儿恁。", "倘或成亲，到大宋福荫。", "(末云)小生为小姐如此容色，莫不小姐为小生也减动丰韵么？(红唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・绵搭絮","p":"","d":"元代","a":"王实甫","c":["他眉弯远山铺翠，眼横秋水无尘；体若凝酥，腰如嫩柳，俊的是庞儿俏的是心，体态温柔性格儿沉。", "虽不会法灸神针，更胜似救苦难观世音。", "(末云)今夜成了事，小生不敢有忘。", "(红唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・幺篇","p":"","d":"元代","a":"王实甫","c":["你口儿里漫沉吟，梦儿里苦追寻。", "往事已沉，只言目今，今夜相逢管教恁。", "不图你甚白壁黄金，则要你满头花，拖地锦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・煞尾","p":"","d":"元代","a":"王实甫","c":["虽然是老夫人晓夜将门禁，好共歹须教你称心。", "(末云)休似昨夜不肯。", "(红云)你挣揣咱，来时节肯不肯尽由他，见时节亲不亲在于您。", "(并下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"张君瑞害相思(第三本)・络丝娘煞尾","p":"","d":"元代","a":"王实甫","c":["因今宵传言送语，看明日携云握雨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕/赏花时","p":"","d":"元代","a":"杨景贤","c":["放鱼的都言子产良，射虎的皆称周处强。", "你之任到他乡，买得活鱼尚不忍坏，今恩足以及禽兽矣。", "百姓行必有个主张，咱两个携手上河梁。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"混江龙","p":"","d":"元代","a":"杨景贤","c":["这里有船无路，玉骢不惯识西湖。", "乡关何处？烟景模糊。", "一片锦帆云外落，千重绣岭望中舒。", "江声汹涌，风力喧呼，犹怀着千古英雄怒。", "这山见几番白发，这水换几遍皇都。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"油葫芦","p":"","d":"元代","a":"杨景贤","c":["你道是万事无过酒破除，你不曾读《大禹谟》？禹恶旨酒而好善言，进来的美酒禁入皇都。", "你今日白衣应举思高步，恰便似黄鹂出谷迁乔木。", "今日受三品职，全凭你满腹书。", "布衣中跳到洪州路，倒不如借住在步兵厨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"村里迓鼓","p":"","d":"元代","a":"杨景贤","c":["听了他语言无味，觑了他面色可恶！(陈云)夫人，你多事，你是汉时许负？(夫人唱)我虽不是汉时许负，端详了是个不良人物。", "你看他胁肩谄笑，趋前退后，张皇失错。", "(王云)夫人，我认得人。", "(夫人唱)聪明的王伯当，(陈云)不妨事。", "(夫人唱)糊突了裴闻喜，休送了孤寒鲁义姑，恁堤防着船到江心漏苦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"元和令","p":"","d":"元代","a":"杨景贤","c":["料心肠似蝎毒，看眼脑似狼顾。", "(陈云)娘子，灰头草面不打扮，偿或江上遇着相知朋友，怎生厮见？(夫人唱)路途中何须用巧妆梳，金凤翘珠络索？却不道周亡殷破越倾吴，都则因美艳妹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"上马娇","p":"","d":"元代","a":"杨景贤","c":["想当日妲己又俗，褒姒又愚。", "西子有妖术，累朝把家邦来误。", "可正是，美女累其夫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺","p":"","d":"元代","a":"杨景贤","c":["他每送了百二山河壮帝居，愿及早到洪都。", "俺三口别无眷属，无金无玉，有官有禄。", "受天子御前除。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"游四门","p":"","d":"元代","a":"杨景贤","c":["除俺做洪州知府教风俗，(刘云)小人正是本处人。", "(夫人唱)你正是本乡居。", "着殷勤相公亲抬举，免税脱丁夫。", "咱两口，都不会说嚣虚。", "(刘云)多谢夫人。", "禀老爷，好顺风，请早些下船罢。", "(陈同夫人下船，分付开船科)(刘云)不免扯起篷来。", "(夫人唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"胜葫芦","p":"","d":"元代","a":"杨景贤","c":["则见他风顺帆开船去速，更疾似马和车。", "(刘做推抢科)(夫人唱)俺歹煞是洪州民父母，你怎敢推前抢后，你来我去？(陈云)夫人，才下船要利市，饶他初犯罢。", "(夫人云)相公说那里话。", "常言道君子断其初。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"青哥儿","p":"","d":"元代","a":"杨景贤","c":["呀！急煎煎无一个亲人相护，(刘做扯科)紧邦邦扯住了衣服，哎，你个粪土之墙不可木亏，又无甚钱物。", "杀坏他身躯，倾陷了俺儿夫，强要他媳妇。", "天意何如？人命何辜？哎！你个柳盗跖哥哥忒心毒，怎下得浪淘淘流将他去？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声","p":"","d":"元代","a":"杨景贤","c":["拆散了美满并头莲，接上这热莽连枝树，你愿足咱心未足。", "鸱枭难和莺燕侣，厕坑里蛆怎和你似水如鱼。", "若是到洪都，佥押文书，甚的是六案须知和裣目？这一个屈死的风流丈夫，偷生的愚痴拙妇，谁想俺死和生的夫妇到头疏？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕/粉蝶儿","p":"","d":"元代","a":"杨景贤","c":["满腹离愁，诉苍天不能答救，俺一家儿和你有甚冤仇？淹杀我儿夫，奸淫他媳妇，又待废他亲生的骨肉。", "那贼汉劣心肠火上浇油，不依从恐遭毒手。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉春风","p":"","d":"元代","a":"杨景贤","c":["烧一陌断肠钱，酹三杯离恨酒。", "滔滔雪浪大江中，陈光蕊呵，你魂灵儿敢有、有！我有一个大梳匣，将孩儿安在里面，将两三根木头儿，将蔑子缚着，可以浮将去。", "匣子里安藏，水波边抛弃，陈光蕊呵，你在那浪花中等候。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"迎仙客","p":"","d":"元代","a":"杨景贤","c":["心肝浑似摘，我泪点卒难收，将这乳食儿再三滴入口。", "若流过蓼花滩，芦叶洲，休着当住石头，天那，则愿得渔父每争相救。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"石榴花","p":"","d":"元代","a":"杨景贤","c":["愿龙神保佑莫迟留，休着鱼鳖等闲瞅。", "鼋鼍蛟蜃莫追逐，到瓜州渡口，有人亲救。", "对天祷告还生受，保护得他速见东流。", "金钗两股牢拴就，抵多少骑鹤上扬州。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"斗鹌鹑","p":"","d":"元代","a":"杨景贤","c":["恁娘那里望眼将穿，俺儿大灵魂儿尚有。", "儿呵，则愿得性命完全，精神抖擞。", "恰便似红叶儿飘香出御沟，淹淹地伴野鸥。", "俺孩儿身向低行，谁肯道恩从亡流？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"上小楼","p":"","d":"元代","a":"杨景贤","c":["咬破我这纤纤指头，一任淋淋血溜。", "摅一缕白练，写两行红字，赴万顷清流。", "将匣缝儿塞，匣盖儿缚，包袱儿紧扣，我须关防得宋水屑不漏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"十二月","p":"","d":"元代","a":"杨景贤","c":["他那里呱呱叫吼，我这里急急抽头。", "将匣子轻抬手，近着这沙岸汀洲。", "哭声哀猿闻肠断，匣影孤鱼见应愁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尧民歌","p":"","d":"元代","a":"杨景贤","c":["儿呵，趁着这一江春水向东流，离子上源头则愿你有下场头。", "蒹葭寒水泛轻鸥，恰便似杨柳西风送行舟。", "(内做催科)休则管逼逐，别离几样忧，如摘下心肝上肉。", "(做放科)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺","p":"","d":"元代","a":"杨景贤","c":["咽不下心内苦，遮不了脸上羞。", "怀耽十月干生受，一个赤子入井谁人救？一个红粉迸波那个瞅？今日肉落在猫儿。", "做儿的花飘泛水，做娘的几时得叶落归秋。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声","p":"","d":"元代","a":"杨景贤","c":["跛弓鞋恰转身，回胭领再瞬眸。", "这一个锁离愁的匣子儿索是劳台候，望着那流水斜阳路儿上走。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"商调/集贤宾","p":"","d":"元代","a":"杨景贤","c":["你趁着那碧澄澄大江东去得紧，如失却宝和珍。", "白日里鱼行虾队，到晚来鹭友鸥群。", "黑蒙蒙翠雾连山，白漭漭雪浪堆银。", "则俺那跳龙门的丈夫转世稳便，重生上八岁为人。", "目穷明月渡，肠断碧天云。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"逍遥乐","p":"","d":"元代","a":"杨景贤","c":["倚危楼高峻，瞑眩药难痊，志诚心较谨。", "(唐僧扮行脚僧上，云)来到洪州。", "问人来，旧太守陈光蕊家，在江边黑楼子内便是。", "惭愧，有他呵便，有我的母亲。", "来到也，这个便是。", "我叫一声：阿弥陀佛。", "(夫人唱)见一个小沙弥来往踅开门，叫一声阿弥陀佛心意全真。", "策杖移踪似有因，恰便是塑来的诸佛世尊。", "师父，俺家里斋来。", "(唐僧云)有布施么？(夫人唱)有做袈裟的绸绢，供佛像的斋粮，御严寒的衲裙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金菊香","p":"","d":"元代","a":"杨景贤","c":["金山来此二三旬，宝殿能容千万人。", "问讯向前礼数勤，觑了他清气逼人，恰便是一溪流水彻云根。", "这和倘好似我陈光蕊男儿也呵！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿","p":"","d":"元代","a":"杨景贤","c":["眉眼全相似，身材忒煞真，霞脸绛丹唇，莫不是石上三生梦，天台一化身？我心下自如亲。", "师父，你法算多少了？(唐僧云)小僧年一十八岁也。", "(夫人云)俺孩儿在时，也一十八岁。", "儿呵，你随着十八年波翻浪滚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醋葫芦","p":"","d":"元代","a":"杨景贤","c":["我问你何处是家？那个是亲？几年上落发做僧人？(唐僧云)出母胞胎，便做僧人。", "(夫人唱)出胞胎便怎生离世尘？也是你前生有分，便是离母腹中出家，也须索有你爷娘。", "与我从头一一说缘因。", "(唐僧云)我父姓陈，母姓殷。", "(夫人唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺","p":"","d":"元代","a":"杨景贤","c":["他道是父姓陈，母姓殷。", "为官为吏是当军？(唐僧云)我父亲任洪州太守。", "(夫人唱)几年上此间来治民？(唐僧云)贞观三年八月间，被贼人劫杀在江中了也。", "(夫人唱)则一句道的我心迷眼晕，他道是江上遇着强人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺","p":"","d":"元代","a":"杨景贤","c":["听说绝口内词，扫除了心上尘。", "幽幽的顶门上去了三魂，元来是仁流儿远乡来认亲。", "(唐僧云)娘子，好要便宜也，我怎生是恁孩儿？(夫人唱)是小的每言多语峻，告吾师心下莫生嗔。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺","p":"","d":"元代","a":"杨景贤","c":["尘昏了老绢帛，金黄了旧血痕。", "这的是一番提起一番新，与我那十八年的泪珠都征了本。", "善和恶在乎方寸，恰便似花开枯树再逢春。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕/后庭花","p":"","d":"元代","a":"杨景贤","c":["我这里收拾下金共银，则要你早分一个冤与恩。", "俺孩儿经卷能成事，陈光蕊呵，你说甚文章可立身？莫因循，疾忙前进。", "下水船风力稳，报仇心如箭紧，去程忙似火焚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"柳叶儿","p":"","d":"元代","a":"杨景贤","c":["我又想当年时分，哭啼啼送你到江滨。", "今日个蒲帆百尺西风顺，休辞困，暂劳神，天那，谁承望血修书弄假成真？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"商调/浪里来","p":"","d":"元代","a":"杨景贤","c":["才得见掌上珍，又提起心头闷。", "今宵何处去安身？明日里风波可又无定准。", "眼睁睁看的他有家难奔，空着我断肠人送断肠人。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听","p":"","d":"元代","a":"杨景贤","c":["鹊噪花枝，报仇恨的孩儿敢来到此。", "龙蟠泥滓，受辛勤娘母困于斯。", "这贼汉孽罐儿满了，想天公不受半分私，则怕阎王注定三更死，这厮怎能勾亡正寝、全四肢？少不得一刀两段诛在都市。", "(唐僧引公人做拿住科)(刘云)娘子，我也无歹处，你救我咱。", "(夫人唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"雁儿落","p":"","d":"元代","a":"杨景贤","c":["神道般官吏使，虎狼般公人至。", "(刘云)到官休说你的事出来，我也是有情分的人。", "(夫人唱)我不申口内言，你自想心间事。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"得胜令","p":"","d":"元代","a":"杨景贤","c":["长老便是正名师，(刘云)那得小和尚来告状，他是谁？(夫人唱)天网恢恢，疏而不漏，这个是江流的小孩儿。", "今日个死草重交翠，残花再发枝。", "当时，已趁英雄志，你不索寻思，则要你填还俺夫婿死。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"川拨棹","p":"","d":"元代","a":"杨景贤","c":["江上设灵祠，用三牲作祭祀。", "浪卷风嘶，风袅杨枝。", "(龙王、夜叉背陈光蕊上)(夫人惊，云)哑，孩儿，远远望见江面上，是你父亲的灵魂来了。", "(唐僧云)这就是我父亲？(夫人唱)鬼吏参差，簇捧着屈死的孤穷秀士。", "十八年霜雪姿，我苍颜他似旧时。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"七兄弟","p":"","d":"元代","a":"杨景贤","c":["他说罢口内词，官人每三思，一个个痛嗟咨。", "(观音佛上高垛，云)众官见老僧么？(众做拜科)(观音云)长安城中，今夏大旱。", "可着玄奘赴京师，祈雨救民。", "我佛有五千四十八卷《大藏金经》，要来东土，单等玄奘来。", "虞太守听我叮咛：依老僧国祚安宁。", "陈光蕊全家封赠，唐三藏西天取经。", "(下)(夫人唱)云头上显出白衣衣，市廛间诛了绿林儿，贼巢中趁了红裙志。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梅花酒","p":"","d":"元代","a":"杨景贤","c":["都赖着佛旨，水府内为师，早地上当时，尘世上官司。", "那海龙王报救命恩，小和尚说因缘事。", "上八年离城市，离城市到龙祠，到龙祠住偌时，住偌时再回之。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"收江南","p":"","d":"元代","a":"杨景贤","c":["呀！今日个大官司输与小孩儿，小孩儿亏杀老禅师，老禅师慧眼识天时。", "观音佛法旨，着取西天经卷到京师。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・仙吕/点绛唇","p":"","d":"元代","a":"关汉卿","c":["俺本是汉国臣僚。", "汉皇软弱；兴心闹，惹起那五处兵刀，并董卓，诛袁绍。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・混江龙","p":"","d":"元代","a":"关汉卿","c":["止留下孙、刘、曹操，平分一国作三朝。", "不付能河清海晏，雨顺风调；兵器改为农器用，征旗不动酒旗摇；军罢战，马添膘；杀气散，阵云消；为将帅，作臣僚；脱金甲，着罗袍；则他这帐前旗卷虎潜竿，腰间剑插龙归鞘。", "人强马壮，将老兵骄。", "（云）可早来到也。", "左右报复去，道乔公来了也。", "（卒子报云）报的大夫得知：有乔公来到了也。", "（鲁云）道有请。", "（卒云）老相公，有请！（末见鲁，云）大夫，今日请老夫来，有何事干？（鲁云）今日请老相公，别无甚事，商量索取荆州之事。", "（末云）这荆州断然不可取！想关云长好生勇猛，你索荆州呵，他弟兄怎肯和你甘罢？（鲁云）他弟兄虽多，兵微将寡。", "（末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・天下乐","p":"","d":"元代","a":"关汉卿","c":["你道是\"铜雀春深锁二乔\"，这三朝、恰定交，不争咱一日错便是一世错……（鲁云）俺这里有雄兵百万，战将千员，量他到的那里！（末唱）你则待要行霸道，你待要起战讨。", "（鲁云）我料关云长年迈，虽勇无能。", "（末唱）你休欺负关云长年纪老。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・那吒令","p":"","d":"元代","a":"关汉卿","c":["收西川白帝城，将周瑜来送了。", "汉江边张翼德，将尸骸来当着。", "船头上鲁大夫，几乎间唬倒。", "你待将荆州地面来争，关云长听的闹，他可便乱下风雹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・鹊踏枝","p":"","d":"元代","a":"关汉卿","c":["他诛文丑逞粗躁，刺颜良显英豪。", "他去那百万军中，他将那首级轻枭。", "（鲁云）想赤壁之战，我与刘备有恩来。", "（末唱）那时间相看的是好，他可便喜孜孜笑里藏刀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・寄生草","p":"","d":"元代","a":"关汉卿","c":["幸然是天无祸，是咱这人自招。", "全不肯施恩布德行王道，怎比那多谋足智雄曹操？你须知南阳诸葛应难料！（鲁云）他若不与呵，我大势军马，好歹夺了荆州。", "（末唱）你则待千军万马恶相持，全不想生灵百万遭残暴！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・金盏儿","p":"","d":"元代","a":"关汉卿","c":["他上阵处赤力力三绺美髯飘，雄赳赳一丈虎躯摇，恰便似六了神簇捧定一个活神道。", "那敌军若是见了，唬的他七魄散、五魂消。", "（云）你若和他厮杀呵。", "（唱）你则索多披上几副甲，剩穿上几层袍。", "便有百万军，挡不住他不刺刺千里追风骑；你便有千员将，闪不过明明偃月三停刀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・尾声","p":"","d":"元代","a":"关汉卿","c":["曹丞相将送路酒手中擎，饯行礼盘中托，没乱煞侄儿和嫂嫂。", "曹孟德心多能做小，关云长善与人交。", "早来到灞陵桥，险唬杀许褚、张辽；他勒着追风骑，轻轮动偃月刀。", "曹操有千般计较，则落的一场谈笑。", "（云）关云长道：\"丞相勿罪！某不下马了也。", "\"（唱）他把那刀尖儿斜挑锦征袍。", "（下）（鲁云）黄文，你见乔公说关公如此威风，未可深信。", "俺这江下，有一贤士，复姓司马，名徽，字德操。", "此人与关公有一面之交，就请司马先生为伴客，就问关公平昔智勇谋略，酒中德性如何。", "黄文，就跟着我去司马庵中相访一遭去。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・正宫/端正好","p":"","d":"元代","a":"关汉卿","c":["本是个钓鳌人，到做了扶犁叟；笑英布、彭越、韩侯。", "我如今紧抄定两只拿云手，再不出麻袍袖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・滚绣球","p":"","d":"元代","a":"关汉卿","c":["我则待要聚村叟，会诗友，受用的活鱼新酒，问甚么瓦钵瓷瓯。", "推台不换盏，高歌自掴手；任从他阴晴昏昼，醉时节衲被蒙头。", "我向这矮窗睡彻三竿日，端的是傲煞人间万户侯，自在优游。", "（云）道童，门首觑者，看有甚么人来。", "（道童云）理会的。", "（鲁肃上，云）可早来到也，接了马者。", "（见道童科，鲁云）道童，先生有么？（童云）俺师父有。", "（鲁云）你去说：鲁子敬特来相访。", "（童云）你是紫荆？你和那松木在一搭里。", "我报师父去。", "（见末，云）师父弟子孩儿……（末云）这厮怎么骂我！（童云）不是骂；师父是师父，弟子是徒弟，就是孩儿一般。", "师父弟子孩儿……（末云）这厮泼说？有谁在门首？（童云）有鲁子敬特来相访。", "(末云）道有请。", "（童云）理会的。", "（童出见鲁，云）有请！（鲁见末科）（末云）稽首。", "（鲁云）区区俗冗，久不听教。", "（末云）数年不见，今日何往？（鲁云）小官无事不来，特请先生江下一会。", "（末云）贫道在此江下修行，方外之士，有何德能，敢劳大夫置酒张筵？（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・滚绣球","p":"","d":"元代","a":"关汉卿","c":["大夫，你着我筵前劝几瓯，那汉劣性怎肯道折了半筹？（鲁云）将酒央人，终无恶意。", "（末唱）你便休题安排着酒肉，他怒时节目前见鲜血交流。", "你为汉上九座州，我为筵前一醉酒，（云）大夫，你和贫道，（唱）咱两个都落不的完全尸首。", "（鲁云）先生是客，怕做甚么？（末唱）我做伴客的少不的和你同病同忧。", "（鲁云）我有三条计索取荆州。", "（末唱）只为你千年勋业三条计，我可甚\"一醉能消万古愁\"，提起来魂魄悠悠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・倘秀才","p":"","d":"元代","a":"关汉卿","c":["你与我躬着身将他来问候。", "（云）你依的么？（鲁云）关云长下的马来，我躬着身问候。", "不打紧，也依的。", "（未唱）大夫，你与我跪着膝连忙的劝酒；饮则饮、吃则吃、受则受。", "道东呵随着东去，说西呵随着西流。", "（云）这一桩儿最要紧也！（唱）他醉了呵你索与我便走。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・滚绣球","p":"","d":"元代","a":"关汉卿","c":["他尊前有一句言，筵前带二分酒，他酒性躁不中撩斗，你则绽口儿休提着索取荆州。", "（鲁云）我便索荆州有何妨？（末云）他听的你索取荆州，（唱）他圆睁开丹凤眸，轻舒出捉将手；他将那卧蚕眉紧皱，五蕴山烈火难收。", "他若是玉山低趄，你安排着走；他若是宝剑离匣，你则准备着头。", "枉送了你那八十一座军州！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・倘秀才","p":"","d":"元代","a":"关汉卿","c":["比及你东吴国鲁大夫仁兄下手，则消得西蜀国诸葛亮先生举口，奏与那有德行仁慈汉皇叔。", "那先生抚琴霜雪降，弹剑鬼神愁，则怕你急难措手。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・滚绣球","p":"","d":"元代","a":"关汉卿","c":["有一个黄汉升猛似彪；有一个赵子龙胆大如斗；有一个马孟起，他是个杀人的领袖；有一个莽张飞，虎牢关力战了十八路诸侯，骑一匹毕月乌，使一条丈八矛，他在那当阳坂有如雷吼，喝退了曹丞相一百万铁甲貔貅，他瞅一瞅漫天尘土桥先断，喝一声拍岸惊涛水逆流。", "那一伙怎肯干休！（鲁云）先生若肯赴席呵，就与关公一会何妨？（末云）大夫，不中，不中！休说贫道不曾劝你。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・隔尾","p":"","d":"元代","a":"关汉卿","c":["我则待拖条藜杖家家走，着对麻鞋处处游。", "（云）我这一去，（唱）恼犯云长歹事头，周仓哥哥快争斗，轮起刀来劈破了头，唬的我恰便似缩了头的乌龟则向那汴河里走。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・中吕/粉蝶儿","p":"","d":"元代","a":"关汉卿","c":["那时节天下荒荒，恰周、秦早属了刘、项，分君臣先到咸阳。", "一个力拔山，一个量容海，他两个一时开创。", "想当日黄阁乌江，一个用了三杰，一个诛了八将。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・醉春风","p":"","d":"元代","a":"关汉卿","c":["一个短剑下一身亡，一个静鞭三下响。", "祖宗传授与儿孙，到今日享、享。", "献帝又无靠无依，董卓又不仁不义，吕布又一冲一撞。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・十二月","p":"","d":"元代","a":"关汉卿","c":["那时节兄弟在范阳，兄长在楼桑，关某在蒲州解良，更有诸葛在南阳；一时出英雄四方，结义了皇叔、关、张。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・尧民歌","p":"","d":"元代","a":"关汉卿","c":["一年三谒卧龙网，却又早鼎分三足汉家邦。", "俺哥哥称孤道寡世无双，我关某匹马单刀镇荆襄。", "长江，今经几战场，却正是后浪催前浪。", "（云）孩儿，门首觑者，看甚么人来。", "（关平云）理会的。", "（黄文上，云）某乃黄文是也。", "将着这一封请书，来到荆州，请关公赴会。", "早来到也。", "左右，报复去：有江下鲁子敬，差上将拖地胆黄文，持请书在此。", "（平云）你则在这里者，等我报复去。", "（平见正末，云）报的父亲得知：今有江东鲁子敬，差一员首将，持请书来见。", "（正末云）着他过来。", "（平云）着你过去哩。", "（黄文见科）（正末云）兀那厮甚么人？（黄慌云）小将黄文。", "江东鲁子敬，差我下请书在此。", "（正末云）你先回去，我随后便来也。", "（黄文云）我出的这门来。", "看了关公英雄一个神道相。", "鲁子敬，我替你愁哩！小将是黄文，特来请关公。", "髯长一尺八，面如挣枣红。", "青龙偃月刀，九九八十斤。", "脖子里着一下，那里寻黄文？来便吃筵席，不来豆腐酒吃三钟。", "（下）（正末云）孩儿，鲁子敬请我赴单刀会，走一遭去。", "（平云）父亲，他那里筵无好会，则怕不中么？（正末云）不妨事。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・石榴花","p":"","d":"元代","a":"关汉卿","c":["两朝相隔汉阳江，上写着道\"鲁肃请云长\"。", "安排筵宴不寻常，休想道\"画堂别是风光\"。", "那里有凤凰杯满捧琼花酿，他安排着巴豆、砒霜！玳筵前摆列着英雄将，休想肯\"开宴出红妆\"。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・斗鹌鹑","p":"","d":"元代","a":"关汉卿","c":["安排下打凤牢龙，准备着天罗地网；也不是待客筵席，则是个杀人、杀人的战场。", "若说那重意诚心更休想，全不怕后人讲。", "既然谨谨相邀，我则索亲身便往。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・上小楼","p":"","d":"元代","a":"关汉卿","c":["你道他\"兵多将广，人强马壮\"；大丈夫敢勇当先，一人拚命，万夫难当。", "（平云）许来大江面，俺接应的人，可怎生接应？（正末唱）你道是隔着江，起战场，急难亲傍；我着那厮鞠躬、鞠躬送我到船上。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・幺篇","p":"","d":"元代","a":"关汉卿","c":["你道是先下手强，后下手殃。", "我一只手揪住宝带，臂展猿揉，剑掣秋霜。", "（平云）父亲，则怕他那里有埋伏。", "（正末唱）他那里暗暗的藏，我须索紧紧的防。", "都是些狐朋狗党！（云）单刀会不去呵，（唱）小可如千里独行，五关斩将。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・快活三","p":"","d":"元代","a":"关汉卿","c":["小可如我携亲侄访冀王，引阿嫂觅刘皇，灞陵桥上气昂昂，侧坐在雕鞍上。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・鲍老儿","p":"","d":"元代","a":"关汉卿","c":["俺也曾挝鼓三冬斩蔡阳，血溅在沙场上。", "刀挑征袍出许昌，险唬杀曹丞相。", "向单刀会上，对两班文武，小可如三月襄阳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・剔银灯","p":"","d":"元代","a":"关汉卿","c":["遮莫他雄赳赳排着战场，威凛凛兵屯虎帐，大将军智在孙、吴上。", "马如龙，人似金刚；不是我十分强，硬主张，但提起厮杀呵磨拳擦掌。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・蔓菁菜","p":"","d":"元代","a":"关汉卿","c":["他便有快对付能征将，排戈戟，列旗枪，对仗，我是三国英雄汉云长，端的是豪气有三千丈。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・尾声","p":"","d":"元代","a":"关汉卿","c":["须无那临潼会秦穆公，又无那鸿门会楚霸王，遮莫他满筵人列着先锋将，小可如百万军刺颜良时那一场嚷。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・双调/新水令","p":"","d":"元代","a":"关汉卿","c":["大江东去浪千叠，引着这数十人驾着这小舟一叶。", "又不比九重龙凤阙，可正是千丈虎狼穴。", "大丈夫心别，我觑这单刀会似赛村社。", "（云）好一派江景也呵！（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・驻马听","p":"","d":"元代","a":"关汉卿","c":["水涌山叠，年少周郎何处也？不觉的灰飞烟灭，可怜黄盖转伤嗟。", "破曹的樯橹一时绝，鏖兵的江水犹然热，好教我情惨切！（带云）这也不是江水，（唱）二十年流不尽的英雄血！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・庆东原","p":"","d":"元代","a":"关汉卿","c":["你把我真心儿待，将筵宴设，你这般攀今览古，分甚枝叶？我根前使不着你\"之乎者也\"、\"诗云子曰\"，早该豁口截舌！有意说孙、刘，你休目下番成吴、越！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・沉醉东风","p":"","d":"元代","a":"关汉卿","c":["想着俺汉高皇图王霸业，汉光武秉正除邪，汉王允将董卓诛，汉皇叔把温侯灭，俺哥哥合情受汉家基业。", "则你这东吴国的孙权，和俺刘家却是甚枝叶？请你个不克己先生自说！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・雁儿落","p":"","d":"元代","a":"关汉卿","c":["则为你三寸不烂舌，恼犯我三尺无情铁。", "这剑饥餐上将头，渴饮仇人血。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・得胜令","p":"","d":"元代","a":"关汉卿","c":["则是条龙向鞘中蛰，唬得人向座间躲。", "今日故友每才相见，休着俺弟兄每相间别。", "鲁子敬听者，你内心休乔怯，畅好是随邪，休怪我十分酒醉也。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"关大王独赴单刀会・搅筝琶","p":"","d":"元代","a":"关汉卿","c":["却怎生闹炒炒军兵列，上来的休遮当，莫拦截。", "（云）当着我的，呵呵！（唱）我着他剑下身亡，目前流血！便有那张仪口，蒯通舌，休那里躲闪藏遮。", "好生的送我到船上者，我和你慢慢的相别。", "（鲁云）你去了倒是一场伶俐。", "（黄文云）将军，有埋伏哩。", "（鲁云）迟了我的也。", "（关平领众将上，云）请父亲上船，孩儿每来迎接哩。", "（正末云）鲁肃，休惜殿后。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・燕引雏奉寄小山先辈","p":"","d":"元代","a":"大食惟寅","c":["气横秋，心驰八表快神游。", "词林谁出先生右？独占鳌头。", "诗成神鬼愁，笔落龙蛇走，才展山川秀。", "声传南国，名播中州。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・寿阳曲答卢疏斋","p":"","d":"元代","a":"珠帘秀","c":["山无数，烟万缕，憔悴煞玉堂人物。", "倚篷窗一身儿活受苦，恨不得随大江东去。", "冬季会黎正卿分司席上开年近，酿酒醇，是谁传竹边梅信？小斋中主宾三四人，旋蒸来醉乡风韵。", "套数。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"正宫・醉西施","p":"","d":"元代","a":"珠帘秀","c":["检点旧风流，近日来渐觉小蛮腰瘦。", "想当初万种恩情，到如今反做了一场亻孱亻愁。", "害得我柳眉颦秋波水溜，泪滴春衫袖，似桃花带雨胭脂透。", "绿肥红瘦，正是愁时候。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"并头莲・风柔，帘垂玉钩。怕双双燕子，两两莺俦，对对时相守。薄情在","p":"","d":"元代","a":"珠帘秀","c":["何处秦楼？赢得旧病加新病，新愁拥旧愁。", "云山满目，羞上晚妆楼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赛观音・花含笑，柳带羞。舞场何处系离愁？欲传尺素仗谁修？把相思一","p":"","d":"元代","a":"珠帘秀","c":["笔都勾，见凄凉芳草增上万千愁。", "休、休，肠断湘江欲尽头。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉芙蓉・寂寞几时休，盼音书天际头。加人病黄鸟枝头，助人愁渭城衰柳。","p":"","d":"元代","a":"珠帘秀","c":["满眼春江都是泪，也流不尽许多愁。", "若得归来后，同行共止，便是牡丹花下死，做鬼也风流。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"临江仙","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末上)一段新奇真故事，须教两极驰名。", "三千今古腹中存，开言惊四座，打动五灵神。", "六府齐才并七步，八方豪气凌云，歌声遏住九霄云。", "十分全会者，少不得仁义礼先行。", "〔问答照常〕。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"沁园春","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["才子王生，佳人钱氏，贤孝温良；以荆钗为聘，配为夫妇。", "春闱催试，拆散鸾凰。", "独步蟾宫，高攀仙桂，一举鳌头姓氏香。", "因参相，不从招赘，改调潮阳。", "修书远报萱堂，中道奸谋变祸殃。", "岳母生嗔，逼凌改嫁，山妻守节，潜地去投江。", "幸神道匡扶，使舟人捞救，同赴瓜期往异乡。", "吉安会，义夫节妇，千古永传扬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"满庭芳","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］乐守清贫，恭承严训，十年灯火相亲。", "胸藏星斗，笔阵扫千军。", "若遇桃花浪暖，定还我一跃龙门。", "亲年迈，且自温衾扇枕，随分度朝昏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"水底鱼","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］白屋书生，胸中醉六经。", "蛟腾风起，管登科，为上卿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］白面儿郎，学疏才不广。", "粗豪狂放，指银瓶，索酒尝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉芙蓉","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］书堂隐相儒，朝野开贤路，喜明年春闱已招科举。", "窗前岁月莫虚度，灯下简篇可卷舒。", "［合］时不遇，且藏渚韫椟。", "际会风云，那时求价待沽堵。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］悬头及刺股，挂角并投斧，叹先贤曾历许多勤苦。", "六经三史宜温故，诸子四书可诵读。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］家私虽富足，心性忒愚鲁，向书斋懒读者也之乎。", "无才学休想学干禄，有才的便能身挂绿。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"高阳台","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］兔走乌飞，星移物换，看看鬓发皤然。", "嗣息无缘，幸生一女芳年。", "温衣饱食堪过遣，赖祖宗遗下田园。", "喜一家老幼平安，谢天周全。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"鹧鸪天","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["华发萧萧鬓若霜，老来无子实堪伤，箕裘事业谁承继，诗礼传家孰绍芳。", "闲议论，细思量，欲将一女赘贤良。", "流行坎坷皆前定，只把丹心托上苍。", "老夫姓钱，名流行，温城人也。", "昔在鸿门，忝考贡元。", "衣冠世裔，时乖难显于宗风，阀阅名家，学浅粗知乎礼义。", "不幸先妻早逝，只有一女，年方二八，欲招王十朋为婿，以继百年。", "自愧再婚姚氏，幸喜此女能侍父母。", "正是\"子孝双亲乐，家和万事成。", "\"今日是老夫贱诞，聊备蔬酒，少展良辰。", "李成那里？［末上］一点祥光现紫薇，匆匆瑞气蔼庭帏，齐簪翠竹生春意，共饮瑶卮介寿眉。", "老员外有何钧旨？［外］请老安人出来。", "［末］老安人有请。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"腊梅花","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］年华老人双鬓皤，胭脂腻粉幸丢抹。", "市人都道我，道老娘相像夜叉婆。", "［末］牛头狱卒做浑家，此不是夜又婆？［净］老员外万福。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］奴奴体貌多袅娜，月里嫦娥也赛奴不过。", "市人都道我，道老娘相像紧那罗。", "［末］小心金鼓手，此不是紧拿锣。", "［丑见介］愿嫂嫂千年朱顶鹤，愿哥哥万代绿毛龟。", "［外］甚么说话？［净］姑娘，今日是你哥哥诞日，为何只得能迟？［丑］在家整备些薄礼，因此来迟。", "［外］妹子自家一般，如何送许多礼采？［丑］没有什么。", "牵得一只黄狗，与哥哥庆寿。", "［外］狗庆得寿的？［丑］\"黄?无疆\"，愿哥哥\"受天之庆\"。", "［净］每年间是你把盏，今年你侄女长成了，该他把盏，学些礼体。", "待我去叫他出来。", "孩儿那里？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锦堂月","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］华发斑斑，韶光荏苒，双亲幸喜平安。", "庆此良辰，人人对景欢颜。", "画堂中宝篆香销，玉盏内流霞光泛。", "［合］齐祝赞，愿福如东海，寿比南山。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］筵间，绣巾莫围环，奇珍摆列，浑如洞府仙寰，美食嘉肴，堪并凤髓龙肝。", "簪翠竹同乐同欢，饮绿醑齐歌齐唱。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］幽闲，食可加餐。", "官无事扰，情怀并没愁烦。", "人老花残，于心尚有相关。", "待招赘百岁姻亲，承继我一脉根蔓。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉翁子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["非悭。", "论治家千难万难，休只管吃得瓮尽杯干。", "［丑］今番，庆生席面，难做寻常一例看。", "［合］重换盏，直饮到月转花梢，影上阑杆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］神仙，满座间人闲事减。", "庆眉寿，樽前席上，正宜疏散。", "［众］欢宴，乐人祗应，品竹弹丝敲象板。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"侥侥令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［众］银台烧绛蜡，宝鼎喷沉檀，望乞苍穹从人愿。", "［合］骨肉永团圆，保岁寒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["炎凉多反复，日月易循环，但愿岁岁年年人康健。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["玉人弹唱声声慢，露春纤把锦筝低按，曲罢酒阑人散。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"谒金门","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［小外，杂从上］简命分专邦甸，报国存心文献；蒲鞭枉昭公椽，三载民无怨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"鹧鸪天","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["千里承恩秉郡旄，矢心曾不染秋毫。", "公门既许清如水，吏笔何须利似刀？无德政，起童谣，聿修文书赞皇朝。", "愿将廉范龚黄意，布政瓯城教尔曹。", "自家温州府太守吉天祥是也。", "即今宾兴之秋，又当堂试之日，下官今日考试诸生。", "左右，唤秀才进来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"转山子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末扮学官上］六经惭负管窥天，可信灯毡恁有缘。", "士子作章编，争望登高选。", "送生员手本。", "［外］趱生员进来，教官出去罢。", "［末应下］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"水底鱼","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］仰之弥高，钻之弥坚，忽焉在后，赡之忽在前。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］学问无边，如人临广渊。", "意深趣远，玄玄复又玄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］身似神仙，金银积万千。", "无心向学，终朝只爱眠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红衲袄","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］问：古人君所以贤，古人臣所可言，圣王汲汲思为善，为善还当何者先？子辈灯窗已有年，所得经书学问渊。", "悉心为我敷陈也，毋视庸常泛泛然。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］对：古明君在重贤，古良臣贡举先。", "巫咸傅说初皆贱，伊尹曾耕莘上田。", "皋陶既举不仁远，四皓出而汉祚安。", "恭承执一询遇见，敢不谆谆露胆肝？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］对：古贤王在猎畋，古贤臣开垦先。", "孟轲十一言犹善，八口同耕井字田。", "庸言\"民乃国之本\"，故曰\"食为民所天\"。", "躬承执事询愚见，敢不粗心进数言？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］对：古刚明须积钱，臣奉行须聚敛。", "治财理赋称刘晏，功数萧何馈饷先。", "征粮时要他加二三，粮完时赏疮一个钱。", "若今府库充盈也，大敌闻之不敢言。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"荷叶鱼儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］春雨新收，喜见山明水秀，万花深处有鸣鸠，软红泥踏青时候。", "试蹑青鞋，慢拖斑竹，去寻良友。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］静把诗书闲究，竹扉上是谁频扣？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三学士","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["弱息及笄姻未偶，故米拜屈问游，书生已露魁人手，山老因营继嗣谋。", "［合］若得良媒开笑口，这求亲愿必酬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［太］解绶归来为至友，果然同气相求。", "尔玉人窈窕钟闺秀，那君种子殷勤须好逑。", "［合］管取两门开笑口。", "这求婚愿必酬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］谨领尊言求风偶，管教配合鸾俦。", "云英志不存田玉，织女期当订斗，牛。", "［合前］管取。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"绕地游","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦上］桑榆暮景，将往事空思省。", "家贫窘，闷怀耿耿。", "共姜誓盟，慕贞洁甘守孤零，喜一子学问有成。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风人松","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］青霄万里未鹏抟，淹我儒冠；布袍虽拟蓝袍换，荣枯事皆由天断。", "且自存心奉母，何须着意求官？母亲拜揖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黄莺儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["半世守孤灯，镇朝昏儿几泪零，到今犹在凄凉景。", "寒门似冰，衰鬓似星。", "［生］母亲为何掉泪？［老旦］为只为早年不幸鸾分影。", "［合］细评论，黄金满簸，不如教子一经。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］父丧母劳形，论孩儿当报恩，奈何人事不相称。", "［老旦］只怕你学未成。", "［生］非学术成。", "［老旦］只怕你己未能。", "［生］非己未能，为只为五行不顺男儿命。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"簇御林","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］亲师范，近友朋，把诗书勤讲明。", "聚萤凿壁真堪敬，他们都显父母、扬名姓。", "［合］奋鹏程，名题雁塔，自屋显公卿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］亲年迈，家势倾，恨腴甘缺奉承。", "卧冰泣竹真堪并，他们都感大地、登台省。", "［合前。", "末上］受人之托，必当终人之事。", "钱贡元央老夫到王宅议亲。", "此间有人么？［老旦］儿，有人在外，你去看。", "［生］待孩儿去看。", "呀！老将仕，失迎了。", "［末］令堂有么？［生］家母有。", "［末］老夫求见。", "［生］少待。", "母亲，许将仕在外。", "［老旦］请进来。", "［见介］许大人请。", "重蒙贵步到寒家，有何见谕？［末］老夫非为别事，只因钱贡元前番央老夫来说令郎亲事，老安人不允。", "近闻得贤郎堂试魁名，贡元不胜之喜。", "今着老夫送吉贴到宅，望乞安人允就，不必推辞。", "［老旦］多蒙贡元见爱，又蒙将仕周全。", "只是家窘，不敢应承。", "［末］贡元说道：不问人家贫富，只要女婿贤良。", "聘礼不拘轻重，随意下些，便可成亲。", "［老旦］贡元乃丰衣足食之家，老身乃裙布荆钗之妇，惟恐见诮。", "［末］安人何必太谦！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桂枝香","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］年华衰边，家私穷败，要成就这段姻亲，全赖高贤担带。", "论才难布摆，论才难布摆，钱难揭债，物无借贷。", "［拔钗介］儿，自你父亲亡后，再无所遗，止有这荆钗，权把他为财礼，只愁事不谐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］萱亲宁耐，冰人休怪。", "小生呵！贫居陋室多年，惟苦志寒窗十载。", "倘时运到来，倘时运到来，功名可待，姻亲还在。", "母亲，这荆钗又不是金银造，如何做聘财？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］女人容拜。", "秀才听解。", "那贡元呵，不嫌你礼物轻微，偏喜爱熟油苦菜。", "但心无忌猜，但心无忌猜，物无妨碍，人无杂坏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秋夜月","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］家富豪。", "少甚财和宝？未毕姻亲，萦牵怀抱。", "只因命犯孤星照，没一个老瓢。", "自家号做孙汝权，牛羊无数广田园。", "无瑕美玉白似雪，没孔珍珠大似拳。", "白银积下如土块，黄金堆垛似方砖。", "温州城里第一个财主，件件称心，样样如意。", "说也惶恐，夜夜缩脚眠。", "前日学中回来，偶见一家门径里面四个大字：\"为善最乐\"。", "正看之际，闪出二八佳人，生得描不成，画不就，十分美貌。", "若得此女为妻，不枉了今生一世。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻云飞","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["思忆多娇，想他十指纤一捻腰，两瓣金莲小，赛过西施貌。", "妖，其实是俊多娇，想他身材小巧，教我日夜相思，日刻萦怀抱。", "若得成亲，我也不枉了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"秋夜月","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["蒙见招，打扮十分俏，走到门前人都道，道奴奴脸上胭脂少，搽些又好，抹些又俏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"豹子令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["闻说佳人多袅娜，多袅娜，端的容貌赛嫦娥，赛嫦娥。", "此亲若得周全我，酬劳财礼敢虚过。", "［合］花红羊酒谢媒婆。", "［丑］成亲之后，就是姑婆。", "［净］朱吉，你牵羊担酒谢姑婆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］非是冰人说强呵，说强呵，成败都是女萧何，女萧何。", "若是才郎拚财礼，管教织女渡银河。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"似娘儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］一女貌天然，缘分浅。", "亲事迁延。", "愿天早与人方便，丝萝共结，蒹葭可倚，桑梓相联。", "\"男子生而愿为之有室，女子生而愿为之有家。", "\"老夫昨央将仕王宅议亲，回来便知端的。", "［末上］伏托荆钗成好事，何须红叶作良媒。", "昨蒙贡元央我王宅议亲，不免回覆。", "有人么？［外］将仕，有劳动问，亲事如何？［未］老夫初到王宅，说起亲事，王老安人再三推辞。", "已后将尊言说明，谗得允从。", "［外］将何物为聘？［末］聘物虽有，只是轻微，将不出。", "［外］老夫有言在先，不拘轻重，只要成其姻事。", "［末］聘物在此，请收。", "［外］好罕物。", "昔日汉粱鸿聘孟光荆钗，至今遗下，岂不是达古之家？老安人那里？［净争上］\"姻缘本是前生定，曾向蟠桃会里来。", "\"那个在此？［外］是将仕。", "［净］不是来说我儿亲事么？［外］正是。", "［净］李成看茶来。", "将仕公，外日多蒙厚礼，我说李成去请将仕公来吃些寿面，说你不在家；一钵头面，放了三日，把与狗吃了。", "［外、末］这什么说话？［净］敢问将仕，说我女儿亲事怎么了？［末、外］亲事已成了。", "［净］既成了，几时下盒子？［末、外］就是今日。", "［净］今日教我怎么安排得酒与来人吃？［末］都是干折，袖里来，袖里去。", "［净］看鸡鹅污屎，坏了衣服。", "［末］不是这个干折。", "［净］小厮讨天平来。", "［外］要天平做什么？［净］要他兑银子。", "［外］银子希什么罕？［净］银子不希罕，什么希罕？［外］一股荆钗，只怕你不晓得。", "［净］你拿来我看。", "多少年纪，不晓得这是什么东西。", "闻又不香，拿在手又不重，待我磨一磨。", "［外］这是宝贝，擦不得的。", "［净］人到禁擦，他到不禁擦。", "［外、末］什么说话？［净］这味头簪子，一分银子买了十根，讨得十个媳妇。", "［外］不要多说。", "［净］我晓得。", "当初汉梁鸿仗他讨了个娘子，如今又将来讨我女儿，是二婚人了。", "［末］休得取笑。", "［净］你便说何人置造，甚人遗下的？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"柰花子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］论荆钗名本轻微，汉梁鸿已仗得妻，芳名至今留传于世。", "老安人，休将他恁般轻视，听启，明说道表情而已。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］虽然是我女低微，他将我恁般轻觑。", "一城中岂无风流佳婿？老员外，偏只要嫁着穷鬼。", "老许，你做媒氏，疾忙与我还他的财礼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］这财礼虽是轻微，你为何讲是说非？婆子，你不晓得，那王秀才是个读书人，一朝显达，名登高第，那其间夫荣妻贵。", "这财礼呵，纵轻微，既来之，且宜安之。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］富家郎央我为媒，要娶我侄女为妻。", "说开说合，非同容易，也全凭虚心冷气。", "匹配，端的是老娘为最。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］才貌兼全，亲老家贫囊又艰，羞杀荆钗裙布，绣褥金屏，绮席华筵。", "好姻缘番做恶姻缘，富亲眷强似穷亲眷。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］五百年前，月老曾将足系缠，不用诗题红叶，书附青鸾，玉种蓝田。", "瑶池曾结并头莲，画堂中已配豪家眷。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"恋芳春","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦止］宝篆香消，绣窗日永，又还节近清明。", "暗里时更换，月老逼椿庭，惟愿双亲福寿康宁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一江风","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["绣房中，袅袅香烟喷，翦翦轻风送；但晨昏问寝高堂，须把椿萱奉。", "忙梳早整容，忙梳早整容，惟勤针指功，怕窗外花影日移动。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["听鹊鸦，噪得我心惊怕，有甚吉凶话？念奴家不出闺门，莫把情怀挂。", "依然绣几朵花，依然绣几朵花，天生怎比他？再绣出蔷薇架。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"青哥儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］豪门议亲，哥哥嫂嫂已许谐秦晋。", "未审玉莲肯从顺，且向绣房询问。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州序","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["他家私迭等，良田万顷，富豪声振瓯城。", "他又不曾婚聘，专浼我来求亲。", "［旦］他恁的钱物昌盛，愧我家寒貌丑难厮称。", "［丑］这段姻缘料想是前生定，入境缘何不顺情？休得要恁执性。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］你爹娘俱已应承，问侄女缘何不肯？恁推三阻四，莫不是行浊言清。", "［旦］枉了将人凌并，便刎下头来，断然不依允。", "［丑］论我作伐，宅第尽闻名。", "十处说亲九处成，谁学你假惺惺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］做媒的，［丑］做媒的不是做贼的。", "［旦］做媒的个个夸能，也多有言不相应，信着你都被误了终身。", "［丑］合穷合苦没福分。", "丫头强厮挺，令人怒憎。", "［旦］出语伤人，你好不三省，荣枯事总由命。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］这段姻缘非厮逞，少什么花红送迎？［旦］谁想番成作画饼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"福青歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］只因我女娇媚，富家郎要结姻契。", "姑娘在此作良媒，寻思道理，强如嫁着穷鬼。", "常言道：\"会嫁嫁田庄，不会嫁嫁才郎。", "\"好笑我老儿将女儿许嫁王十朋，姑娘来说的温州城内第一个财主孙汝权。", "如今姑娘绣房中与女儿议亲，待姑娘来便知端的。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"七娘子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］芳心未许春搬弄，傍纱窗绣鸾刺风。", "［净］玉莲。", "［旦］母命传呼，奴当趋奉。", "金莲轻举湘裙动。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锁南枝","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］休发怒，免性焦，一言望乞听奴告。", "这聘礼荆钗，休恁看得小。", "［净］是金的？［旦］非是金。", "［丑］敢是宝。", "［旦］非是宝。", "［净］非金非宝，要他何用？［旦］将来聘奴家，一似孟德耀。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净、丑］听他道，越气恼，无知贱人不听教。", "因甚苦死执迷，惹得娘焦燥？他礼物有甚好？比着玉镜台，羞杀晋温峤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四换头","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["贼泼贱闭嘴，数黑论黄讲甚的？我是你什么人？［旦］是娘。", "［净］恰又来，娘言语怎违逆？颐父母颜情却是礼。", "［旦］顺父母颜情，人之大礼。", "话不投机，教人怎随？富豪贪恋，贫穷见弃，惹得傍人讲是非。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］呆蠢丫头，出语污人耳。", "恁推三阻四，话不投机。", "豪家求汝效于飞，他有甚相亏？出言抵撞，你好没尊卑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］非奴失礼仪，望停嗔，听拜启。", "婚姻事有之，恐误了终身难改移。", "［净］嫁去好，多住几日，不好，回来再嫁。", "［旦］怕一时贪富侈，恐船到江心补漏迟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净、丑］好言劝你，再三阻推。", "娘是何人你是谁？［旦］母亲暂息雷电威，休恁自差池。", "今日里缘何将我苦禁持？［净］自今和你做头敌。", "［旦］谩威逼，断然不与孙氏做夫妻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"破阵子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］翠黛深笼宝镜，蛾眉懒画春山。", "丝萝虽喜依乔木，椿树还怜老岁寒，偷将珠泪弹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉交枝","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］音容不见，望冥中听奴诉言，甫离怀抱娘恩断，目应怎瞑黄泉。", "谁知继母心太偏，逼奴改嫁相凌贱。", "我那亲娘，孩儿今日出嫁，本待做一碗羹饭与你，料他决不相容。", "苦！莫说羹饭，我要痛哭一场，［合］怕他们闻之见嫌，只得且吞声泪痕如线。", "我的亲娘在日，岂是今日？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["不能光显，叹资装十元一完。", "爹爹，母亲，荆钗裙布奴情愿。", "只是我爹爹年老在堂，奴家去后，叹无人膝下承颜。", "我的亲娘，七岁抛离了你，受他折磨难尽言。", "孩儿倘有一些差处，非打即骂，他全无骨肉亲相脊。", "［合前］［外上］荆钗与裙布。", "随时逼婚嫁。", "［丑上］三夜不息烛，相思何日罢。", "［外］我儿，哭得这等模样，你在此怎么？［旦］我在此别母亲神主。", "［外］我的儿，。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忆多娇","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["你且开镜奁，锭翠钿，休得界破残妆玉箸悬。", "今日我做爹爹的肮脏了你，首饰全无真可怜。", "［合］休得愁烦，喜嫁个读书大贤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］愁只愁你子嗣悭，爹老年，何忍教儿离膝前。", "爹爹，你与母亲不谐，孩儿去了，凡事忍耐些罢。", "莫惹闲非免抟牵。", "［合前。", "丑］我儿，你若依了我，嫁了孙家，大样妆奁，十分富贵。", "今日什么来由，到嫁这个穷鬼？［外］你好胡说！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"斗黑麻","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["自古姻缘事，非偶然，五百年前，赤绳系牵。", "儿今去，听教言：我的儿，你到王门做媳妇，勿慢勿骄，必钦必敬。", "孝顺姑嫜，数问寒暄。", "［合］灯前泪涟，生离各一天。", "他有日归宁，吾心始安。", "我儿上轿去罢。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["蒙教养成人，恩同昊天。", "［净内应］我又不是你亲娘，说什么昊天！［旦］我的娘，虽不是你亲生，多蒙保全。", "儿别去，免忧煎。", "娘，你是个年老之人，休惹闲气，倘爹爹有些不是处，忍耐些罢！努力加餐，望把愁颜变笑颜。", "［合］灯前泪涟，生离各一天。", "［外］我儿，他衣饰也无一件与你，哭他怎么？［旦］裙布荆钗，奴身自便。", "［丑］侄女儿，拜了爹爹，上轿去罢！［外］不要拜了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["半壁孤灯相吊影，萧萧白发盈颠。", "那堪弱息离身边，叮咛辞别去，情痛不成干。", "［哭下］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风马儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦上］株守蜗居事桑蚕，形憔悴、鬓蓝参。", "［生上］家寒世薄精神减，凄凉一担，母忧愁，子羞惭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"琐寒窗","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］这门亲非是我贪婪，无奈人来说再三。", "送荆钗只愁富室褒谈，良媒竟没一言回俺，反教娘挂肠悬胆。", "［合］早间只闻得鹊噪窗南，有何亲旧相探？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］叹连年贫苦多谙，尤在凄凉一担担，事萱亲、朝夕愧缺腴甘。", "劬劳未答，常怀凄惨。", "议姻亲，断然不敢。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末、净上］论人生嫁女婚男，不是姻缘怎妄贪。", "谩夸他豪门首饰衣衫。", "娇娥志洁，甘居清淡。", "那听他巧言啜赚。", "这姑姑闲此脸羞惭，此来必定喃喃。", "此间已是。", "有人么？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"宝鼎儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］亲送侄女临门，管取今朝沈醉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"花心动","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］适遣匆匆，奈眉峰慵画，鬓云羞笼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"惜奴娇","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["只为家道贫穷，守荆钗裙布，谨身节用。", "今为姻眷，惟恐玷辱亲家门风。", "［旦］空空，愧乏房奁来陪奉，望高堂垂怜宠。", "［合］喜气浓，悄似仙郎仙女，会合仙宫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］欣逢，夫婿宽洪，可留心遵守，四德三从。", "［末］勤攻诗赋，休得要效我飘蓬。", "［生］重重，命蹇时乖长如梦。", "［老旦］谢良言，开愚懵。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］愚蒙，欲步蟾宫，奈才疏学浅，未得飞冲。", "愧无能，岂宜先自乘龙？［丑］雍雍，才郎但显功，娇妻拟赠封。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锦衣香","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］夫性聪，才堪重；妇有容，德堪重，天生美质奇才，彩驾丹凤。", "［生］自惭非是汉梁鸿，何当富室，配着孤穷。", "［旦］念妾非孟光，奉亲命遣侍明公。", "今日同欢共，蓝田玉曾修种。", "夫和妇睦，琴调瑟弄。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"浆水令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］恕贫无香醪泛钟，恕贫无美食献供。", "［丑］又无些汤水饮喉咙。", "妆甚么大媒？做甚么亲送？［末］休相笑，莫妄冲，惟恐外人相讥讽。", "［老旦］非缺礼，非缺礼，只为窘中。", "凡百事，凡百事，望乞包笼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［众］佳人才子德堪重，更人才又兼出众，夫妻到老永和同。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"出队子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］追思前事，追思前事，心下如同理乱丝。", "虽然颇颇有家私，争奈年高无后嗣，怎不教人日夕怨咨！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"好姐姐","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］听吾一言说与，那王秀才欲求科举。", "他若去时，必定家空虚。", "［合］堪忧虑，形只影单添凄楚，暮想朝思愈困苦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］解元为功名利禄，他应难免分开鸳侣。", "妻孤母独，怎不愁满腹。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］我欲把西边空屋，相请他萱亲媳妇，移来并居，早我相看顾。", "［合］亲骨肉，及早取来同居住，彼此心欢意满足。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］小仆蒙东人付嘱，到彼处传说衷曲。", "他闻此语，拟定无间阻。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"挂真儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦上］天付姻缘事谐矣，夫和妇如鱼似水。", "［生上］贫处蜗居，羞婚燕尔，惟恐旁人谈耻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"宜春令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["恩东命，遣仆来上覆，近闻说官人赴帝都。", "解元出路，料想家中，必定添凄楚。", "老员外呵，意欲把西首房屋，待相邀安人居住。", "为此特令男女，到宅传语。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］蒙错爱，为眷属，这恩德深铭肺腑。", "奈缘艰苦，迤逦不能勾参岳父。", "到如今又蒙相呼，顿教娘心中犹豫。", "试问我孩儿媳妇，怎生区处？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］因科举，欲赴都，免不得抛妻弃母。", "千思百虑，母老妻娇，却教谁为主？既岳翁惜寡怜孤，这分明爱枝惜树。", "且自随机应变。", "慎勿推阻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］大出路，百事无。", "况家中前空后虚，晨昏朝暮，虑恐他人生嫉妒。", "既相招共处同居，暂离这荜门蓬户。", "末审婆婆夫主，意中何如？［老旦］媳妇，既如此，你道怎么不去？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"绣衣郎","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦、生、旦吊场］［老旦］半生在陋室幽牺，乐守清贫苟度时。", "重蒙不弃，大厦于间相周庇。", "望孩儿异日荣贵，报岳翁今日恩义。", "［合］愿从今奋鹏程万里，愿从今奋鹏程万卫！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］自历学十载书帏，黄卷青灯不暂离。", "春闱催试，鏖战功名在科场内。", "金弯殴拟着荷衣，广寒宫必攀仙桂。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］想苍天不负男儿，一举成名天下知。", "倘登高第，雁塔题名身荣贵。", "若能勾赠母封妻，也不枉了争名夺利。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］黄河尚有澄清日，岂可人无得运时？［旦］皇都得意，那时好个风流婿。", "［生］我寒儒显赫门楣，太岳翁传扬名誉。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"卜算子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］从别女孩儿，心下常萦系。", "昨日令人去请归，彼此心欢喜。", "雪隐鹭鸶飞始见？柳藏鹦鹉语方知。", "昨日着李成去搬取王亲妈、秀才与我女孩儿同家另居。", "待李成回来，便知分晓。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"疏影","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦上］韶光荏苒，叹桑榆暮景，贫困相兼。", "［旦上］半载忧愁，一家艰苦，末知何日回甜。", "［生上］衣单食缺心无歉，为亲老常怀凄惨。", "［末上］安人贤会，秀才儒雅，小姐贞坚。", "老安人，这里正是本宅门首，待小人进去通报。", "老员外，老安人、秀才官人、小姐都来了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"降黄龙","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["草舍茅檐，蓬荜尘蒙，纲罗风风召。", "尊亲到此，但有无一一望亲遮掩。", "［老旦］恩沾，万间周庇，悄似寒灰拨焰。", "使穷亲欢生愁腹，喜生愁脸。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］安然，问效鹣鹣，为取功名，顿成抛闪。", "君今此行，又恐怕贪荣别娶娇艳。", "［生］休言，我守忠信，自古道\"贫而无谄\"，肯贪荣忘恩负义，附热控炎？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］叨忝，母训师严，三史谙通，九经博览。", "今承召举，到试闱定有朱衣头点。", "［外］孩儿，丈夫远行，你也递他一杯酒。", "［旦］奴家晓得了。", "［唱］春纤，捧觞低劝，好将心事拘钳。", "到京师闲花野草，慎勿沾染。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黄龙滚","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］休将别泪弹，休将别泪弹！且把愁眉敛。", "背井离乡，谁敢胡沾染？［老旦］路途迢递，不无危险。", "才日暮，问路程，寻宿店。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］萱亲免愁烦，萱亲免愁烦！岳丈休忆念。", "［老旦］记取叮咛，客邸当勤俭。", "［外］此行只愿鳌头高占，功名遂，姓字香，门楣显。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］随身不虑无琴剑，虑只虑行囊缺欠。", "［外］些少白金相助添。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"临江仙","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["渡水登山须仔细。", "［外］贤婿，朝行须听晓鸡啼。", "［旦］官人，成名先寄好音回。", "［末］王官人，蓝袍将挂体，及第便回归。", "［生］重荷萱亲勤训诲，感蒙岳丈提携。", "娘子，好生侍奉我亲帏。", "李成，在家勤照顾。", "［末］及第便回归。", "［旦扯生介］半载夫妻成拆散，婆婆年老怎支持？成名思故里，切莫学王魁！［生］你不须多嘱付，我及第便回归。", "［生先下。", "众吊场］正是\"流泪眼观流泪眼，断肠人送断肠人。", "\"［外］孩儿，你夫婿上京取应，好把婆婆恭敬。", "［旦］甘旨一一趋承。", "谨依爹爹严命。", "［老旦］多幸多幸，骨肉团圆欢庆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"园林好","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["深感得亲家见怜，助白银恩德万千。", "更广厦容留，贫贱得所，赐喜绵绵。", "蒙所庇，意拳拳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"沈醉东风","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］我孩儿三生有缘，与才郎忝为姻眷。", "今日赴春闹，程途遥远。", "论盘费，尚忧轻鲜。", "［旦］婆当暮年，父当老年，只愿我儿夫荣归故苑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"川拨棹","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］他凭取才学上京赴选，又恐怕他功名缘分浅。", "［末］老安人且莫萦牵，那秀才文章灿然。", "管登科，作状元。", "管登科，作状元。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红绣鞋","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］旦夕祝告苍天，周全。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["从今且把眉舒展，遇良辰自宜消遣，骨肉永远团圆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"水底鱼","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］天下贤良，赴选临帝乡。", "白衣卿相，暮登天子堂。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］为功名纸半张，引得吾辈忙。", "人人都想，要登龙虎榜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］有等魍魉，本是田舍郎，妆模作样，也来入试场。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"甘州歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］自离故里，谩回首家乡，极目何处？萱亲年老，一喜又还一惧。", "晨昏幸托年少妻，深感岳丈相怜一处居。", "［合］蒙嘱付，牢记取，教我成名先寄数行书。", "休悒怏，莫嗟吁，白衣换却锦衣归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］芳春景最奇，正可人不暖不寒天气。", "千红万紫，开遍满目芳菲。", "香车宝马逐队随，只见来往游人浑似蚁。", "［合］争如我，折桂枝，十年身到凤凰池。", "身荣贵，回故里，人人都道状元归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］迤逦松篁迳里，见野塘溶溶水没沙嘴。", "鸥凫往来，出没又还惊飞。", "危桥跨涧人过稀，只见漠漠平沙接远堤。", "［合］途中趣，真是奇，绿杨枝上啭黄鹂。", "难禁受，闻子规，声声叫道不如归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［众］闻知皇都近矣，尚还隔几重烟水。", "餐风宿水，岂惮路途迢递。", "一心指望入试闱，恨不得肋生双翅飞。", "［合］寻宿处，莫待迟，竹篱茅舍掩柴扉。", "天将暮，日坠西，渔翁江上钓鱼归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["问牧童，归村市，香醪同饮典春衣，图得今宵沈醉归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"夜游朝","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外，杂从上］锦袍银绶掌春宫，辅佐承明一统。", "圣主求贤心重，网罗天下英雄。", "乌纱玉带紫金鱼，出入千人拥一车；若问荣华何自至，少年曾读五车书。", "下官蒙差考试，为天子之辅臣，系文章之司命。", "荣身食禄，岂容尸位素餐；报主匡时，敢不矢心殚力？今当会试之春，命主礼闱。", "天下英才，雪屯蚁聚。", "左右，举子入试者，用意搜检，以防怀挟。", "着他鱼贯而进！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"水底鱼","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］天降坚恩，诏我众书生。", "鱼龙变化，直上九霄云。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］慈亲衰倦，弟兄无一人。", "无人奉养，时刻常挂心。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］我是文人，声名天下闻。", "若还高中，管取第一名。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黄莺儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生］鲁史纪周正。", "［外］正名之实，何者为先？［生］重明伦，先正名。", "先明王霸之分。", "尊正贱霸功难泯。", "［外］五霸桓文为盛，事业如何？［生］齐桓公会诸侯于葵丘，次师召陵以伐楚。", "晋文公会诸侯践土，天王狩于河阳。", "葵丘序盟，召陵誓兵，河阳践土诚陵分。", "［外］春秋以赏罚为事，无乃为僭乎？［生］春秋天子之事也。", "故仲尼曰：\"罪我者，其惟春秋乎？知我者，其惟春秋乎？\"细推评，刑诛爵赏，准以素正情？［外］此篇深得春秋赏罚之旨，真内圣外王之学也。", "可喜可喜。", "地字号把你本经做一篇来！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］五典与三坟，见重华，思放勋。", "［外］昔左史倚相，能读坟典丘索之书。", "子亦能是乎？［末］不敢，此分内事也。", "九丘八索扦能省。", "［外］既然读上古书，且说\"欲为君尽君道，欲为臣尽臣道\"二者当法何人？［木］君人之道，至文武而尽。", "人巨之义，当以伊周为法。", "文谟克勤，武烈继明，商衡周鼎辉相映。", "［外］\"如或知汝，则何以哉？\"［末］有用我者，务引君当道而已。", "际风云，盐梅舟楫，一德务臣君。", "［外］此篇深有宰辅器量。", "深为朝廷得人贺也。", "人字号把你本经做一篇来看！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］四圣旨弥纶，道阴阳，说鬼冲。", "［外］易主卜筮者，说可信么？［净］圣人作易，神以知来，知以藏往，是故知幽明之故。", "知来藏往昭无朕。", "人根杳冥，月窟浑论。", "［外］何为天根，何为月窟？［净］尧夫云：\"乾遇巽时观月窟，地逢雷处见天根。", "\"［外］夏商之时，易有何名？［净］夏易首艮，是曰连山；商易首坤，是曰归藏。", "皆无足传者。", "连山云断归藏隐。", "［外］此子年齿虽逾，学识颇到。", "［净］不敢。", "我学生八八六十四卦，三百八十四爻，无不精晓。", "［外笑］可知你日亲笔砚？［净］惶恐。", "且休颦，书编三绝，观国利王宾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风检才","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［众上］举子读书大贤，锦绣文章可观；象简罗袍恁你穿，宫花插帽檐偏。", "［合］头名是王状元！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"破阵子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］灯灿金花无寐，尘生锦瑟消魂。", "凤管台空，鸾笺信杳，孤帏不断离情。", "巫山梦断银缸雨，绣阁香消玉镜蒙。", "十朋，休怨怀想人。", "妾惭非淑女，父命嫁洪儒。", "矢心共贫素，布荆乐有余。", "旦夕侍巾栉，齐眉愧不如。", "两情正欢洽，一旦赴征书。", "折此蓝田玉，分我合浦珠。", "翠钿空零落，绿鬓渐萧疏。", "登楼试晚妆，镜破意踌躇。", "羞看舞双燕，交彩人空虚。", "况有高堂亲，忧怀日倚闾。", "愿言还游子，及早赋归欤。", "奴家自从才郎别后，每日鸡鸣而起，敬奉姑嫜，勤事父母。", "如今天尚未明，意欲对镜梳妆，争奈离愁千种，想起别时，不觉垂泪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["时光似箭如梭掷，勤把萱亲奉侍，专等儿夫返故里。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"贺圣朝","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］几年职掌朝纲，四时变理阴阳；一人有庆寿无疆，兆民赖之安康。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"菊花新","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］十年身到凤凰池，一举成名天下知。", "脱白挂荷衣，功名遂，少年豪气。", "引领君仙下翠微，云间相逐步相随；桃花已透三千丈，月桂高攀第一枝。", "阆苑应无先去客，杏园惟有后题待；男儿志气当如此，金榜题名天下知。", "小生得了头名状元，深蒙圣恩，除授饶州佥判。", "方已朝回，必须参见万俟丞相。", "［末见科］状元贺喜。", "［生］何喜可贺？［末］丞相有一多娇小姐，欲招状元为婿，只今便要成亲。", "［生］小生自有寒荆在家，焉敢望此？烦请通报。", "［末］少待。", "［介］告垂相，状元已在门首。", "［净］着他进来见我。", "［末］请状元进去相见。", "［生见拜介］小生一介寒儒，久困山泽，郡乏贤才，勉使来试。", "忝蒙天眷，皆赖丞相提携之赐。", "谨造钧墀参拜，不胜愧感之至。", "［净］状元。", "且休闲说，休闲讲。", "我有一事与你说：\"男子生而愿为之有室，女子生而愿为之有家。", "\"我有一女，小宇多娇，欲招你为婿，只今就要成亲。", "你心下如何？［生］深蒙不弃微贱，感德多矣。", "奈小生已有寒荆在家，不敢奉命。", "［净］你是读书之人，何故见疑。", "自古道：\"富易交，贵易妻。", "\"此乃人情也。", "［生］丞相岂不闻宋弘有云：\"糟糠之妻不下堂，贫贱之交不可忘。", "\"小生不敢违例。", "［净怒］我到违例！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"八声甘州歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["穷酸魍魉，对我行辄敢数黑论黄，妆模作样，恼得我气满胸膛！［生］平生颇读书几行，岂敢紊乱三纲并五常。", "［末］斟量，不如且顺从公相何妨？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］你千推万阻，靡恃已长，只怕你舌剑唇枪反受殃。", "［生］谩自相劳让，停妻再娶谁承望？有何故，共受殃？［净］朝纲选法咱把掌，使不得祸到临头烧好香。", "不轻放，定改除远方，休想还乡。", "［净］堂候官，与我赶出去！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉落魄","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［生上］乡关久别应多虑，幸登高第得铨注；修书欲寄报平安，浼承局，带回家去。", "亏心折尽平生福，行短天教一世贫。", "念小生贫寒之际，以荆钗为聘，遂结姻亲。", "临行又蒙岳丈接取母亲妻子一同居住，仍赠盘缠赴京，得了头名状元。", "深蒙圣恩，除授饶州佥判。", "本欲回乡视亲，不合参见万俟丞相，反要招我为婿。", "只因不从，被他拘留听候，不得回乡。", "只得写封家书回去，通报母亲妻子知道。", "我昨日在省门外，有一承局差往温州下文书，与他说了，约我今日来取书。", "待我写完，在此等他。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一封书","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["男百拜拜覆母亲尊前妻父母：离膝下到都，一举成名身挂绿。", "蒙除授饶州佥判府，待家眷临京往任所。", "寄家书，附承局，草草不恭儿拜覆。", "书已写完，在此等待承局到来。", "［末上］传递急如火，官差不自由。", "自家承局的是也。", "公差到浙江递送公文；昨日王状元与我说，要寄家书回去，不免到下处取书。", "［生］承局，起动你来了。", "［末］状元写完家书未曾？［生］写完在此了。", "［末］既完了，送在那里去？［生］此书烦附与温州在城双门巷里钱贡元家下。", "［末］状元姓王，为何到钱宅？［生］是我岳丈家中。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"懒画眉","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["烦伊传递彩云笺，你到吾家可代言。", "［末］代言怎么说？［生］因参相府被留连，不能勾归庭院，传与我萱亲莫挂牵。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］状元深念北堂萱，料想尊堂忆状元。", "泥金先把好音传，他必定生欢忭，正是-纸家书抵万钱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双劝酒","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］儒冠误身，一言难尽。", "为玉莲贱人，常怀方寸。", "若得他配合秦晋，那其间燕尔新婚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］官差限紧，心中愁闷。", "途路上苦辛，怎辞劳顿。", "只恐怕误了公文，那其间有口难分。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"刘泼帽","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］念我到此求科举，因不第、羞回乡里。", "修书欲报娘和父，欲烦捎带，只怕相推阻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］自家虽在京城住，温台路来往极熟。", "官人若有家书附，休得要踌躇，咱与你捎回去。", "［净］承局哥，既蒙允肯，同到下处写书与你。", "［末］如此同行。", "［净］这里便是下处，请坐。", "［末］不敢。", "［净］承局哥，我本待留你吃一杯淡酒，怎奈客边恐怕简慢你。", "今奉白银一钱，自去酒肆中去吃三杯；待我写完了书，你再来取。", "［末］多谢！无功蒙厚禄，不敢受。", "［净］亵渎尊前，请收了。", "［末］如此受了。", "我去吃了酒，官人你写完了，我就来取。", "［净］我就在此写。", "［末下介，净叫介。", "末］孙官人，怎么又叫我？［净］我与你说，这个包儿，倘若到酒肆中吃醉了，这包儿放在那里，不如放在此。", "吃了酒一发来取。", "［末］我晓得，你说道我拿了一钱银子去了，不来取书，拿我包在此做当头。", "［介］我便放在此，你不要动，里面有王状元的书在里面。", "［净］我生疔疮也不动。", "［末］自沽三酌酒，早写万金书。", "［末下。", "净吊场］不施心上无穷计，怎得他人一纸书？想承局去远了，我把包袱开将起来。", "且喜王状元书已在此，待我读一遍。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"清江引","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["求名未遂，羞归乡里，淹滞在京都地。", "拜覆我爹娘，休把儿牵系，指日间到家庭，重贺喜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"朱奴儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］因科举离乡半春，从别后断羽绝鳞。", "今日天教遇你们，趁良使附归音信。", "［合］还历尽山郭水村，指日到东瓯郡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］是则是公文限紧，蒙相委怎敢不允？拚十朝与半旬，到宅上备说原因。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"临江仙","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦上］凭栏极目天涯远，那人去远如天。", "［旦上］鳞鸿何事竟茫然？今春看又过，何日是归年？［老旦］春闱催试怕违期，一纸音书绝雁鱼；［旦］此去定应攀月桂，拜恩衣锦听荣除。", "［老旦］自从你丈夫去后，杳无音信回来。", "［旦］婆婆，想没有便人。", "［老旦］我与你倚门而望。", "［旦］婆婆请先行，奴家随后。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"傍妆台","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］意悬悬，倚门终日，望得眼儿穿。", "自他去京历鏖战，无一纸信音传。", "［旦］多应他在京得中选，因此上无暇修书寄故园。", "［老旦］他既登金榜，怎不锦旋，越教娘心下转萦牵。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］何劳忧虑恁拳拳，且自把愁眉暂展闲消遣。", "虽眼下人不见。", "终有日再团圆。", "［老旦］愁只愁他命乖福分浅，又恐怕客邸淹留疾病缠。", "［旦］死生有命，富贵在天，不须忧虑泪涟涟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"不是路","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末上］渡口离船，早来到钱家宅院前。", "咱不免、偷闲先下彩云笺。", "［老旦］甚人言？因何直入咱庭院？［末］为一举登科王状元。", "［老旦］那个王状元？［末］就是王十朋状元。", "［老旦、旦］可有书么？［末］因来便，特令捎带家书转。", "［老旦、旦］喜从人愿，喜从人愿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］先生，他为何不整归鞭？付与你书时说甚言？［末］教传语，道因参丞相被留连。", "［旦］婆婆，留连不得回来了。", "［老旦］媳妇，且省忧煎，可备些薄礼酬劳倦。", "［旦］就把银钗当酒钱。", "［老旦］物轻鲜，权充路费休辞免。", "［末］小人公文紧急，不敢久稽，多谢了。", "去心如箭，去心如箭。", "［下］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"皂角儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］想连年时乖运蹇，喜今日姓扬名显。", "步蟾宫高攀桂枝，跳龙门首登金殿。", "把宫花斜插在帽檐边，琼林宴，胜似登仙。", "［合］早辞帝辇，荣归故苑，那时节，夫妻母子大家欢忭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］想前生曾结分缘，与才郎共成姻眷。", "喜得他脱白挂绿，怕嫌奴体微名贱。", "若得他贫相守，富相连，心不变，死而无怨。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外、净上］鹊声喧，灯花艳。", "［末上］老员外，老安人，姐夫中了状元，有书回来了。", "［外、净］果然今有信音传，整备华堂开玳筵。", "亲家且喜，我儿且喜。", "［老旦］小儿有书回来，正欲着媳妇请亲家看书。", "［旦］爹爹，书在此。", "［外］还送与婆婆开拆。", "［净］老员外，你看封皮上写那个开拆就是了。", "［外］此书烦附岳父大人亲手开拆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一封书","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["男八拜拜覆，妈妈萱亲想万福。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"剔银灯","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［老旦］亲家母不须怒起，容老身一言咨启。", "我孩儿颇颇识法理，肯贪荣忘恩失义？须知天不可欺，决不肯停妻娶妻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］书中句全无礼体，竟不审其中详细。", "葫芦提便说他不是，骂得我无言抵对。", "娘，休听谗说是非，他为人呵，决不肯将奴负亏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］妈妈且回嗔做喜，我孩儿不须垂泪。", "终不然为着家书至，将好意番成恶意。", "娘儿休辩是非，真和假三日后便知。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"普贤歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］书中语句有差讹，致使娘儿絮聒多。", "真伪怎定夺，是非争奈何？尺水翻成一丈波。", "［末］老员外回来了。", "［外］李成，我今日出去，体问王秀才消息，未知端的。", "我与你同到妹子家去走一遭。", "［末］小人同去，转弯抹角，此间便是。", "［叫介］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］奴奴方始念弥陀，忽听堂前谁叫我。", "偷睛把眼睃，却是我哥哥。", "阿三，快把柴来烧焰火。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"蛮牌令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］儿婿往京畿，前日附书回。", "道重婚丞相女，使母弃前妻。", "我儿道：非夫写的，你嫂嫂怒从心起。", "真和假俱未知，为此特来询问详细。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］哥哥听咨启，不必恁忧疑。", "我邻居孙官人，赴选近回归。", "他在京必知事体，问他音信，便知端的。", "［外］无由去他宅里，你可令人请来问个详细。", "［净上］日里莫说人，夜里莫说鬼。", "方才说小子，小子便来至。", "［末］未相邀，准来请你？［净］我在戏房中听得。", "［末］这科诨休要提，且与东人相见施礼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"川拨棹","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["我当初问亲，你们不听允，到今日被他负恩。", "［外］当初是我忒好意，谁想他忘了本？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"生姜芽","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］从他往京畿，两月余，一心指望登科第，回乡里，怎舍得轻辜负？相门重赘多娇女，不思量撇下荆钗妇。", "［合］弃旧怜新小人儒，亏心折尽平生福。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］畜生反面目，太心毒。", "忘恩负义难容恕，真堪恶！且放怀，休疑虑。", "他既贪图荣贵重婚娶，咱这里别选收花主。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［末］恩东免嗟吁，且听覆。", "言清行浊心贪污，违法度，恩和义，都不顾。", "半载夫妻曾厮聚，一时间却把婵娟误。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"字字双","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净上］试官没眼他及第，得志。", "恋着相府多荣贵，入赘。", "不思贫窘弃前妻，忘义。", "叵耐穷酸太无知，呕气。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉胞肚","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］读书豪俊，忍撇下瓯城故人。", "［丑上］负心贼有才实无信，才及第，弃旧怜新。", "［合］他贪奢恋侈，实丕丕使不仁，行短天教一世贫。", "［外］只因差一着，满盘都是空。", "［净］老儿，体问消息如何了？［外］一言难尽。", "［净］怎么说？［丑］好教嫂嫂知道。", "方才哥哥到我家中，说那王秀才的情节未尽，恰好孙官人近日在京回来，正好到我家中探望。", "我将此事问他，真个赘在万俟丞相府中了。", "言语并不差池。", "［净］实也不实？［丑］怎么不实！［净］我说道，老贼不听我说，你做得好事！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"浆水令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["你当初不听我们，到如今被他负恩。", "［外］世间谁是预知人，何须斗口与我相争？［丑］都忍耐，听解纷，家必自毁令人晒。", "［合］寻思起教人气忿。", "谁知道，谁知道恁般不仁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］那孙官人来说事因，他依然要愿续此亲。", "［净］那人果不弃寒门，教他选日下定成亲。", "［外］听伊言，心自忖，只恐我儿不从顺。", "［合前］［净］姑娘，既然孙官人果有此心，事不宜迟。", "［丑］便是。", "他今日送财礼，明日就成亲。", "［净］若如此甚好。", "［丑］我便去报与他知道，教哥哥便去对玉莲说，教他准备成亲。", "［外］我难对他说，你们自去与他说。", "［净］姑娘，待我自与玉莲说，你二人自回去。", "［介］情到不堪回首处，一齐分付与东风。", "［外、丑先下。", "净］且叫玉莲与他说，肯嫁孙家，房奁首饰，件件与他。", "若不肯时，头上剥到脚下，打他半死，不怕不从。", "玉莲！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金蕉叶","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］奈何奈何，信谗言母亲怪我，尺水翻成一丈波。", "天那！是何人暗地里调唆？［见介。", "净］孩儿，早知今日，悔不当初。", "早依我说，不见如此。", "你爹爹出去体问你丈夫消息，委实赘在万俟丞相府中了。", "你爹爹说道：他那里重婚，我这里改嫁。", "因此将你许了孙家了。", "你可梳妆准备。", "［旦］母亲差矣，王秀才是贤良儒士，未必辜恩负义。", "玉莲是贞洁妇人，焉敢再嫁？他果然重婚相府，奴家情愿在家守节。", "［净］什么守节？\"要知山下路，须问过来人。", "\"我当时若守得定时，为何又嫁你老子？\"守节\"二字，只好口说，一个时辰也熬不得的。", "［旦］母亲，此乃伤风化之言，不须提起。", "［净］我儿，今番断不由你了，依了娘说，我与你母子相亲。", "再若不从，朝一顿，暮一顿，打得你黄肿成病。", "教你汤不得吃，水不得进。", "嫁不嫁，今日还我个明白！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"孝顺歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["孙员外，家富足，他们有的是金共玉。", "你一心嫁寒儒，缘何弃撇汝？［旦］容奴禀覆，未必儿夫将奴辜负。", "那一个横死贼徒，忒兀自生嫉妒？［净］这纸书你重看取，明写着赘相府。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［净］他登高第身挂绿，侯门赘居谐凤侣。", "［旦］他为官理民庶，必然守法度，岂肯停妻再娶？［净］他负义辜恩，一筹不数。", "你因甚苦死执迷，不听娘言语？［旦］空自说要改嫁奴，宁可剪下发做尼姑！［净打旦介］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["贼泼贱敢抵触，告官司拷打你不孝妇！［旦］官司要厚风俗，终不然勒奴再嫁夫。", "［净］抵触得我好！［旦］非奴抵触。", "［净］恼得娘心头腾腾发怒，便打死你这丫头，罪不及重婚母。", "［旦］打死了奴，做个节孝妇。", "若要奴再招夫，直待石烂与海枯。", "［净］贱人，石头怎得烂？海水怎得枯？你敢说三个不嫁么？［旦］不嫁，不嫁，只是不嫁！［净］好回得停当！我要你嫁孙家，一片好心，你到反为不美。", "罢！罢！自从今日，脱下衣服首饰还我，与你三条门路：刀上死也得；水里死也得；绳上死也得，只凭你。", "肯嫁孙家，进我门来；不肯嫁，好好走出去。", "［旦］萱亲息怒且相容，［净］母命如何不听从？［旦］休想门阑多喜庆，［净］管教女婿近乘龙！［净下］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"五更转","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["心痛苦，难分诉。", "丈夫！一从往帝都，终朝望你谐夫妇。", "谁想今朝，拆散中途。", "我母亲信谗言，将奴误。", "娘呵！你一心贪恋，贪恋他豪富，把礼义纲常全然不颐。", "母亲，你今日听信假书，逼奴改嫁，此事决然不可！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["奴哽咽，难移步，不想堂前有老姑。", "婆婆，奴家今日撇了你去。", "千愁万怨，休怨儿媳妇，也不是你孩儿将奴辜负。", "婆婆，奴家若不改嫁，又不投江，恐母亲逼勒奴生嗔怒。", "罢！罢！贤愚寿夭天之数，拚死黄泉，丈夫！不把你清名辱污。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"满江红","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["拚此身来，早去跳江心，捞明月。", "［下］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"粉蝶儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］一片襟期，清似五湖秋水，喜声名上达丹墀。", "感皇恩，蒙圣宠，迁除福地。", "秉忠心肃清奸弊。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"山歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］做梢公，做梢公，起桩开船便拔篷。", "相公要往福州去，愿天起阵好顺风。", "［末］好好，说得利市。", "［外］梢子，明早开船。", "［丑］明早赛神好开船。", "［外］合用物件说将来。", "［丑道介。", "外］你且听我说，夜来寝睡之间，忽有神人嘱付言语，说有节妇投江，使吾捞救。", "又道此妇人与吾有义女之分，汝等驾几只小船，沿江巡哨，不拘男妇，捞救得时，重重赏你。", "［众］领钧旨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"铧锹儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］乘桴浮海非吾愿，算来人被利名牵。", "登舟过福建，须要防危虑险。", "［合］明早动船，开洋过浅，愿阵好风，吉去善转。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑］撑船道业虽微贱，水晶宫里活神仙。", "铺盖且柔软，蓑衣簟眠。", "［合前］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］遭折挫，受禁持，不由人不泪垂。", "无由洗恨，无由远耻。", "事临危，拚死在黄泉作怨鬼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"香罗带","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["一从别了夫，朝思暮苦。", "寄来书道赘居丞相府。", "母亲和姑妈逼勒奴也，改嫁孙郎妇。", "奴岂旨再招夫？萱堂苦苦责打奴，只得拚死在黄泉路，免得把清名来辱污。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"胡捣练","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["伤风化，乱纲常，萱亲逼嫁富家郎。", "若把身名辱污了，不如一命丧长江。", "［投江介。", "丑上救旦下］。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"五供养","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外上］餐风宿水，海舟中多少忧危。", "终宵魂梦里，似神迷。", "披衣强起，玉宇清高如洗。", "江风紧，海潮回，侧听邻岸晓鸡啼。", "人平不语，水平不流。", "叫梢水，什么人？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"山歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［丑上］夜行船里捞救一枝花，五更转说天净纱，脱布衫跳下江儿水，一支红绣鞋失落在浣溪沙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"菊花新","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［贴旦上］日上三竿犹未起，闻呼未审何因。", "［外］夜来有一妇人投江，梢手救得在小船上。", "夫人，你把些干衣服与他换了湿的来见我。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"糖多令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦上］无奈祸临头，今朝拚死休，如痴似醉任飘流。", "不想舟人捞救，我身出丑，脸惭羞。", "［见介。", "外］妇人，我且问你，你是何等人家儿女？因何短见投水？必有缘故。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉交枝","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］容奴伸诉。", "［外］你在那里住居？［旦］念妾在双门住居。", "［外］姓甚名谁？［旦］玉莲姓钱儒家女。", "［外］原来与我同姓。", "你曾嫁人么？［旦］年时获配鸳侣。", "［外］既有丈夫，丈夫姓甚名谁？在家、出外？［旦］王十朋是夫出应举。", "［外］且住。", "王十朋是你丈夫，他得中了头名状元，有书回来么？［旦］数日前有传尺素。", "［外］既有书来，为何投水？［旦］因此书骨肉间阻，因此书衔冤负屈。", "［外］书中必有缘故。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［旦］书中缘故，道休妻重婚在相府。", "［外］他是读书人，岂肯违法度？我晓得了，莫不是朋党嫉妒？［旦］萱亲信听谗诈书，逼奴改嫁孙郎妇。", "［外］怎么不从母命？［旦］论贞洁不更二夫，奴焉敢伤风败俗？［外］原来是王状元的贞烈夫人，快请起来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["听他言语，论贞洁他人怎比，思量我也难留你。", "左右叫舟子，不如送还伊父。", "［旦］若还送奴归故里，不如早丧黄泉路，到显得名传万古，尽教他的婚后娶。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["［外］不须忧虑，且带你同临任所。", "修书遣人饶州去，管教你夫妇重会。", "［旦］若还这般周济奴，犹如久旱逢甘雨，便是妾重生父母。", "望公相与奴做主。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黄莺儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)公相望垂怜，感夫人意非浅。", "又蒙结拜为姻眷，恩德万千，何日报全？愿公相早登八位三台显。", "(合)泪涟涟，双亲远别，重得遇椿萱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)不必泪涟涟，这相逢非偶然。", "同临任所为姻眷，聊附寸笺，饶州报传，管教你夫妇重相见。", "(合)免忧煎，夫妻有日，重得遇椿萱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(贴)天赐这姻缘，喜他们也姓钱，同临所作宛转。", "明日动船，开洋过浅，愿一阵好风，急去登福建。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)溺水自心酸，我婆婆苦万千，堂前继母心不善。", "儿夫去远，家尊老年，何日得见王佥判？(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"喜迁莺","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生上)从别家乡，期逼春闱，催赴科场。", "鹏程展翅，蟾宫折桂，幸喜名标金榜。", "旅邸忆念，孤鸾幽室，萱花高堂，鱼雁杳，信音稀，使人日夜思想。", "人在东瓯，身淹上苑，望中山色空迷眼。", "终朝旅思叹萧条，高堂亲鬓愁衰短。", "秦岭云横，蓝关雪漫，潮阳未到魂先断。", "春归花落久栖迟，愁深那觉时光换。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"雁鱼锦","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["长安四月花正飞，见残红万片皆愁泪。", "何苦被利禄成抛弃，如今把孤身旅泊天涯。", "意悬悬止不住思维，音书曾有回，只怕他望帝都欲赴愁迢递。", "望目断故园，知他知也未？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["嗟吁，凤别鸾离，怎如得俦莺偶燕时相聚？凄楚寒窗，寂寞旅况。", "闪杀当时，甘效于飞。", "孤灯夜雨，溜声不断，却把寸心滴碎。", "只为那钗荆裙布妻难弃，总有紫阁香闺人怎迷？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["猛思那日临行际，蒙岳丈惜伊玉树，兼爱我寒枝。", "念行囊空虚，欣然便周全助路资。", "召共居，感此义山恩海深难弃。", "细踌躇，甚日酬取？教我怎生忘渠？但愿得一家到此沾禄养，也显得半子从今展孝私。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["论科举，本图看春风杏枝，玉马骤香衢。", "岂知他陷我在瘴岭烟区？愁只愁身归凤池，恨只恨衅生鸳侣。", "人不见，气长吁，只为蝇头蜗角微名利，致使地北天南怨别离。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦上)儿媳妇哭啼啼，昨夜三更出绣帏。", "今早起来没寻处，使我无把臂。", "一重愁翻做两重悲，使我泪偷垂。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"山坡羊","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["撇得我不尴不尬，闪得我无聊无赖。", "亲家，你一霎时认真逼他去投江海，怎布摆，祸从天上来。", "你嫡亲父母尚且不遮盖，反将他谐老夫妻生打开。", "(合)哀哉！扑簌簌泪满腮。", "伤怀，生擦擦痛怎捱！(外、净上)隔墙须有耳，窗外岂无人。", "亲家为何啼哭？(老旦)亲家，不好了，我的媳妇投江死了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"山坡羊","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["儿，你不念我年华高迈，不念我形衰力败，不念我无人养老，不念我绝宗枝派。", "我想这桩事不是别人，都足你老祸胎，受了孙家婚聘财，逼得他衔冤负屈投江海。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"胜如花","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["辞亲去，别泪零，岂料登山蓦领。", "只因人递简传书，教娘离乡背井，未知道何日欢庆？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)我为绝宗派，结婚姻，指望一牢永定。", "谁知他又赘在侯门，今日翻成画饼，辜负了田园荒径。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)他家锅中米没半升，去恋着豪门，不思旧亲，到如今一旦身荣，撇却糟糠布荆，短行处教人怒冲。", "(合前。", "外)李成，你送王老安人到京，面会王状元，即便回来。", "(末)男女理会得。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["蒙员外分付情，对状元一诉明，幸喜得日暖风恬，相送起程，伤目兮桑榆暮景。", "(合前)生离死别痛无加，路上行人莫叹嗟。", "花正开时遭雨打，月当明处被云遮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忆虎序","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["当初娶汝，(净)正是大盘大盒娶的。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["我当初嫁你，也是明媒正娶，又不是暗地里偷情，强来随你。", "相随百步，尚有徘徊之意。", "免告官司，免告官司，和你团圆到底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风马儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦上)柳拂征衣露未央，可怜年迈往他乡。", "(末)谩自殷勤设奠，血泪洒长江。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"绵搭絮","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["寻踪觅迹到江边。", "李成舅，可曾带得香来？(末)小人不曾带得。", "(老旦)我那儿，只一块香没福受用。", "(苦)只得撮土为香，礼虽微，表姑情意怪。", "望灵魂暂且听言：指望松萝相倚，谁想你抱石含冤？这也不要埋怨你丈夫，都是你的亲娘把乘龙女婿嫌。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忆多娇","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)愁哽咽，情惨切，萱堂苦逼中道绝，暮忆朝思难诉说。", "(合)丧溺江心，丧溺江心，永远传扬孝烈。", "(老旦)我那媳妇的儿，我有半年粮食，也不见得到你家来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"绵搭絮","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["只为家贫无倚，在他闾阎。", "是你的儿夫去经年，杳没音信传。", "是你的继母呵，信谗言。", "镇日熬煎，熬煎得你抱屈含冤。", "我那儿，撇得我无倚无依。", "你带我的孝才是顺理。", "今日呵，反披麻哭少年！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忆多娇","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)心痛惜，情惨戚，将身赴江学抱石。", "可怜夫妇鸾凤拆，(合)即日登程，即日登程，渺渺音容远隔。", "(末)老安人，不须啼哭，趱行前去。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风入松","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)叹连年贫苦未逢时，谁想一旦分离。", "我孩儿自别求科举，怎知道妻房溺水？但说来，又恐惊骇我儿，决不可与他知。", "(末)安人不必恁忧虑，且听男女咨启。", "只说状元催逼起，先令我送安人来至。", "那其间方说就里，决不要使惊疑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"急三枪","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)痛易情难诉！痛易情难诉！常思忆，常忧虑，心戚戚，泪如珠。", "(末)且自登程去，且自登程去，休思忆，休忧虑，途路上，免嗟吁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风入松","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)如何教我免嗟吁？我这老景凭谁？年华老迈难移步，旦夕间有谁来温顾？恨只恨他们继母，逼他嫁死得最无辜。", "(末)果然死得最无辜，论贞洁真无。", "姻缘契合从今古，拆散了夫妻皆天数。", "漫腾腾洛阳近也，今且喜到京都。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"夜行船","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生上)一幅鸾笺飞报喜，垂白母，料已知之。", "日渐过期，人何不至？心下转添萦系。", "雁塔题名感圣恩，便鸿昨已寄佳音。", "思亲目断云山外，缥缈乡关多白云。", "下官前日修书，附承局带回，请取家小，同临任所。", "一去许久，不见到来，使我常怀忧念。", "正是：虽无千丈线，万里系人心。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前引","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦上)死别生离辞故里，经历尽万种孤凄。", "(末上)昨过村庄，今入城市，深感老天垂庇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"刮鼓令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["从别后到京，虑萱亲当暮景。", "幸喜得今朝重会，娘，又缘何愁闷萦？李成舅，莫不是我家荆，看承母亲不志诚？(末)小姐且是尽心侍奉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)心中自三省，转教人愁闷增。", "你媳妇多灾多病，况亲家两鬓星，家务事要支撑，教他怎生离乡背井？为你饶州之任恐留停。", "儿，你岳丈先令人送我到京城。", "(生)母亲言语不明，李成舅，你备细说与我知道。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)当初待起程，(生)正要问你起程，小姐怎么不来？(末)到临期成画饼。", "(生)母亲，李成舅说甚么画饼？(末背)若泌起投江一事，恐唬得恩官心战惊。", "(生)李成舅，说甚么惊字？(末)是有个经字，小姐呵！路途上少曾经，当不得许多高山峻岭，餐风宿水怕劳形。", "(生)老安人也来了，他到来不得？(末)便是小姐有些病体，老员外呵，因此上留住在家庭。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"江儿水","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)吓得我心惊怖，身战簌，虚飘飘一似风中絮。", "争知你先赴黄泉路，我孤身流落知何处？不念我年华衰暮，风烛不定，死也不着一所坟墓。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)一纸书亲附，我那妻，指望同临任所。", "是何人写套书中句？改调潮阳应知去，迎头先做河伯妇。", "指望百年完聚，半载夫妻，也算做春风一度。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)状元休忧虑，且把情怀暂舒。", "人妻聚散生前注，这离别虽说离别苦，想姻缘不入姻缘簿。", "听取一言伸覆：须信人生万事，莫逃天数。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"破阵子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外上)野外江山幽雅，城中景物繁华；(贴旦、旦、丑上)六街三市堪描画，万紫千红实可夸。", "(合)闽城景最佳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"榴花泣","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["守官如水，胸次莹无瑕。", "薄税敛。", "省刑罚，抚安民庶禁奸猾。", "幸喜词清讼简。", "无事早休衙。", "(旦)依条按法，看惩一戒百谁不怕？待三年任满期瓜，诏书来早晚迁加。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(贴)觑着他花容月貌胜仙娃，忍将身命掩黄沙？天教公相救伊家，好似拨云见日，枯树再开花。", "(外)贞洁可夸，恁捐生就此令人讶。", "恁萱亲怎不详察？全不道有伤风化。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)今日裹拜辞都爷，明日裹到海角天涯。", "一心要传递佳音，不惮路途波查。", "(外)关门。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["月再圆，花重发，那其间欢生喜洽，重整华筵泛紫霞。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"临江仙","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦上)客梦悠悠鸡唤醒，窗前尚有残灯。", "(生、末上)揽衣披枕自评论，今日飘零，何日安宁？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"朝元歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["腾腾晓行，露湿衣襟冷；徐徐晚行，月照遥天暝。", "只为功名，过离乡背井，渡水登山蓦岭，带月披星，车尘马足不暂停。", "晴岚障人形，西风吹鬓云。", "(合)潮阳海城，到得后那时欢庆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["几处幽林曲径，松杉列翠屏。", "回首乱云凝，禅关掩映，听远钟三四声。", "钦奉纶音，命游宦，宿邮亭。", "远离京城，盼阳关把往事空思省。", "水程共山程，长亭复短亭。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["危巅绝顶，飞流直下倾。", "叹微名奔竞，身似浮萍。", "鹧鸪啼，不忍听。", "野花开又馨，消遣羁旅情。", "到处草茵，题咏眼前无限景。", "牧笛陇头鸣，渔舟江上横。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)八九处人家寂静，柴门半掩扃，溪洞水泠泠。", "路远离别兴，自来不惯经。", "遥望酒旗新，买三杯，消渴吻。", "哀猿晚风轻，归鸦夕照明。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"探春令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外上)人生最苦是别离，论贞洁他人怎如？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一枝花","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(贴上)书缄情惨切，烟水多重叠。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"渔家傲","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)莫不是明月芦花没处寻？(外)明月芦花一片白，那里去寻？(旦)莫不是旧日王魁，嫌递万金？(外)他也不是王魁；你也不是桂英。", "(旦)莫不是忘了半载同衾枕？(外)也不是。", "(旦)莫不是不曾之任？(外)怎么不曾之任。", "(旦)爹爹，欲言不浯情难审，那里是全抛一片心？(外)咱语言说到舌尖声又噤，(旦)为何不说了。", "(外)若提起始末缘因，教你愁闷怎禁？儿，此生休想同衾枕，要相逢除非是东海捞针。", "如今兀自不思省，那苗良不投一下佳音回讣音。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧桐树","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["我为你受跋涉，我为你遭磨折。", "丈夫，我为你投江，我为你把残生舍。", "今日怎知先倾逝，这样凄凉．教我暗地里和谁说？禀爹爹，可容奴家带孝？(外)儿，在任穿些素缟吧。", "(旦)与我除下钗梳，尽把罗衣卸。", "持丧素服存贞沾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金莲子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(贴)休忧此生鸾镜缺，常言道：救人须救彻。", "(丑)听覆取休得要哽咽！姐姐，待等三年孝满，别赘豪杰。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)再醮徒然费唇舌，共姜誓盟甘自悦，守寡从教髻似雪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一枝花","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老巴上)细雨霏霏时候，柳眉烟锁常愁。", "(生、末上)昨夜东风蓦吹透，报道桃花逐水流。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"新水令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)一从科第凤鸾飞，被奸谋有书空寄。", "幸萱堂无祸危，痛兰房受岑寂。", "捱不过凌逼，身沈在浪涛里。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"步步娇","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)将往事今朝重提起，越恼得我肝肠碎。", "清明祭扫时，省却愁烦，且自酬礼，须心得圣贤书。", "看酒。", "(生)儿女何劳母亲递酒。", "(老旦)道\"吾不与祭如不祭\"。", "(生)看香来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"折桂令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["燕沈檀香喷金猊，昭告灵魂，听剖因依。", "自从俺宴罢瑶池，宫袍宠赐，相府勒赘。", "掩只为撇不下糟糠旧妻，苦推辞桃杏新室，致受磨折，改调俺在潮阳。", "妻，因此上耽误了恁的归期。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"江儿水","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)听说罢衷肠喜只为伊，却元来不从招赘生奸计，恼恨娘行生恶意，凌逼你奸没存济。", "母子虔诚遥祭来，望鉴微忱，早赐灵魂来至。", "看酒来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"侥侥令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)这话分明诉与伊，须记得圣贤书。", "懊恨娘行忒薄劣，抛闪得两分离在中路里，两分离在中路里。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"收江南","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)呀！早知道这般样拆散呵，谁待要赴春闱？便做到腰金衣紫待何如？说来又恐外人知，端的是不如布衣，端的是不如布衣！俺只索要低声啼哭自伤悲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"园林好","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)免愁烦回辞奠仪，拜冯夷多加护持。", "早早向波心中脱离，惟愿取免沈溺，惟愿取免沈溺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"沽美酒","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)纸钱飘，蝴蝶飞。", "纸钱飘，蝴蝶飞。", "血泪染，杜鹃啼。", "睹物伤情越惨凄。", "灵魂恁自知，灵魂恁自知。", "俺不是负心的，负心的随着灯灭。", "花谢有芳菲时节，月缺有团圆之夜。", "我呵！徒然间早起晚寐，想伊念伊。", "妻，要相逢除非是梦儿里再成姻契。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["昏昏默默归何处？哽哽咽咽思念你。", "直上嫦娥宫殿里。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一枝花","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦上)花落黄昏门半掩，明月满空阶砌。", "嗟命薄，叹时乖。", "华月在，人不见，好伤怀！昔恨时乖赴碧流，重蒙恩相得相留；深处闺门重闭户，花落花开春复秋。", "奴家自那日投江，不期遇着钱安抚捞救，留为义女，胜如亲生。", "只是无以报他。", "今宵明月之夜，不免烧炷清香，以求荫庇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"园林好","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["想那日身投大江，感安抚恩德怎忘？胜似嫡亲襁褓，如重遇父和娘。", "奴家烧此夜香呵，愿他增福寿，永安康！想我母亲亡过之后，又亏继母呵，。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"川拨棹","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["亲鞠养，我爹爹呵，择良人求配鸳行。", "谁知道命合遭殃，命合遭殃！递谗书逼奴险亡，蒙天眷，遇贤良。", "奴家烧此夜香呵，保佑他永安康，保佑他永安康。", "想我婆婆取奴家呵。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"好姐姐","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["指望终身奉养，谁知道中途肮脏。", "存亡未审，使奴愁断肠，心凄怆。", "奴家烧此夜香呵，愿得亲姑早会无灾障，骨肉团圆乐最长。", "想我丈夫有了奴家呵，。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"香柳娘","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["又重婚在洞房，重婚在洞房，将奴撇漾。", "奴家一身犹可，你不思父母恩德广。", "奴家指望你还有相见之日，谁想你到先亡了！痛儿夫夭亡，痛儿夫夭亡，不得耀门墙，抛弃萱花在堂上。", "奴家烧此夜香呵，愿他魂归故乡，遣他魂归故乡，免得此身渺茫，早赐瑶池宴赏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赏宫花","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净、丑上)耆宿社长，听荣除，特举觞。", "五年民沾惠，尽安康，卧辙攀鞍无计策，离歌别酒众难忘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生上)潮阳海邦，坐黄堂，名誉彰。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)衰老年，只愁烟瘴为吾患。", "幸家门吉庆，子母平安。", "今日里子擢高官，饮别酒应难留恋。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)心愧赧，备员窃禄常嗟叹。", "想刘宽难并，赵普难攀。", "偶然间盗息民安，非德化何劳称赞？(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"菊花新","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦上)云鬟衰鬓玉龙蟠，羞睹妆台镜里鸾。", "(生，末上)日月似梭窜，嗟嗟人事暗中偷换。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"泣颜回","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)说起便心酸，抱屈溺水含冤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)潜观慈母两眉攒，他欢无半点，愁有千般。", "朝夕萦绊，教人痛苦针钻。", "(净)河伯水官，那其间怎把人勾唤？致令得死别生离，如何会意悦心欢？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赚","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)擎捧雕盘，送出魂幡绢一端；更有些醮金三十堤，权收管。", "必须斋沐虔诚，休教功果不圆满。", "(净)天怎瞒，地怎瞒，小贫道谨告辞回观。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"扑灯蛾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦，生)荐亡虽已完，邀亲岂宜缓？若请岳翁至，同临观中游玩。", "也趁天时地暖，便起程休得盘桓。", "是则是夜长昼短，论朝行暮宿，休惮路漫漫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["生的报答心方稳，死的荐拔情颇宽，好事完成意始欢。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三台令","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外上)夜来花蕊银灯，晓起鹊声翠屏。", "(净上)何喜报门庭，顿教人侧耳频听。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末上)近别向粤邮亭，又入东瓯郡城。", "水秀山明，睹风物喜不自胜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一封书","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)婿百拜岳父前：自离膝下已数年。", "因奸相不见怜，改调潮阳路八千。", "今喜升为吉安守，遣仆相迎到任间。", "匆匆的奉寸笺，仗乞尊颜照不宣。", "(外)我听此书呵，。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"下山虎","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["见鞍思马，睹物伤情。", "触起关心事，怎不泪零？如今我婿得沐圣朝宠荣，我女一身成画饼。", "他取我到吉城，值此寒冬，怎出外境？(合)天寒地冷，未可离乡背井，且待春和款款行。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"亭前柳","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)老儿垂鬓已星星，弱体战兢兢。", "况兼寒凛凛。", "那更冷清清。", "此行怎去登山岭？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"亭前柳","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)老儿不去恐生嗔，欲去怕劳形。", "李成儿。", "你须先探试，临事怎支撑？(末)小人只索从台命。", "(合)且过新年，待春暖共登程。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"霜天晓角","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(小生，杂从上)黄堂佐政齐黎庶，肯将清似月扬辉，如渊彻底，愿效汉循良吏。", "勤簿书，门馆无私，日以刑名为事。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"啄木儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑)吾兄女，将及笄。", "(小生)曾许甚么人？(丑)许配王生尚未归。", "(小生)妇人谓嫁曰归。", "后来嫁去了么？(丑)那孙郎忽至奴家里。", "(小生)到你家来怎么？(丑)也要娶我侄女，他浼央老妾为媒氏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑)吾兄意，执不从。", "(小生)你侄女也肯么？(丑)侄女坚将节操持。", "我嫂嫂执不相容。", "吾兄就应变随机，将侄女送到王门去。", "(小生)王家既成了亲，孙家再不该议亲了。", "(丑)结亲后即赴科场里。", "谁想一举成名天下知。", "(小生)就是王十朋么？(丑)正是。", "(小生)到是我年兄家里的事。", "得中状元，有书回么？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑)因承局，附信归。", "(小生)有书回是喜事了。", "(丑)喜气翻成怨气吁。", "(小生)一纸家书抵万金，怎么是怨气？(丑)老爷，那里是万金佳音，元来是一纸休书。", "(小生)王状元是个读书君子，焉有此事来？(丑)他母亲疑是亲笔迹，女言道改书中句。", "只为字迹相同亦起疑。", "(小生)其时书来，说在那家为婿么？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑)赘在万俟府为女婿。", "(小生)你哥哥也曾上访问不曾？(丑)曾访问来。", "正遇孙郎下第归，他与吾兄面述其言，他说道：果赘侯门。", "(小生)孙汝权道你兄受他财礼。", "(丑)孙汝权，肉面对肉面，你家行甚财和礼？上有青天，我家那个来接取。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"归朝欢","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(小生)贤东坦，贤东坦，教音下期，令贱子，令贱子，翁前转致。", "须宜是，须宜是，行囊且携，恐他们悬望伊。", "(外)家庭虽小谁为理？田园颇广谁为治？欲去还留心两持。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三段子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(小生)翁今几儿？(外)念箕裘无人可倚。", "(小生)族分几枝？(外)念宗支无人可悲。", "(小生)你既然只身一己，如何不上倚贤婿？况是他殷勤想伊。", "(小生)叫左右，与我打点马船人夫，送钱相公到吉安府去。", "(外)如此多感多感！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小蓬莱/临江仙","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)绿暗汀洲三月景，锦江风静帆收。", "垂杨低映木兰舟，半篙春水滑，一段夕阳愁。", "(未)灞水桥东回首处，美人亲卷帘钩，落花几阵入红楼。", "行云归处，水流鸦噪枝头。", "老员外，今日日丽风和，花明景曙，加鞭趱行几步。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"八声甘州","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)春深离故家，叹衰年倦体，奔走天涯。", "一鞭行色，遥指剩水残霞。", "墙头嫩柳篱畔花，见古树枯藤栖暮鸦。", "嗟呀！遍长途触目桑麻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)呀呀，幽禽聚远沙，对彷佛禾黍，宛似蒹葭，江山如画，无限野草闲花。", "旗亭小桥景最佳，见竹锁溪边三两家。", "渔槎，弄新腔一笛堪夸。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"解三酲","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)为当初被人谎诈，把家书暗地套写，致吾儿一命丧在黄泉下，受多少苦波查。", "今日幸得佳婿来迎也，又愁着逆旅淹留人事赊。", "(合)空嗟呀！自叹命薄，难苦怨他。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(末)步徐徐水边林下，路迢迢野田禾稼，景萧萧疏林暮霭斜阳挂。", "闻鼓吹，闹鸣蛙，一经古道西风鞭瘦马。", "谩回首，盼想家山泪似麻。", "(合前)高山迢递日初斜，绿柳依稀路更赊。", "日断前村烟未暝，不知今夜宿谁家？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"懒画眉","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生上)紫箫声断彩云开，腻粉香朦玉镜台，灯前孤幌冷书斋。", "血衫难挽仙裾返，造化能移泰岳来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外，净，末上)馆甥位掌五侯台，千里裁封遣使来。", "令人更喜复悲哀，哀吾弱息今何在，喜他母子恩情得再谐。", "(末)老员外，这里是府门首。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"哭相思","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["一自别来容鬓改，恨公衙失迎冠盖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)自惭睚眦，望尊亲休劳挂怀。", "一时我也出无奈，莫把我做好人看待。", "人家晚母休学我忌猜，逼儿改嫁遭毒害。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)惭予一介，荷深恩扶出草莱。", "微名五载忘亲爱，岂知中路变祸灵？当初指望白首谐，谁知青岁遭残害？(合前。", "丑)老爷，酒席已完备了。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"普贤歌","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净上)侯门涉水最难求，愿适贤良王太守。", "自家非强口，管教成配偶，且请媒人吃喜酒。", "正是作伐全凭斧，引线必须针。", "我年兄有个令爱守寡，央我为媒，要招本郡太守王梅溪。", "他鼓盆已久，未有夫人，央我去说亲。", "邓兴，这里府前了，通报。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玩仙灯","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生上)兀坐书斋，闻道有客来相访。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"啄木儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)乞情恕，听拜禀：自与山妻合卺婚，才与他半载同衾，一旦凤拆鸾分。", "他抱冤守节先亡殒，我辜恩再娶心何忍？须知行短天教一世贫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)他八两，你半斤，彼此为官居上品。", "论阀阅，户对门当，真个好段姻亲。", "你意骄性执不从顺，故千推万阻令人恨，有眼何曾识好人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"三段子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)事当隐忍，未可一时先怒嗔。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"归朝欢","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)你没思忖，不投分，那里是儒为席上珍？(生)我做官守法言忠信，名亏行损遭谈沦，纵独处鳏居，决不可再婚！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"杜韦娘","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦上)朔风寒凛冽，云布野，卷飞雪，看万木千林都冻折。", "小窗前，梅花再缀，冰稍数点幽洁。", "淡月黄昏，暗地香清绝，早先把阳和漏泄，又葭管灰飞地穴。", "痛忆我亡夫，感念嗟吁，转头又是五年余。", "安抚收留恩不浅，补报全无。", "今日乃是冬至令节，等待爹妈出来，拜贺则个。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"麻婆子","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑上)做奴做奴空惆怅，何时得嫁马上郎？做奴做奴空劳攘，只落得一个晓夜忙。", "遇冬节，巧梳妆，身穿一套好衣裳。", "市人见了都夸奖，道我是个风流好养娘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"海棠春","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外，贴上)时序两推迁，莫惜开芳宴。", "孩儿，金乌似箭，玉兔如梭，不觉来此又是五年。", "前日邓尚书来相探，闲话间说起王太守未有夫人，因此将你吉帖付与他去，了汝终身。", "(旦)爹爹，但愿终身守节，再醮难言。", "(外)你丈夫未死，不肯嫁礼之所当。", "汝夫已死多年，不嫁将何倚靠？(旦)望爹爹为我螟蛉一子，以为终身后嗣。", "(外)如此终无结果。", "(旦)妾闻仁者不以盛衰改节，义者不以存亡易心。", "截耳残形，永杜重婚之议；劈面流血，难从再醮之言；自古及今，芳名不灭。", "使妾有失志节，听此宁无愧乎？誓以柏舟，甘效共姜，死而后已。", "若窥隙钻窬，潜奔司马，则非奴所愿也。", "若不容奴于相府，则贱妾仍丧于江中。", "(外)夫人，我寻思这般志节也难得。", "孩儿，你要守节，改旦这房一子，与你为后嗣。", "(旦)如此甚感爹爹，爹妈请坐，待奴家拜节。", "看酒来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"集贤宾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["一阳气转春透彻，履长欢庆冬节。", "验岁瞻云人意切，听残漏晓临台榭。", "今年是别，黄云谶争书吉贴。", "(合)芳宴设，沉醉后，管弦声咽。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)日晷渐长人尽悦，绣纹弱线添些。", "待腊将舒堤柳弦，冻柔条未堪攀折。", "百官摆列，贺新岁齐朝金阙。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"莺啼序","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(贴)光阴迅速如电掣，断送了多少豪杰。", "遇良辰自宜调燮，且把闲闷抛撇。", "进履袜欢看妇仪，炷宝鼎对天答谢。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑)道消遣长空叹嗟，画堂中且安享骄奢。", "看纷纷绿拥红遮，绮罗香散沉麝。", "辟寒犀开元此日，曾远贡喧传朝野。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(众)小寒天气，莫把酒樽歇。", "醉看歌姬容艳冶，春容微晕酒悬颊。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["玉山低颓日已斜，酒散歌阑呼侍妾。", "把锦纹烘热，从教醉梦赊。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玩仙灯","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生上)节届元宵，灯月灿然高，到观门拈香荐悼。", "(净)道士接爷爷。", "(生)功果都完了么？(净)经文都完了，专等老爷拈香。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一封书","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)特朝拜上清，仗此名香表志诚。", "亡妻滞水滨，愿神魂得上升。", "(净)横死孤魂都召请，请到坛前听往生。", "(合)诵仙经，荐亡灵，仗此功勋超圣境。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦，丑上)前日已预名，届此良辰来殿庭。", "拈香炷宝鼎，望慈悲作证盟。", "(净)惟愿亡灵来受领，献取香花酒果饼。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)蓦然见俊英，与一丫鬟前后行。", "潜地想面形，转教人疑虑生。", "(末)他两次三回常观顾，觑了恩官也动情。", "(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)回廊下撞迎，顿教人心暗惊。", "那烧香上卿，好似亡夫王十朋。", "(丑)休得轻言当三省，烧罢名香转看灯。", "(合前)(下生)见鞍思马，睹物思人。", "适才那妇人好像我夫人。", "叫道士过来，适才妇人那家宅眷？(净)钱都爷小姐。", "(生)原来天下有这般相似的。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"步步娇","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦上)观里拈香蓦相会，使我心萦系。", "(丑)小姐，如今枉致疑，既认得真时，何不问取详细。", "(旦)梅香，这就里你怎知，恐错认了风流婿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红衲袄","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["意沉吟，情惨伤；步趑趄，心悒怏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["小姐，你曾和他共鸳衾，同象床。", "直恁的你认不得他形共庞。", "(旦)面貌身材果然厮像，行动举止没两样。", "(外暗听。", "丑)既认得真时合主张。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锦缠道","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["治家邦，正人伦，有三纲反常。", "你潜说出短和长，怎不提防，他人须有耳隔墙？讲甚么晋陶潜认作阮郎？却不道，誓柏舟甘效共姜？(打丑介)光打后商量，问出你私情勾当。", "押发离府堂。", "文牒上明开供状，抵多少衣锦去还乡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(丑)小梅香，待回言，恐触突了使长。", "不回言，这无情棒打难当，怎知道祸从天降。", "他本是守荆钗寒门孟光。", "(外)潜奔之女，什么孟光！(丑)休错认做出墙花淮甸双双。", "我说起这行藏。", "(外)说什么来？(丑)他说道：烧香的王太守，好似亡夫模样。", "寻思痛感伤，因此上和妾在此闲讲，又个曾想像赴高唐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)守孤孀，荐亡灵，亲临道场。", "烧香罢。", "传回廊，偶相逢不由人不睹物悲伤。", "(外)你这贱人要做莺莺？(旦)那里是西厢下莺莺伎俩？(外)你这贱人就是红娘！(旦)怎么的就打梅香，生纽做红娘？当初去投江，(外)亏你不识羞，还说投江！(旦)把原聘物牢拴在髻上，荆钗义怎忘？妾岂肯随波逐浪，却不道辱没宗祖把恶名扬？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)假乖张，贱奴胎，把花言抵搪，全不顾外人扬，恼得我气满胸膛。", "你本是王月英留鞋在殿堂，怎不学浣纱女抱石投江？(打介)你这贱人还不说！(丑)雪上更加霜，自不合与他人闲讲。", "谁知惹祸殃，闲话里没些度量，怎知道一霎时祸起在萧墙？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"紫苏丸","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外上)若认此荆钗，其中可宛转。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)听诉因依，昔日卑人贫困时，忽有良媒作伐，未结婚姻，愧乏财礼，荆钗遂把聘钱氏。", "(外)成亲几年？(生)结亲后即赴春闱里，幸喜及第。", "(外)除授那里？(生)除授饶州佥判，叨蒙恩庇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)再听因依，说起教人珠泪垂。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)曾寄书回，深恨孙郎故改易。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["曾荐亡妻，原籍视临在宫观里。", "我在回廊之下，见一佳人，与妻无二。", "教人展转痛伤悲，今朝又见荆钗记。", "睹物伤悲，人亡物在，空弹珠泪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)休皱双眉，听俺从头说仔细。", "我在东瓯发足，渡足登舟，一梦跷蹊。", "(生)梦见甚的？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(净)此事真奇，节妇义夫人怎比？年兄，疾忙开宴，请出夫人，就此相会。", "天教今日重完聚，金杯捧劝须当醉。", "(生)深感提携，从今万载传名誉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"哭相思","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦上)妮子传呼意甚美，尚未审凶和喜。", "(外)儿，王守公正是你丈夫。", "(生、旦)每痛忆伊作幽冥鬼，不料重逢你！(外)快去府里请太夫人相见。", "(老旦上)公相相招见儿妇，焉敢踌躇。", "(旦)婆婆，自从那日别离，今日又得相会。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红衫儿","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)自那日投江随潮去，痛苦伤悲。", "忽闻人报道身亡，转教人痛悲。", "若不遇公相相留，怎能勾夫妻重会？效衔环结草，当报恩义。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"大环着","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(外)那一日江道，那一日江道，得梦蹊跷。", "灵神对吾曾说道，见佳人果然声韵高。", "投水江心早，梢公救捞，问真情取覆言词了。", "留为义女，带同临任所福州道。", "(合)怎知今日，夫妻母子，子母团圆，再得重相好。", "腰金衣紫还乡，大家齐欢笑，百世永谐老。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(老旦)想当初穷暴，想当初穷暴，岂有今朝。", "苍天果然不负了，幸孩儿喜得名誉高。", "门闾添荣耀，阖家旌表，感皇恩母子得宠招。", "加官赐爵受天禄，满门福怎消？(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)叹椿庭丧早，叹椿庭丧早，母氏劬劳。", "想当年运乖时未遭，对青灯简编莫惮劳。", "萱亲况年老，深蒙泰山，送荆钗岂嫌寒舍小。", "春闱应举，助白金与我恩怎消？(合前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"越恁好","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(生)自上长安道，自上长安道，步蟾宫，挂紫袍。", "为不就万俟丞相宠招，不从赘配多娇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"前腔","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["(旦)诈书传报，诈书传报，苦逼奴嫁富豪。", "遂投江，幸得钱安抚急救捞，免随潮。", "因此上五年两两伤怀抱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾","p":"","d":"元代","a":"柯丹邱《荆钗记》","c":["移宫换羽虽非巧，仿古依今教尔曹，奉劝诸君行孝道。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・普天乐酒","p":"","d":"元代","a":"滕斌","c":["谪仙强，刘伶缪。", "笑豪来鲸吸，有甚风流？聊复尔，无何有。", "酝酿潮红春风透，兴来时付与觥筹。", "频频到口，轻轻咂啖，少过咽喉。", "色百年身，千年债。", "叹愚夫痴绝，云雨阳台。", "人易老，心犹在。", "独倚阑干春风外，算人间少甚花开。", "春光过也，风亻孱雨亻愁，一叶秋来。", "财一瓢贫，千钟富，是天生分定，何必枉图？锦步障，黄金坞。", "狗苟蝇营贪不足，为妻儿口体区区。", "君家饱暖，他人冻馁，于汝安乎？气少年时，风云志。", "记篇诗杯酒，颠倒群儿。", "吾善养，今方是。", "唾面来时休教拭，看英雄自古如痴。", "前程万里，饶人一步，却是便宜。", "柳丝柔，莎茵细。", "数枝红杏，闹出墙围。", "院宇深，秋千系。", "好雨初晴东郊媚，看儿孙月下扶犁，黄尘意外，青山眼里，归去来兮。", "昼偏长，人贪睡。", "新蝉高树，乳燕低飞。", "荷荡中，湖光内。", "款棹兰舟闲游戏，任无情日月东西。", "钓头锦鲤，杯中美酝，归去来兮。", "翠荷残，苍梧坠。", "千山应瘦，万木皆稀。", "蜗角名，蝇头利。", "输与渊明陶陶醉，尽黄菊围绕东篱。", "良田数顷，黄牛二只，归去来兮。", "朔风寒，彤去密。", "雪花飞处，落尽江梅。", "快意杯，蒙头被。", "一枕无何安然睡，叹邙山坏墓折碑。", "狐狼满眼，英雄袖手，归去来兮。", "日迟迟，江山丽。", "秋千影里，手握肩依。", "闹管弦，纷罗绮。", "我爱青山共流水，游一和困在苔矶。", "落花啼鸟，一般春意，归去来兮。", "晚天凉，薰风细。", "浮云黯淡，远水茫微。", "江水清，遥山碧。", "喜驾孤舟潇湘内，伴纶竿箬笠蓑衣。", "垂杨树底，芦花影里，归去来兮。", "淡烟迷，遥山翠。", "秋天雁唳，夜月猿啼。", "小径幽，茅檐僻。", "秋色南山独相对，傲西风菊绽东篱。", "疏林鸟栖，残霞散绮，归去来兮。", "暮霞收，彤云密。", "朔风凛冽，瑞雪纷飞。", "酒力微，茶烟湿。", "暖炕明窗绵绸被，尽前村开彻江梅。", "日高未起，黑甜睡足，归去来兮。", "叹光阴，如流水。", "区区终日，枉用心机。", "辞是非，绝名利。", "笔砚诗书为活计，乐齑盐稚子山妻。", "茅舍数间，田园二顷，归去来兮。", "仗权豪，施威势。", "倚强压弱，乱作胡为。", "我劝你，休窒闭。", "此等痴愚儿曹辈，利名场多少便宜。", "寻饥得饥，凭实得实，归去来兮。", "乐生涯，抛活计。", "麻绦草履，淡饭黄齑。", "遇酒歌，逢场戏。", "落落魄魄无萦系，那里管闲是闲非。", "游山玩水，埋名隐迹，归去来兮。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"正宫・端正好集杂剧名咏情","p":"","d":"元代","a":"孙季昌","c":["鸳鸯被半床闲，胡蝶梦孤帏静，常则是哭香囊两泪盈盈。", "若是这姻缘簿上合该定，有一日双驾车把香肩并。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"滚绣球・常记的曲江池丽日晴，正对着春风细柳营，初相逢在丽春园遣兴，","p":"","d":"元代","a":"孙季昌","c":["便和他谒浆的崔护留情。", "曾和他在万花堂讲志诚，锦香亭设誓盟，谁承望下场头半星儿不应，央及杀调风月燕燕莺莺。", "则被这西厢待月张君瑞，送了这花月东墙董秀英，盼杀君卿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"倘秀才・玩江楼山围着画屏，见一只采莲舟斜弯在蓼汀，待和他竹叶传情","p":"","d":"元代","a":"孙季昌","c":["诉咱闷萦。", "并头莲分做两下，鸳鸯会不完成，知他是怎生？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"滚绣球・付能的潇湘夜雨睛，早闪出乌林皓月明，正孤雁汉宫秋静，知他","p":"","d":"元代","a":"孙季昌","c":["是甚情怀月夜闻筝？那时节理残妆对玉镜台，推烧香到拜月亭，则被这亻刍梅香紧将咱随定，不能够写相思红叶题情。", "指望似多情双渐怜苏小，到做了薄幸王魁负桂英，撇得我冷冷清清。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"倘秀才・金凤钗斜簪在鬓影，抱妆盒寒侵倦整，想踏雪寻梅路怎行？弄黄","p":"","d":"元代","a":"孙季昌","c":["昏梅梢月，香正满酷寒亭，伤情对景。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"叨叨令・当日被破连环说啜赚得再成交颈，谁承望错立身的子弟无音信。","p":"","d":"元代","a":"孙季昌","c":["闪得我似离魂倩女相思病，将一个魔合罗脸儿消磨尽。", "径不着也么哥，如今这谎郎君一个个传槽病。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"脱布衫・我便似蓝桥驿实志真诚，他便似竹林寺有影无形。受寂寞似越娘","p":"","d":"元代","a":"孙季昌","c":["背灯，恨别离如乐昌分镜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"小梁州・他便似柳毅传书住洞庭，千里独行，吹箫伴侣冷清清。我待学孟","p":"","d":"元代","a":"孙季昌","c":["姜女般真诚性，我则怕啼哭倒了长城。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・京娘怨杀成孤另，怨你个画眉的张敞杂情，揣着窃玉心、偷香性。我","p":"","d":"元代","a":"孙季昌","c":["则学举案齐眉，贤孝牌上立个清名。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・金钗剪烛人初静，彩扇题诗句未成。后庭花歌残玉树声，琵琶怨凄凉","p":"","d":"元代","a":"孙季昌","c":["不忍听。", "比题桥的相如忒寡情，戏妻秋胡不老成。", "想则想关山远路程，恨则恨衣锦还乡不见影。", "则不如一纸刘公书谨缄定，寄与你个三负心的敲才自思省。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"仙吕・点绛唇集赤壁赋","p":"","d":"元代","a":"孙季昌","c":["万里长江，半空烟浪，惊涛响。", "东去茫茫，远水天一样。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"混江龙・壬戌秋七月既望，泛舟属客乐何方？过黄泥之坂，游赤壁之傍。","p":"","d":"元代","a":"孙季昌","c":["银汉无声秋气爽，水波不动晚风凉。", "诵明月之句，歌窈窕之章。", "少焉间月出东山上，紫微贯斗，白露横江。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"油葫芦・四顾山光接水光，天一方，山川相缪郁苍苍，浪淘尽风流千古人","p":"","d":"元代","a":"孙季昌","c":["凋丧。", "天连接崔嵬，一带山雄壮。", "西望见夏口，东望见武昌。", "我则见沿江杀气三千丈，此非是曹孟德困周郎？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天下乐・隐隐云间见汉阳，荆襄，几战场，下江陵顺流金鼓响。旌旗一片","p":"","d":"元代","a":"孙季昌","c":["遮，舳舻千里长，则落的渔樵每做话讲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"那吒令・见横槊赋诗是皇家栋梁，见临江酾酒是将军虎狼，见修文偃武是","p":"","d":"元代","a":"孙季昌","c":["朝廷纪纲。", "如今安在哉，做一世英雄将，空留下水国鱼邦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"鹊踏枝・我则见水茫茫，树苍苍，大火西流，乌鹊南翔。浩浩乎不知所往，","p":"","d":"元代","a":"孙季昌","c":["飘飘乎似觉飞扬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"寄生草・渺苍海之一粟，哀吾生之几场。举匏樽痛饮偏惆怅，挟飞仙羽化","p":"","d":"元代","a":"孙季昌","c":["偏舒畅，溯流光长叹偏悒怏。", "当年不为小乔羞，只今惟有长江浪。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・谩把洞箫吹，再把词章唱。苏子正襟坐掀髯鼓掌，洗盏重新更举觞。","p":"","d":"元代","a":"孙季昌","c":["眼纵横醉倚篷窗，怕疏狂错乱了宫商。", "肴核盘空夜未央，酒入在醉乡。", "枕藉乎舟上，不觉的朗然红日出东方。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・粉蝶儿怨别","p":"","d":"元代","a":"孙季昌","c":["锦帐罗帏，空留下这场憔悴，想人生最苦别离。", "恨匆匆，愁冗冗，忘餐失寐。", "困腾腾眼倦心迷，却原来害相思恁般滋味。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉春风・枕剩梦难成，衾余愁易得。衾余枕剩捱长更，我到如今悔，悔。","p":"","d":"元代","a":"孙季昌","c":["银烛灯残，金杯酒冷，宝炉香细。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红绣鞋・黄甘甘胭憔粉悴，病恹恹瘦损香肌，急煎煎和泪数归期。急穰穰","p":"","d":"元代","a":"孙季昌","c":["情没乱，碜磕磕的两分离，空着我闷恹恹盼望你。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"普天乐・意踌蹰，心萦系。哀哀怨怨，惨惨凄凄。抛闪下年少人，辜负了","p":"","d":"元代","a":"孙季昌","c":["鸾凰配。", "早是离人伤心碎，更和那杜宇悲啼。", "冷清清在销金帐里，珊瑚枕剩，好梦惊回。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"上小楼・美恩情眉南面北，好姻缘鸳鸯拆对。想着俺携手星前，并肩月下，","p":"","d":"元代","a":"孙季昌","c":["共枕同席。", "见如今宝鉴分，钗断股，簪折瓶坠，正值着感情怀物伤人意。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺篇・画梁间燕语喧，花柳中莺乱啼。好着我泪眼羞观，愁心倦听，景物","p":"","d":"元代","a":"孙季昌","c":["狼藉。", "正遇着风雨催，柳絮飞，残红满地，我则索掩重门绿窗春睡。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"耍孩儿・山长永远人千里，满目残红春又归。闲愁闲闷几时休，怕黄昏帘","p":"","d":"元代","a":"孙季昌","c":["幕低垂。", "我则怕更阑夜静离人苦，倦听谯楼画角催。", "捱不彻凄凉日，打熬出闷忧中日月，憔悴了花朵儿身肌。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"煞尾・别离了数载余，淹留的我三不归。若能够好姻缘重把佳期会，则除","p":"","d":"元代","a":"孙季昌","c":["是一枕南柯梦儿里。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・中吕/赏花时","p":"","d":"元代","a":"郑光祖","c":["母亲道豚犬东行百步忧，（卜儿云）孩儿，你趁着这鹏鹗西风万里秋。", "（正末唱）趁着这鹏鹗西风万里秋。", "非拙计岂狂游，凭着我高才和这大手。", "（卜儿云）孩儿疾去早来。", "（正末云）母亲，恁孩儿常存今日志，必有称心时。", "（唱）稳情取谈笑觅封侯。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・仙吕/黠绛唇","p":"","d":"元代","a":"郑光祖","c":["早是我家业凋残，少年可惯，我被人轻慢，似翻复波澜，贫贱非吾患。", "（小二云）王先生，你即是读书人，何不寻几个相识朋辈？（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・混江龙","p":"","d":"元代","a":"郑光祖","c":["我与人秋毫无犯。", "（小二云）则为你气高志大，见是如此。", "（正末云）则为气昂昂误得我这鬓斑斑。", "久居在箪瓢陋巷，风雪柴关。", "穷不穷甑有蛛丝尘网乱。", "（小二云）看了你这嘴脸，火也没一些拢的。", "（正末唱）窘不窘炉无烟火酒瓶干。", "划的在天涯流落，海角飘零，中年已过，百事无成，捱不出伤官破祖穷愁限。", "多只在闾阎之下，眉睫之间。", "（小二云）王先生，我看你身上有些儿单寒么？（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・油葫芦","p":"","d":"元代","a":"郑光祖","c":["小二哥人休笑书生胆气寒，赤紧的看承的我如等闲。", "则俺这敝裘裳怯晓霜残，端的可便有人把我做儿曹看。", "堪恨那无端一郡苍生眼。", "（小二云）看你这模样，也没些志气胆量。", "（正末唱）我量宽如东大海，志高如西华山。", "则为我五行差没乱的难迭辨，几能勾青琐点朝班。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・天下乐","p":"","d":"元代","a":"郑光祖","c":["因此上时复挑灯把代理人剑弹，有那等酸也波寒，可着我怎挂眼，只待要论黄数黑在笔砚间。", "（小二云）你既是读书之人，何不训几个蒙童，讨些钱钞还我，可不好？（正末唱）你着我教蒙童数子顽。", "（带云）据王粲的心呵，（唱）我则待辅皇朝万姓安。", "哎！你可便枉将人做一例看。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・那吒令","p":"","d":"元代","a":"郑光祖","c":["我怎肯空隐在严子陵钓滩，我怎肯甘老在班定远玉关。", "（带云）大丈夫仗鸿鹄之志，据英杰之才。", "（唱）我则待大走上韩元帅将坛。", "我虽贫呵乐有余，便贱呵非无惮，可难道脱不的二字饥寒？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・鹊踏枝","p":"","d":"元代","a":"郑光祖","c":["赤紧的世途难，主人悭，那里也握发周公，下榻陈蕃。", "这世里冻饿死困居的范丹，哎，天呵，兀的不忧悉杀高卧袁安。", "（云）叔父，不止小生受窘，先辈古人也多有受窘的。", "（蔡相云）王粲，与你比喻：你那积雪成阜，怎熬俺有力之松；磨墨成池，怎染俺无瑕之玉。", "明珠遭杂，岂列雕盘，素丝蒙垢，难成美锦。", "小见人万种机谋，总落的俺高人一笑。", "先辈那几个古人受窘，你试说一遍听咱。", "（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・六幺序","p":"","d":"元代","a":"郑光祖","c":["我投奔你为东道。", "（蔡相云）我可也做不的东道。", "（正末唱）倚仗你似泰山。", "（蔡相云）我可也做不的那泰山。", "（正末唱）的似惊弓鸟叶冷枝寒。", "好教我镜里羞看，剑匣空弹！前程事非易非难，想蛰龙奋起非为晚。", "赤紧的待春雷震动天关，有一日梦飞熊得志扶炎汉。", "才结果桑枢瓮牖，平步上玉砌雕栏。", "（蔡相云）（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・赚煞","p":"","d":"元代","a":"郑光祖","c":["我持翰墨谒荆王，展羽翼腾霄汉。", "梦先到襄阳岘山，楚天阔争如蜀道难。", "我得了这白金骏马雕鞍，则愿的在途间人马平安，稳情取峥嵘见您的眼。", "（曹学士云）贤士，常言道人恶礼不恶，还辞一老丞相。", "（正末云）看学士分上，我辞他一辞，叔父，承管待了也。", "（蔡相云）王粲，你去了罢，又回来做甚么？（正末云）我吃你甚么来？（唱）我略别你个放鱼的子产。", "（蔡相云）放鱼的子产嗓磕老夫不识贤哩！（正末唱）你休笑我屠龙的王粲。", "（云）虽是今日之贫，安知无他日之贵。", "有一日官高极品，位列三公，食前方丈，禄享千钟，武夫前拥，锦衣后随，学士恕罪了。", "（曹学士云）贤士，稳登前路。", "（正末唱）你看我锦衣含笑入长安。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・正宫/端正好","p":"","d":"元代","a":"郑光祖","c":["则有分鞭羸马，催行色，拂西风满面尘埃，想昨朝风送烟波侧，今日个落日在青山外。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・滚绣球","p":"","d":"元代","a":"郑光祖","c":["我比那买官的省些玉帛，求仕的费些草鞋。", "赤紧的好难寻紫袍金带。", "（云）今日见荆王呵，（唱）便是我苦尽甘来。", "他听得我扣宅，他将那书折开，多应是把我来降阶接待。", "岂不闻有朋自远方来？（带云）那荆王或问我兵法呵，（唱）你看坐间略展安邦策，便索高筑黄金拜将台，不索疑猜。", "（云）说话中间，可早来到门首也。", "左右报复去，道有高平王粲，持曹子建学士书呈，特来拜见。", "（卒子云）将书来，我与你报去。", "喏！报的大王得知，今有高平王粲，持曹子建学士书呈，特来拜见。", "（荆王云）将书来我看：\"翰林学士曹植拜书。", "\"我折开这书看：\"蔡邕拜上麾下。", "\"元来封皮上是曹子建之名，书内是蔡邕丞相举荐，书中意我尽知了也。", "久闻此人，是一代文章之士。", "道中门相请！（请见科）（荆子王）久闻贤士大名，今至俺荆襄之地，如甘霖润其旱苗，似清风解其酷暑，何幸何幸！（正末云）小生闻知大王豁达大度，纳谏如流，因此不远千里，持子建学士书，特来拜见。", "（荆子王）动问贤士，何不在帝都阙下，求取功名，如何远涉江湖，徒步至此？俺这荆襄土薄民稀，兵微将寡，只怕展不得仲宣之志，如之奈何？（正末云）大王，（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・倘秀才","p":"","d":"元代","a":"郑光祖","c":["如今那有钱人没名的平登省台，那无钱人有名的终淹草莱。", "（荆子王）据贤士如何？（正末唱）如今他可也不论文章只论财。", "（荆子王）贤士可曾投托人么？（正末唱）赤紧的难录东道主。", "（荆子王）向在何处？（正末唱）久困在书斋。", "非王粲巧言令色。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・滚绣球","p":"","d":"元代","a":"郑光祖","c":["非是我王仲宣胸次高，赤紧的晏平仲他那度量窄。", "（云）小生远远而来，他道：\"老兄几时到？\"我回言：\"恰才到此。", "\"你道：\"休往别处去，来俺家里住。", "\"（唱）我和他初相见厮亲厮爱。", "（云）他问道：\"老兄此一来，有何贵干？\"我回言道：\"特来投托求些盘缦。", "\"他听得道罢，（唱）早唬得他不抬头口倦难开（云）那人推托不过，则索应付。", "（唱）至少呵等到有十朝半月，多呵赍发银一两钱二百，那一场赍发的心大惊小怪。", "（云）大王，久以后不得第便罢，若得第时，一时间顾盼不到，他便道：\"黑头虫儿不中救，俺也曾赍发你来。", "\"（唱）怎禁他对人前朗朗的花白，如今那友人门下难投托，因此上安乐窝中且避乖，倒大来悠哉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・呆骨朵","p":"","d":"元代","a":"郑光祖","c":["若论掌襄帅府威风大，我是白衣人怎敢望日转千阶。", "我又不曾驱六甲风雷，又不曾辨三光气色，又不曾写就《论天表》又不曾草下甚么《平蛮策》（荆王云）贤士乃簪缨世胄，堪为元戎帅首也。", "（正末唱）我虽是个簪缨门下人，怎做的斗牛星畔客。", "（荆子王）贤士知天文，晓地理，观气色，辨风云，何所不通，何所不晓！有大才受大任，固其宣也。", "（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・倘秀才","p":"","d":"元代","a":"郑光祖","c":["止不过曲志在蓬窗下守着霜毫的这砚台，我又不曾进履在圯桥下收的甚兵书战策。", "如今那有志的屠龙去南海，古今无贤士，前后少英才，非王粲疏狂性格。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・滚绣球","p":"","d":"元代","a":"郑光祖","c":["我不让姜子牙兴周的显战功。", "（荆王云）你谋策如何？（正末云）论谋策呵，（唱）我不让张子房佐汉的有计画。", "(荆王云)你扎寨如何？（正末云）论扎寨呵，（唱）我不让周亚夫屯细柳安营扎寨。", "(荆王云)你点将如何？(正末云)论点将呵，(唱)我不让马服君仗霜锋点将登台。", "（荆王云）你胆气如何？（正末云）论胆气呵，（唱）我不让蔺相如渑池会那气概。", "（荆王云）你才干如何？（正末云）论才干呵，（唱）我不让管夷吾霸诸侯那手策。", "（荆王云）你行兵如何？（正末云）论行兵呵，（唱）我不让霍嫖姚领雄兵横行边塞。", "（荆王云）你操练如何？（正末云）论操练呵，（唱）我不让孙武子用兵法演习裙钗。", "(荆王云)你智量如何？（正末云）论智量呵，(唱）我不让齐孙膑捉宠涓则去马陵道上施埋伏。", "（荆王云）你决战如何？（正末云）论决战呵，（唱）我不让韩元帅困霸王在九里山前大会垓，胸卷江淮。", "（做睡科）（荆王云）好兵法！将酒来，庆兵法！贤士满饮此杯。", "呀！才和俺攀话，又早睡着了也。", "便好道德胜才为君子，才胜德为小人。", "俺末曾重用，先失左右之门风，正是那才有余而德不足。", "等此人睡觉来问我，只说我更衣去了。", "（诗云）德胜才高不可当，才过德小必疏狂。", "纵然胸次罗星斗，岂是人间真栋梁。", "（下）（蒯越云）点汤！（正末醒科，云）大王安在？（蒯越云）点汤！（正末云）点汤，呼遣客。", "某只索回去。", "(蒯越云)点汤！（正末云）我出的这府门。", "（蒯越云）点汤！（正末云）我来到这和长街上。", "(蒯越云)点汤！（正末云）我来到这酒肆中。", "（蒯越云）点汤！（正末云）我来到这里，你不叫点汤！（蒯越诗云）非我闭贤门，因他傲慢人。", "（蔡瑁诗云）点汤呼遣客，依旧受孤贫。", "（并下）（正末叹科）罢罢罢！（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・煞尾","p":"","d":"元代","a":"郑光祖","c":["他年不作文章伯，异日须为将相材。", "待与不待总无碍，时与不时且宁耐。", "说地谈天口若开，伏虎降龙志不改。", "稳情取兴刘大元帅，试看雄师拥麾盖。", "恨汝等将咱厮害。", "（带云）我若得志呵，（唱）把你掳掠中军账门外，似这等跋扈襄阳吃剑才。", "（带云）将二贼擒至马前斩首报来！（唱）那其间才识俺长安少年客。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・中吕/粉蝶儿","p":"","d":"元代","a":"郑光祖","c":["尘满征衣，叹飘零一身客寄。", "往常我食无鱼弹剑伤悲，一会家怨荆王，信谗佞，把那贤门来紧闭。", "（带云）从那荆王辞世呵，（唱）不争你死丧之威，越闪得我不存不济。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・醉春风","p":"","d":"元代","a":"郑光祖","c":["我本是未入庙堂臣，倒做了不着坟墓鬼。", "想先贤多少困穷途，王粲也我道来命薄的不似你，你！我比那先进何及，想昔人安在，（带云）小生三十岁也，（唱）我可甚么后生可畏。", "（云）说话中间，可早来到也。", "楼下的报复去，王粲来了也。", "（从人报科）报的东人得知，王仲宣来了也。", "（许达云）道有请。", "（见科，云）仲宣请。", "（做上楼科）（诗云）欲穷千里目，（正末云）更上一层楼。", "（许达云）家童将酒过来，仲宣，蔬食薄味，不堪供奉，请满饮此杯。", "（正末云）敢问安道，此楼何人盖造？（许达云）仲宣不问，许达也不道，此楼是先父许士谦盖造。", "（正末云）因何造此？（许达云）因四方官宦，到此无可玩赏，故建此楼。", "（诗云）一座高楼映市廛，玉栏十二锁秋烟。", "卷帘斜眺天边月，举眼遥观日底仙。", "九酝酒光斟琥珀，三山鸾凤舞翩跹。", "停杯畅饮才歌罢，倒卧身躯北斗边。", "（正末诗云）安道，你看危楼高百尺，手可摘星辰。", "不敢高声语，恐惊天上人。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・迎仙客","p":"","d":"元代","a":"郑光祖","c":["雕檐外红日低，画栋畔彩云飞，十二栏干栏干在天外倚。", "（许达云）这里望中原，可也不远。", "（正末唱）我这里望中原，思故里，不由我感叹酸嘶。", "（带云）看了这秋江呵，（唱）越搅的我这一片乡心碎。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・红绣鞋","p":"","d":"元代","a":"郑光祖","c":["泪眼盼秋水长天远际，归心似落霞孤鹜齐飞，则我这襄阳倦客苦思归。", "我这里凭阑望，母亲那里倚门悲。", "（许达云）仲宣，既如此感怀，何不早归故里？（正末云）吾兄怕不说的是哩！（唱）争奈我身贫归未得。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・普天乐","p":"","d":"元代","a":"郑光祖","c":["楚天秋，山叠翠，对无穷景色，总是伤悲。", "好教我动旅怀，难成醉。", "枉了也壮志如虹英雄辈，都做助江天景物凄其。", "（云）老兄，小生有三桩儿不是。", "（许达云）可是那三桩儿不是？（正末云）是这气这愁和这泪。", "（许达云）气若何？（正末唱）气呵做了江风淅淅。", "（许达云）愁若何？（正末唱）泪呵弹做了江雨霏霏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・石榴花","p":"","d":"元代","a":"郑光祖","c":["现如如今寒蛩唧唧向人啼，哎，知何日是归期？想当初只守着旧柴扉，不图甚的，倒得便宜。", "（许达云）大丈夫得志食于钟鼎，不得志隐于山林。", "（正末唱）则今山林钟鼎俱无味。", "命矣时兮。", "哎，可知道枉了我顶天立地居人世。", "（许达云）仲宣，今年贵庚了？（正末唱）老兄也，恰便似睡梦里过了三十。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・斗鹌鹑","p":"","d":"元代","a":"郑光祖","c":["又不在麋鹿群中，又不入麒麟画里。", "自死了吐哺周公，枉饿杀采薇伯夷。", "自洛下飘零到这里，划的无所归栖。", "(带云)小生初投奔刘表的意呵，(唱)指望待末尾三稍，越闪的我前程万里。", "（许达云）仲宣，想昔日孔子投于齐景公，景公不能用，复投鲁哀公，封孔子为鲁司寇。", "三日而诛少正卯。", "齐景公故将美女数十人，习成女乐，献与哀公，哀公受了女乐，三日不朝。", "孔子弃职而归，投于卫灵公，与之言治国之道。", "卫灵公仰视飞雁，孔子知其不能用，投于陈国。", "其时陈国被吴国征伐，孔子遂困于陈蔡之间，粮食都绝，从者皆病不能起，圣人尚然如此，何况今日乎！老兄，(诗云)诗酒当前且尽情，功名休问几时成。", "天公自有安排处，莫为忧愁白发生。", "（正末诗云）三尺龙泉七心身，可堪低首困风尘。", "王侯将相元无种，半属天公半属人。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・上小楼","p":"","d":"元代","a":"郑光祖","c":["一片心扶持社稷，两只手经论天地。", "谁不待执戟门庭，御车郊原，舞剑尊席。", "（许达云）仲宣，当初肯与蒯、蔡，同列为官，可不好来？（正末唱）我怎肯与鸟兽同群，豺狼作伴，儿曹同辈？兀的不屈沉杀五陵豪气！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・幺篇","p":"","d":"元代","a":"郑光祖","c":["据着我慷慨心，非贪这潋滟杯。", "这酒呵便解我愁肠，放我愁杯，展我愁眉。", "则为我志愿难酬，身心不定，功名不遂。", "(云)吾兄将酒过来。", "（许达云）酒在此。", "（正末饮科，云）再将酒来。", "（许达云）仲宣，为何横饮几杯？（正末唱）倒不如葫芦提醉了还醉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・满庭芳","p":"","d":"元代","a":"郑光祖","c":["我如今羞归故里，则为我昂昂而出，因此上怏怏而归。", "空学成补天才却无度饥寒计，几曾道展眼舒眉。", "则被你误了人儒冠布衣，熬熬人淡淡饭黄齑。", "有路在青霄内，又被那浮云塞闭。", "老兄也百忙里寻不见上天梯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・尧民歌","p":"","d":"元代","a":"郑光祖","c":["真乃是鹤长凫短不能齐，从来这乌鸦彩凤不同栖。", "挽盐车骐骥陷淤泥，不逢他伯乐不应嘶。", "只争个迟也么疾，英雄志不灰，有一日登鳌背。", "（做睡科）（外扮使命上，诗云）雷霆驱号令，星斗焕文章。", "圣主贤臣颂，今朝会一堂。", "吾乃天朝使命是也。", "今有王仲宣献上万言长策，圣人见喜，宣他为天下兵大元帅，兼管左丞相事。", "打听得在许安道楼上饮酒，许安道在么？（许达见科，云）那里来的大人？（使命云）小官天朝来的使命，宣王仲宣为天下兵马大元帅，快报复去！（许达云）王仲宣，王仲宣！（正末云）做甚么大呼小叫的！（许达云）今有天朝使命，宣你为天下兵马大元帅。", "（正末云）来了不曾？（许达云）见在楼直下哩！（正末云）慌做甚么，心忙做甚么！既来了，怕他回了不成？（许达云）则吃你这般傲慢？（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・煞尾","p":"","d":"元代","a":"郑光祖","c":["从今后把万言书作战场，辅皇朝为柱石。", "扶侍着万万岁当今帝，则愿的稳坐定蟠龙戗金椅。", "（同使命下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・双调/新水令","p":"","d":"元代","a":"郑光祖","c":["一声雷震报春光，（卒按喝科）（正末唱）起蛰龙九重天上。", "蔡邕也你便似臧仓毁孟轲，王粲也我却做了贡禹笑王阳，则道我甘老在荆襄，今日个峥嵘日岂承望。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・沉醉东风","p":"","d":"元代","a":"郑光祖","c":["想当日到京师将谁倚仗？多亏你曹学士助我行装。", "虽然是一封书死了荆王，还得你万言策奏知今上，才得个元戎印掌。", "这都是你义海恩山不可当，再休题贵人健忘。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・乔牌儿","p":"","d":"元代","a":"郑光祖","c":["不由我肚儿里气夯，他有甚脸来俺门上。", "（云）他可不是蔡邕丞相么？（曹学士云）他可是谁？（正末唱）他是举韩侯三荐的萧丞相。", "往日的情我和他今日讲。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・水仙子","p":"","d":"元代","a":"郑光祖","c":["你道你精神颜色捧瑶觞，和气春风满画堂。", "你道我不明白冻死在颜回巷，我今日也列金钗十二行。", "尽今生急急忙忙，你那里有江湖心量，一片齑盐肚肠。", "（带云）令人抬过了酒肴者。", "（唱）饮不的我玉液琼浆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・甜水令","p":"","d":"元代","a":"郑光祖","c":["你道是位列三台，调和鼎鼐，燮理阴阳，丞相府气昂昂。", "觑的我元帅衙门，无过是点些士伍，排些刀仗，与文臣本不同行。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・折桂令","p":"","d":"元代","a":"郑光祖","c":["你不来呵但凭心上，我也不差着人来，请你登堂。", "（带云）你今日既来呵，（唱）谁着你鸟故趋笼，鱼偏入网，人自投汤。", "既受你这许多好情亲向，我岂可没半句恶语相相伤。", "（蔡相云）可知你与我也沾些亲来。", "（正末唱）从今后星有参商，人有雌黄。", "你做的吐哺周公，我也拚不做坦腹王郎（蔡相云）学士，你这里不说，那里说？（曹学士云）老丞相休慌。", "元帅请暂息雷霆之怒，略罢虎狼之威，听小官明明的说破，着元帅细细里皆知。", "人不说不知，木不钻不透；冰不搦不寒，胆不尝不苦。", "当初老丞相曾与令尊老先生金兰契友，二人指腹成亲，若生二女，同攀绣床；若生二子，同舍攻书；若生子女，结为夫妇。", "不想令尊生下元帅，丞相所生一女。", "因为官守所绊，彼各天涯，间隔亲事。", "老丞相闻知元帅学成满腹文章，只是骄矜傲慢，不肯曲脊于人，以此数次将书调取至京，萧条旅馆，个月期程，不蒙放参。", "可是为何？只是涵养你那锐气。", "及至相见，将那三杯酒耻辱元帅，一席话激发将军。", "岂知春衣白金雕鞍书礼，都不是小官的，老丞相暗暗的与我，着我明明的与你，赍发你投托荆王刘表。", "谁想刘表不能任用，淹留在彼，你将万言长策，寄与小官，小官转与老丞相，老丞相献与圣人，圣人见喜，今得此官。", "自从元帅去后，老丞相将老夫人搬至京师，一般盖下画堂，又陪房奁断送，将小姐聘与元帅为妻。", "说兀的做甚！（诗云）则为你襄阳久困数年间，今日拨开云雾见天颜。", "非干我这举贤曹子建，则拜你那恩人老泰山。", "（正末拜科，云）则被你瞒杀我也，丈人！（蔡回礼科，云）则被你傲杀我也，女婿！（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・雁儿落","p":"","d":"元代","a":"郑光祖","c":["又不曾趋跄天子堂，又不曾图画臣像。", "止不过留心在笔砚间，又不曾恶战在沙场上。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・得胜令","p":"","d":"元代","a":"郑光祖","c":["呀！怎做得架海紫金梁，则消得司县绿衣郎。", "今日个枢府新元帅，还只是长安旧酒狂。", "腾骧，端的有豪气三千丈；游扬，这的是功名纸半张。", "（蔡相云）天下喜事，无过子母夫妇团圆。", "就今日卧翻羊、窨下酒，做个大大庆喜筵席者！（词云）我两姓结婚姻原在生前，难道我今日敢违背初言。", "因此上屡移书接来到此，本待将加官职指引朝天。", "只为你生性子十分骄傲，并不肯谦谦的敬老尊贤。", "我特将三杯酒千般折挫，无非要涵养得气质为先。", "暗地里具书呈白金骏马，封皮上明写着子建相传。", "岂知道到荆州依然不遇，遂淹留不得返苒三年。", "想登楼这一点思乡客泪，多应是长飘洒似雨涟涟。", "万言策又是我转闻今上，才得授大元帅入掌兵权。", "早先期高平去迎将老母，预盖下大宅院供具全。", "专等待你回来选其吉日，与小女结花烛夫妇团圆。", "此皆由我老夫殷勤留意，非学士能出力为你周旋。", "到如今才一一从头说破，大家的开笑口庆赏华筵。", "（正末唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉思乡王粲登楼・离亭宴煞","p":"","d":"元代","a":"郑光祖","c":["你元来为咱气锐加涵养，须不是忌人才大遭魔障。", "端的个这场，收拾了龙争虎斗心，结果了鹗荐鹏搏力，表明了海阔天高量。", "安排下玳瑁筵，准备着葡萄酿，做一个团圆的庆赏。", "早匹配了青春女一生欢，稳情取白头亲百年享。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・仙吕/端正好","p":"","d":"元代","a":"无名氏","c":["渭城歌，阳关恨，别离罢路践红尘。", "可怜见女孩儿独自个无人问。", "父亲也，你是必频频的稍带一纸平安信。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・仙吕/点绛唇","p":"","d":"元代","a":"无名氏","c":["自从俺父亲往京师，妾身独自忧愁死。", "掌把着许大家私，无一个人扶侍。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・混江龙","p":"","d":"元代","a":"无名氏","c":["耽阁了二十一二，好前程不见俺称心时。", "每日家鬓鬟羞整，粉黛慵施。", "熬永夜闲描那花样子，捱长日频拈我这绣针儿。", "每日家重念想，再寻思，情脉脉，意孜孜，几时得效琴瑟，配雄雌，成比翼，接连枝？但得个俊男儿，恁时节才遂了我平生志。", "免的俺夫妻每感恨，觑的他天地无私。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・油葫芦","p":"","d":"元代","a":"无名氏","c":["甚风儿吹你个姑姑来到此？(道姑云)贫姑一径的来望小姐。", "(正旦云)姑姑请坐。", "(唱)慌忙将礼数施。", "(道姑云)小姐，老相公去后，你每日做甚么功课？(正旦云)我绣着一床锦被哩。", "(唱)自从我绣鸳鸯，几曾离了绣床时？我着这金线儿妆出鸳鸯字，我着这绿绒儿分作鸳鸯翅。", "你看那枝缠着花，花缠着枝。", "(道姑云)小姐，这是甚么主意？(正旦唱)直等的俺成就了百岁姻缘事，恁时节才添上两个眼睛儿。", "(道姑云)小姐费得功夫多了。", "(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・天下乐","p":"","d":"元代","a":"无名氏","c":["则这鸳鸯被是我夫妻也那信有之，(道姑云)小姐，你拣个好财主每好秀才每，或招或嫁，可不好那？(正旦云)姑姑，你说他怎的！(唱)嗟也波咨，可也甚意儿。", "则为我父亲家，因此上不曾理婚姻事。", "说的人睡卧又不宁，害的人涕喷又不止，你着我不明白憔悴死。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・后庭花","p":"","d":"元代","a":"无名氏","c":["则我这瘦形骸削了四肢，小腰身争了半指。", "宽掩过罗裙摺，全松了我这楼带儿。", "(带云)我父亲呵，(唱)他一去几多时，杳没个音书来至。", "撇得我冷清清泪似丝，闷恹恹过日子。", "学刺绣一首诗，索对那两句词。", "空展开花样纸，摺成个简帖儿，又不是请亲邻会酒卮，只把小梅香胡乱使。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・柳叶儿","p":"","d":"元代","a":"无名氏","c":["你着我和谁传示？只落得清减了脸上胭脂。", "这姻缘知道落在何人氏？我李玉英是闺中女，你姑姑是个出家儿，可不空费你这一片神思。", "(道姑云)小姐，您恰才不说来？妇人无夫是身无主。", "虽然老相公不在家，难道十年不回，守他十年？二十年不回，守他二十年，可不等老了人？(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・青哥儿","p":"","d":"元代","a":"无名氏","c":["非是我推三、推三阻四，这事情应难、应难造次，虽然道男女婚姻贵及时。", "我须是娇滴滴美玉无疵，又不比败草残枝，怎好的害杀相思？只待要寻个人儿，便窬墙钻穴也无辞，这等胡行事！(道姑云)小姐，这也不妨事。", "只要寻的个人儿停当。", "(正旦云)人儿那里？(道姑云)这个人就是当初老相公借银子的刘员外。", "他是名门旧族，现有百万家财，何等不好？(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・寄生草","p":"","d":"元代","a":"无名氏","c":["你道他是名门子，又道他富不赀。", "(道姑云)你老相公借他十个银子，如今该本利二十个，须要还他哩。", "(正旦云)待我父亲回来还他，干我甚事？(唱)他有钱财只做得钱财使，(道姑云)他道老相公借银子的文书，你也画得有字来。", "(正旦唱)论婚姻须不曾画个婚姻字，(道姑云)当日借银子原写着我是保人，他要拖我到官中告去。", "我是出家人，怎么好做借银子的保人？可不连累我，倒替你吃官司！(正旦唱)便吃官司我也拼得替你官司死。", "总饶他铜山百座邓通家，怎动的我琴心一曲临邛氏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・赚煞","p":"","d":"元代","a":"无名氏","c":["则你那修道的玉清庵，索强如题笔的金山寺。", "罗帏里新婚燕尔，舒展开鸳鸯锦被儿，可着我羞答答说甚言词。", "这些时素质冰姿，也是我不合先接了东君第一枝。", "道与那多情的秀士，偷传心事，到天明是必休撇了这个女孩儿。", "(同梅香下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・正宫/端正好","p":"","d":"元代","a":"无名氏","c":["不由我意张狂，心惊乍，谁曾向街苍行踏。", "你深也紧避在房檐下，方信道色胆有天来大。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・滚绣球","p":"","d":"元代","a":"无名氏","c":["兀的甚势沙，甚礼法，索甚么问天来买卦。", "莫不我与那刘员外合做浑家？他为咱，我为他，好着我放心不下。", "办着个志诚心，着俺这夫妇每欢洽。", "可是怎生黑洞洞桌面上绝了灯火，云黯黯碧天边闭了月华，倒省的人多少喧哗。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・脱布衫","p":"","d":"元代","a":"无名氏","c":["不索你阶直下絮絮答答，门儿外唱叫呀呀。", "我问你罗帏里书生有么？哎，你草庵中道童休唬。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・小梁州","p":"","d":"元代","a":"无名氏","c":["就把姑姑央及煞，可怜我这没照觑的娇娃。", "早唬的来手儿脚儿软刺答，怎抬踏，好着我便心似热油炸。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・幺篇","p":"","d":"元代","a":"无名氏","c":["我和他乍相逢难说知心话，只索羞答答手抵着门牙。", "(小姑云)你行动上些，员外在些等哩。", "(正旦唱)你将我省可里推，我可也其实怕，就着这钟声才罢，却道无事早还家。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・黄钟尾","p":"","d":"元代","a":"无名氏","c":["从今后丹墀策试千言罢，彩笔题成五色霞。", "一举鳌头占科甲，秉笏当胸当胸立朝下。", "乌帽宫花数枝插，御宴琼林醉到家。", "除授为官赐敕札。", "夫人县君合与咱。", "那时我坐香车你乘马，咱两上稳稳安安兀的不快活杀。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・越调/斗鹌鹑","p":"","d":"元代","a":"无名氏","c":["往常我在画阁兰堂，牙床翠屏，烛暗银台，香焚宝鼎，百色衣冠，诸般器皿。", "乍离普救寺，钻入这打酒亭。", "你畅好是性狠也夫人，毒心也那郑恒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・紫花儿序","p":"","d":"元代","a":"无名氏","c":["今日远乡了君瑞，逃走红娘，单撇下个莺莺。", "为家私少长无短，则得忍气吞声。", "(带云)这也是我父亲不是。", "(唱)分明那白纸上教我画着黑字儿是怎么，倒留做他家凭证。", "却将我宅院良人，生扭做酒店里驱丁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・小桃红","p":"","d":"元代","a":"无名氏","c":["则俺祖宗积世有声名，三辈儿为参政。", "(张瑞卿云)哦，原来是宦家。", "你父亲如今那里去了？(正旦唱)俺家君一生正直无邪佞。", "惹人憎，如今勾赴尚书省。", "(张瑞卿云)你父亲这一向也还做官么？(正旦唱)官封左丞，告辞老病．(张瑞卿云)如今你父亲去几时了？(正旦云)怎知他数载不回程。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・调笑令","p":"","d":"元代","a":"无名氏","c":["说着呵怎听，那泼书生，呀，盖世里全无他不志诚。", "(张瑞卿云)这秀才也有好的么。", "(正旦云)如今这秀才家一个个害了传槽病，从今后女孩儿每休惹他这酸丁。", "(张瑞卿云)元来小娘子也曾有夫主来？(正旦唱)都是些之乎者也说全成。", "我道来可是者么娘七代先灵。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・耍三台","p":"","d":"元代","a":"无名氏","c":["当初也无红定无媒证，(张瑞卿云)这等怎生成亲来？(正旦唱)做的来藏头漏影，知他是今世是前生，总则我红颜薄命。", "真心儿待嫁刘彦明，偶然间却遇张瑞卿。", "(张瑞卿背云)奇怪，道着小官的名讳。", "此事必然暗昧。", "我再问他。", "(回云)当初可是谁作成你来？(正旦唱)当是初是那撮合山的姑姑，(张瑞卿云)小娘子可是谁那？(正旦唱)送了这望夫石的玉英。", "(张瑞卿背云)他说的正是我，我如今一发问他咱。", "小娘子，当初成亲，那人姓甚名谁？他如今可往那里去了？(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・圣药王","p":"","d":"元代","a":"无名氏","c":["去了俺那丑生，撞着俺这短命。", "(张瑞卿云)如今这酒店是甚么人的？(正旦唱)他是个放钱举债的爱钱精。", "(张瑞卿云)你可为甚么到这里？(正旦唱)他使弊幸，使气性，无钱踏着陌儿行，推我在这陷人坑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・幺篇","p":"","d":"元代","a":"无名氏","c":["我可也不曾，半星也不动情，则由他法外施行。", "(张瑞卿云)你为何不随顺他？(正旦唱)我便死呵是张家妇名，怎肯踹刘家门径？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・收尾","p":"","d":"元代","a":"无名氏","c":["俺哥哥替还了原借银十锭，两事家临危自省。", "第一来把俺这亲兄长好看成，第二来将俺那俊男儿奈心等。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・双调/新水令","p":"","d":"元代","a":"无名氏","c":["这洛阳城刘员外他是个有钱贼，只要你还了时方才死心塌地。", "他促眉生巧计，开口讨便宜。", "总饶你泼骨顽皮，也少不得要还他本和利。", "(张瑞卿云)妹子，俺父亲借他银子，须待俺父亲来还。", "你不肯嫁他，也由得你。", "(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・步步娇","p":"","d":"元代","a":"无名氏","c":["只为那举债文书我画的有亲笔迹，因此上被强勒为妻室。", "这真心儿誓不移，情愿方打千敲受他磨到底。", "今日留得个一身归，谢哥哥肯救我亲生妹。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・雁儿落","p":"","d":"元代","a":"无名氏","c":["则也这行装特整齐，书舍无俗气。", "瑶琴壁上悬，宝剑床头立。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・得胜令","p":"","d":"元代","a":"无名氏","c":["呀！我与你搭起绿罗衣，铺开紫藤席。", "绣枕头边放，香衾手内提。", "索甚么疑惑，这是我绣来的鸳鸯被；可不是跷蹊，谁承望这搭儿得见你？(云)好是奇怪，这被儿原是绣来的，是我与张瑞卿来，可怎生得到俺哥哥手里？待他来家时，我试问他波。", "(张瑞卿做醉科上，云)我醉了也。", "妹子在那里？(正旦做扶末，云)哥哥有酒也，吃甚么茶饭？(张瑞卿云)妹子，甚么茶饭都吃不了，我醉了也。", "(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・沽美酒","p":"","d":"元代","a":"无名氏","c":["则他这酸黄齑怎的吃，粗米饭充饥，怕哥哥害渴时冰调些凉蜜水。", "我玉英有句话儿敢题？(张瑞卿云)妹子有话，但说不妨。", "(正旦唱)问的我陪着笑卖查梨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・太平令","p":"","d":"元代","a":"无名氏","c":["若问哥哥休讳，这鸳鸯被委是谁的？(张瑞卿云)是我的妹子与我的。", "(正旦唱)除妹子别无甚妹子，除哥哥别无甚兄弟。", "我玉英呵世做的所为，这里，便跪膝，则鸳鸯被要知根搭底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・锦上花","p":"","d":"元代","a":"无名氏","c":["这厮倚恃钱财，虚张声势。", "硬保强媒，把咱凌逼。", "重则鞭笞，轻则骂詈。", "难道河有澄清，人无得意。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・幺篇","p":"","d":"元代","a":"无名氏","c":["当时曾受亏，今日也还席。", "大小荆条，先决四十。", "再发有司，从公拟罪。", "钱呵通神，法难纵你。", "(李府尹云)张瑞卿和老夫同到宅中。", "今日是个吉日良辰，与女孩儿永远为夫妻。", "一面杀羊造酒，做个庆喜的筵席。", "(做到宅，张瑞卿同正旦拜成礼科)(正旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"玉清庵错送鸳鸯被・清江引","p":"","d":"元代","a":"无名氏","c":["想人生百年能有几，要博个开颜日。", "父子共团圆，夫妇重和会，这便是出寻常天大的喜。", "(李府尹诗云)贼徒唬吓结良缘，号令沉枷在市廛。", "欠钱索债虽常事，倚富欺贫岂有天？新婚今朝为令尹，老夫依旧得生旋。", "杀羊造酒排筵宴，夫荣妻贵喜团圆。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・仙吕/赏花时","p":"","d":"元代","a":"刘君锡","c":["谁不知道财上分明是这大丈夫，从今后休着你那心下熬煎枉受苦，你是必好将息这病身躯。", "(李孝先云)元少居士的银子又不问小生要，又与我这两个银子，此恩异日必当重报。", "(正末唱)这银子是我肯心儿愿与，(李孝先云)则是教小生难以克当也。", "(正末云)既是我与你呵，(唱)更论甚么得之有可敢失之无。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・仙吕/点绛唇","p":"","d":"元代","a":"刘君锡","c":["尘世人伦，我可也煞曾穷问，长思忖。", "他可便趋富嫌贫，不想那富贵可是天之分。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・混江龙","p":"","d":"元代","a":"刘君锡","c":["有等人精神发愤，都待要习文演武立功勋。", "演武的不数那南山射虎，习文的堪叹这西狩获麟。", "获麟的鲁国岂知夫子圣，射虎的霸陵谁问你个旧将军。", "屈沉杀一身英勇，枉费尽半世辛勤。", "对面儿高车驷马，转回头可早衰草荒坟。", "我待要抛家业，乐闲身，或是琴一操，酒三巡。", "我为甚一生潇散不恋那一生钱，大刚来这十年富贵也只是十年运。", "运去呵，有如那风摇画烛，天散也的这浮云。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・天下乐","p":"","d":"元代","a":"刘君锡","c":["他可也便见如同陌路人。", "(曾云)我想这等人，何足道哉！(正末唱)也非是小生多议论。", "则我这一片济贫的心比他人心地真。", "(曾云)依居士的主见，可是如何？(正末唱)我恨不的罄囊儿舍与人些钱。", "恨不的刮土儿可便散与人些银，(曾云)这许多钱债文书都烧毁了，可惜了也。", "(正末云)便好道：万般将不去。", "惟有业随身。", "先生也，(唱)量这千百锭家旧文契有那的几锭本。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・那吒令","p":"","d":"元代","a":"刘君锡","c":["有一个为富的似欧明涉津，遇龙衬海神；有一个为富的似元载待宾，仿玄宗圣人；有一个为富的似梁冀害民，灭全家满门。", "我如今待觅一个隐沦，待寻一个逃遁，也只要免的他恶业随身。", "(曾云)居士差矣！你家的富贵，不是你祖上遗留的，便是你自家挣起来的，何苦又要逃遁他去，这也太过了。", "(正末云)先生，还有一等无端的小人，到那腊月三十日晚夕，将那香灯花果祭赛，道是钱呵，你到俺家里来波！那的都是邪气。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・鹊踏枝","p":"","d":"元代","a":"刘君锡","c":["谁待要祭那财神，我则待送那魔君。", "缠杀我也财物金银，我觑的似吊客丧门。", "倒不如将他来与贫乏家施舍尽，另做个种果收因。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・六幺序","p":"","d":"元代","a":"刘君锡","c":["这钱呵，无过是乾坤象，熔铸的字体匀。", "这钱呵何足云云。", "这钱呵使作的仁者无仁，恩者无恩，费千百才头的居邻。", "这钱呵动佳人行意郎君俊，糊突尽九烈三真。", "这钱呵将嫡亲的昆仲绝了情分，这钱呵也买不的山丘零落，养不的画屋生春。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・幺篇","p":"","d":"元代","a":"刘君锡","c":["谁待殷勤，颇奈钱亲。", "钱聚如兄，钱散如奔。", "钱本无根，钱命元神。", "到底来养身波也那丧身，这钱呵兀的不送了多人。", "当日个宣帝为君，疏傅为臣，是汉朝大老元勋，赐千金为具归途赆，青门外供帐如云。", "(曾云)到后来可是如何？(正末唱)他到家乡都给散心无吝，这故事在两贤遗传，千古流闻。", "(曾云)小生与居士共同一席话，胜读十年书。", "想居士这等疏财仗义，高才大德，今日相别，后会有期。", "(正末云)行钱，去将一饼金来。", "(行钱云)理会的。", "(正末云)备一匹全副鞍辔的马来。", "(行钱云)鞍马也有了。", "(正末云)先生，这一饼金与先生做路费，这一匹马与先生代步咱。", "(曾云)居士，小生本为仰德而来，非为财物而至，焉敢当居士如此厚礼，这个断然不好受得。", "(正末云)请先生受了者。", "(曾云)我小生决然不敢受，便受了也无用处。", "过二十年之后，小生与居士再会。", "(正末云)二十年之后有先生，敢无在下了也。", "(曾云)据着居士这等阴骘太重，必然增福延寿也。", "(做别科，云)小圣恰才见此人积功累行，施仁布德，俺神灵如何无一个报应。", "便好道：善有善报，恶有恶报，不是不报，时辰未到。", "(诗云)休将奸狡昧神祗，祸福如同逐影随。", "善恶到头终有报，只争来早与来迟。", "(下)(正末云)呀！天色晚了也。", "行钱，跟我宅前院后烧香去来。", "(行钱云)理会的。", "(正末云)这个是我那油房，装香来。", "南无阿弥陀佛！这个是我那粉房，装香来。", "(行钱云)香在此。", "(正末云)南无阿弥陀佛！这个是我那磨房。", "(净扮磨博士上，打罗唱科，云)牛儿你不走，我就打下来了。", "(正末云)行钱，甚么人这般唱歌口旦曲的？他心中必然快活。", "你与我唤他出来，我问他咱。", "(行钱云)兀那罗和，你出来，爹唤你哩。", "(磨博士云)来也，来也，谁唤罗和哩？(正末云)孩儿也，是我唤你哩。", "(磨博士云)唤我做甚么？误了我打罗也。", "(正末云)你才唱歌口旦曲，你心中必然快活，你试说咱。", "(磨博士云)爹，你道我这般唱歌口旦曲，我那里有甚么快活？孩儿每受苦哩。", "我一日我请着爹二分工钱。", "我清早晨起来，我又要拣麦，拣了麦又要簸麦，簸了麦又要淘麦，淘了麦又要晒麦，晒了麦又要磨面，磨了面又要打罗，打了罗又要洗麸，洗了麸又要撒和头口，只怕睡着了误了工程，因此上我唱歌口旦曲。", "爹，我那里是快活。", "你省的古墓里摇铃，则是和哄我那死尸哩。", "(正末云)嗨！我可怎生知道。", "不问你别事，你这眼上两根棒儿，为甚么支着？(磨博士云)爹，你道我为甚么眼上支着这两根棒儿？我白日里做了一日生活，到晚来恐怕打盹睡着了，误了你家生活，因此上支着这两根棒儿。", "你孩儿受。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・醉扶归","p":"","d":"元代","a":"刘君锡","c":["我为甚么相怜悯，与你这一锭家那雪花银？(磨博士云)爹，你可为甚么与我这银子？(正末唱)我则报答你那脚打罗三年这足一下恩。", "(磨博士云)爹，我罗和请罪咱。", "我昨日瞒着爹做一个贼，偷了二升麦子，去那长街市上算了一个卦，那先生说我今年今月今日今时，可当发迹，得些儿横财。", "不想爹叫我出来，与了我这个银子，那先生也会算哩。", "(正末唱)那人也算的着轮到你那磨眼儿今日合交运。", "(磨博士云)爹，你与我这个银子，去做甚么生意好？(正末唱)这银子我与你做买卖权时做本，(磨博士云)多谢爹，孩儿从今以后，再也不打罗了。", "(正末唱)哎！孩儿呵，我从今以后再不要你似这般当粗坌。", "(磨博士云)则说银子银子，谁曾见他来？这个原来是银子。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・赚煞","p":"","d":"元代","a":"刘君锡","c":["暗评跋，忽笑哂，则被这钱使作的咱如同一个罪人。", "我待向那万丈洪波，落可便一跳身，转回头别是个乾坤。", "叹浊民空攒下那万余锭金银，却也买不得三阳也那洞里春。", "(带云)这钱呵，我当初要用你时，(唱)可便一分不肯，(带云)到今日我要舍钱时，(唱)可便于金何靳，(云)兀那世间的人，那贪财好贿，苦海无边，回头是岸，何不早结善缘也。", "(唱)则咱这百年人谁识百年人。", "(同行钱下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・中吕/粉蝶儿","p":"","d":"元代","a":"刘君锡","c":["若论着今日风俗，正好宜太平箫鼓，有一等寒俭的泛泛之徒，他出来的不诚心，无实行，一个个强文假醋。", "(卜儿云)如今有一等高巾傲带，表德相呼。", "不知他那肚皮里如何？(正末唱)们不他表德相呼，你问波可甚的是那衣冠文物。", "(卜儿云)居士，那称才卿的，可是怎生？(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・醉春风","p":"","d":"元代","a":"刘君锡","c":["他那等空傲慢的唤做才卿，(卜儿云)那称好古的，可是如何？(正末唱)那等假老成的唤做甚么好古。", "(卜儿云)据居士恤孤念寡，敬老怜贫，世之少有也。", "(正末唱)凭着我疏财仗义行几人？如这城中试数，数。", "们见个老的呵，我早则出力的扶持；但见个病的呵。", "我早则尽心儿调养；但见个贫的呵，我早则倾囊儿资助。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・红绣鞋","p":"","d":"元代","a":"刘君锡","c":["他几曾道开东阁把那名儒来管顾，他每可动不动便宴西楼和那妓女每欢娱，(云)他则请人吃一盏茶呵，却早算计也。", "(唱)他将那茶托子人情可便暗乘除。", "常则是佯呆着回过脸，推说话纽身躯，(云)若有个穷相识来，便舍着磕破他头者波，(唱)他每可几曾做那五百钱东道主？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・醉高歌","p":"","d":"元代","a":"刘君锡","c":["枉了我便一生苫鳏寡孤独，半世养贫寒困苦。", "我则道是谁人向这槽畔低低叙，听沉了着我惨惨的怕怖。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・石榴花","p":"","d":"元代","a":"刘君锡","c":["你道我烧毁了文契意何如？岂不闻君子可便断其初？(卜儿云)哎，居士咱，人自是有钱的好。", "(正末唱)想着俺借钱时有甚恶心术，怎知做今生债负，来世追补？则愿的祖师指示我向西方去，早回头拔出迷途。", "(云)烧了者！烧了者！(卜儿云)居士，你留着，休要烧毁了。", "(正末唱)则管里便左来右去把我邀拦住，这钱也他敢不是我那护身符。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・上小楼","p":"","d":"元代","a":"刘君锡","c":["且休论咱这仓廒波务库，更和这家私也那无数。", "应有的金银财宝，收拾将来，放在一处。", "则人你这娘儿海嘶瞅着厮守着，休离了十步，看你那无常时可便带的他同去。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・幺篇","p":"","d":"元代","a":"刘君锡","c":["钱无那三辈儿家钱，福无那两辈儿家福。", "你但看日中则盈，月满则亏，这都是无往不复。", "久以后到头来另有个养身活路，(卜儿云)你将钱债的文书都烧毁了，还有甚养身活路在那里？(正末做念佛科，唱)我待着你一家儿受佛门普度。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・耍孩儿","p":"","d":"元代","a":"刘君锡","c":["你待着我万余资本为商贾，攒利息冲州撞府。", "或足乘船鼓棹渡江湖，或是从鞍马昼夜驰驱。", "我干做了撇妻男店舍里一个飘零客，抛家业尘埃中一个防送夫。", "冷清清梦回两地无情绪，怎熬的程途迢递，更和那风雨潇疏？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・二煞","p":"","d":"元代","a":"刘君锡","c":["古人道鹪鹩巢深林无过占的一枝，鼹鼠饮黄河无过装的满腹。", "咱人这家有万顷田，也则是日食的三升儿粟。", "博个甚睁着眼去那利画上克了我的衣食，闲着子去那算盘里拨了我的岁数。", "攒下些山岸也似堆金玉，这壁厢凌逼着我家长，那壁厢快活杀他妻孥。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・煞尾","p":"","d":"元代","a":"刘君锡","c":["我去那洒色财气行取一纸儿重招，我去那生老病死行告一纸儿赦书。", "岂不闻道儿孙自有儿孙福？我其实便作不的这业，当不的这家，受不的这苦。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・越调/斗鹌鹑","p":"","d":"元代","a":"刘君锡","c":["我弃了这千百顷家良田，便是把金枷来自解。", "我沉了这万余锭家私，便是把玉锁来顿开。", "玳瑁珊瑚，砗磲琥珀，你当初生处生，今日个可便来处来。", "(带云)我若无你呵，(唱)再不做那天北的这经商，我也再不做那江南的贾客。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・紫花儿序","p":"","d":"元代","a":"刘君锡","c":["我愁的是更筹漏箭，我怕的是暮鼓晨钟，我倦的是这紫陌黄埃。", "大刚来光阴迅速，怎教我不心意裁划，早早的安排。", "待把我这一寸心田无挂碍，大道的事着你世人不解。", "则愿的一帆西风，送上我那三岛蓬莱。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・天净沙","p":"","d":"元代","a":"刘君锡","c":["有如那花正开风卸风衰，有如那月初圆云暗云埋，跳不出这尘寰世界。", "我觑了委实痴呆，(带云)那船上的，那里是甚么金银宝贝？(唱)只当是装一船家兀那横祸非灾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・鬼三台","p":"","d":"元代","a":"刘君锡","c":["也非是我胸襟大，将金宝和船载，我只待跳出这尘寰得自在？(卜儿云)居士，你便老了，儿女每正后生哩。", "(正末唱)你道是白发叹吾侪，我道足今番畅快哉。", "趁着这风力软水横天地窄，帆力稳影吞雪浪开。", "这便是风送王勃，赴洪都的命彩。", "(卜儿云)居士，你看那海岸上看俺沉舟的人，好不多也。", "(正末云)兀那君子每，我庞居士这个念头，比别人不同。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・紫花儿序","p":"","d":"元代","a":"刘君锡","c":["我不比那越范蠡驾扁舟游那五湖的这烟浪，我不比那晋石崇送穷船葬万顷波澜，我不比那汉张骞泛浮槎探九曜星台。", "(带云)你觑波，(唱)我则见水接着天泻混元一派，我则见天连着水可便无半点儿纤埃。", "我为甚喜笑盈腮，待着他水晶宫里龙王放一会儿解，这一场我直撑杀他鱼鳖和那虾蟹。", "觑了这万丈风涛，兀的不险似百尺楼台。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・凭栏人","p":"","d":"元代","a":"刘君锡","c":["天际残霞几缕裁，水映天心有如那霞衬彩。", "恰才个船随着海岸开，抵多少烟波风送客。", "(云)婆婆，这船只是不沉，也可怪哩。", "(唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・寨儿令","p":"","d":"元代","a":"刘君锡","c":["我则见雪浪涌似山排，可怎生又风恬水平云雾霭。", "难道是积羽沉舟，这金银呵反为轻载？心儿里好疑猜。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・幺篇","p":"","d":"元代","a":"刘君锡","c":["为甚么这番滚滚海藏里不沉埋？(云)这船怎生不沉？婆婆，我猜着了也。", "(唱)他本是个虚飘飘世上的浮财。", "我和你发虔心祷上苍，近岸口跪苍苔，(云)婆婆、灵兆、凤毛，都来拜者。", "(唱)拜、拜、拜，直拜到那月上的这海门开。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・金蕉叶","p":"","d":"元代","a":"刘君锡","c":["我则听的霹雳响惊魂丧魄，唬的我四口儿无颜落色。", "我则见云偶斗空中乱摆，恰便似千百面征鼙乱凯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・调笑令","p":"","d":"元代","a":"刘君锡","c":["我可便自来几曾该端的便几曾该，抵多少一夜西风透霎时间四野阴霾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・秃厮儿","p":"","d":"元代","a":"刘君锡","c":["赤历历那电光掣一天家火块，吸力力雷霆震半壁崩崖。", "俺这里轻身向前将这海岸踹，(卜儿扯科，云)居士靠后些。", "(正末云)婆婆，你怕甚么？(唱)你还耽着鬼魂胎，哀哉。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・圣药王","p":"","d":"元代","a":"刘君锡","c":["吹的我头怎抬，刮的我眼倦开，(云)龙王呵，你这般烦恼怎么？(唱)又不比入山推出白云来。", "渐的呵风力衰，忽的呵云乱摆。", "只要你沉了咱锦帆舟楫共资财，做的个一去不回来。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・收尾","p":"","d":"元代","a":"刘君锡","c":["谁不知道庞居士误放了来生债，我则待姓名儿千年万载。", "你便积攒下高北斗杀身的钱，(云)婆婆、灵兆、凤毛，你回头试看波。", "(唱)可也填不满这东洋是汇海。", "(同下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・双调/新水令","p":"","d":"元代","a":"刘君锡","c":["谁似我静中参透了这祖师禅，我待向雪山头养心修炼。", "当日那溶溶的天似水，漫漫的海无边。", "一自沉了我那家缘，我将这成道记诵千篇。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・沉醉东风","p":"","d":"元代","a":"刘君锡","c":["谁更敢推辞腼腆，我并不曾半霎儿俄延。", "我从来富不骄，端的个贫无怨。", "(青衣云)不只我来，兀的不又是一个来也。", "(正末做回头科)(青衣云)疾！(下)(正末云)在那里？(唱)他把我赚回头早海变桑田，(内动乐声科)(正末云)是好乐声也。", "(唱)我则听的聒耳笙歌秦管弦，那一派仙音得这韵远。", "(做看科，云)婆婆，你看那金门玉户，碧瓦琉璃，比尘世不同，此处必是天宫也。", "(卜儿云)居士，你看这牌面上写着字儿哩。", "(正末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・雁儿落","p":"","d":"元代","a":"刘君锡","c":["兀的不明明的在这门额上显，分朗朗在这牌面上见。", "牌面上青书篆着的是兜率宫，门额上金字镌着的是灵虚殿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・得胜令","p":"","d":"元代","a":"刘君锡","c":["这里可敢别是一重天，俺又不曾高驾五云轩。", "(云)婆婆，世间则有红莲花、白莲花，那得这青莲花、金莲花？(唱)这的是太液莲如锦，可则抵多少青山花欲燃。", "(云)婆婆，你见么？一个石洞门开着牛壁儿，掩着半壁儿，你子母每敢先过去么。", "(卜儿同灵兆、凤毛过洞门科)(卜儿云)居士，俺先过洞门来了也。", "(正末云)婆婆，你瞒着我多哩。", "(唱)却不是你从前，多与人行方便；着硬处你早当先，岂不闻心坚石也穿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"庞居士误放来生债・折桂令","p":"","d":"元代","a":"刘君锡","c":["这的是庞居士四圣归天，出世超凡同共朝元。", "则为我救困扶危，疏财仗义，都做了注福消愆。", "今日个乘彩凤十洲阆苑，跨苍鸾弱水三千。", "我劝你人世官员，莫恋浮钱。", "只将那好事常行，管教你一个个得道成仙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・伴读书","p":"","d":"元代","a":"高文秀","c":["泰安州便有那千千丈陷虎池，万万尺牢龙阱，我和你待摆手去横行。", "管教他抹着我的无干净，保护得俺哥哥不许生疾病。", "若是有差迟失了军中令，哥也，我便情愿纳下一纸儿军状为凭。", "（宋江云）山儿，你要写文书最好。", "只是你输着甚么？（正末云）哥也，您兄弟这一去，保护得哥哥无是无非还家来。", "若有些失错呵．我情愿输三两银子。", "（宋江云）这个少哩。", "（正末云）哦，我再做个东道，请你那一班落保的都吃一个烂醉何如？（宋江云）也还少哩。", "（正末云）罢、罢、罢，我情愿输了这六阳魁首。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・耍孩儿","p":"","d":"元代","a":"高文秀","c":["是和非谁共你闲相竞，假若是买物件，多和少也不和他争。", "若有醉汉每骂我一千场，（带云）哥也，你写的是。", "（唱）我只索忙陪着笑脸儿相迎。", "那厮鼻中残涕望着我这耳根边喷，那厮口内顽涎望着我面上零。", "再不和他亲折证，我只是吞声忍气，匿迹潜形。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・一煞","p":"","d":"元代","a":"高文秀","c":["有那等打擂台，使会能，摆山棚，博个赢，占场儿没一个敢和他争施逞。", "拳打的南山猛虎难藏隐，脚踢的北海皎龙怎住停。", "我也只紧闭口不放些儿硬，我只做没些本领，再不应承。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・三煞","p":"","d":"元代","a":"高文秀","c":["那大嫂年又青，貌又整，则被他一班儿恶少相缠定。", "似这等天宽地荡的清平世，怎容得女纵男淫泼贱精？触犯我真无幸，请大嫂轻轻移步，和哥哥慢慢同行。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・哨篇","p":"","d":"元代","a":"高文秀","c":["可便道\"恭敬不如从命\"，今日里奉着哥哥令。", "若有人将哥哥厮欺负，我和他两白日便见那簸箕星。", "则我这两条臂拦关扶碑，则我这两只手可敢便直钓缺丁。", "理会的山儿性，我从来个路见不平，爱与人当道撅坑。", "我喝一喝骨都都海波腾，撼一撼赤力力山岳崩。", "但恼着我黑脸的爹爹，和他做场的歹斗，翻过来落可便吊盘的煎饼。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・煞尾","p":"","d":"元代","a":"高文秀","c":["我去阿，两只手忙揪住巅险峰，两只脚牢踏住村峭岭。", "主张的我神州庙里身周正，我可敢搬倒那嵯峨，（带云）放心也，哥，（唱）这一座泰山顶。", "（同孙孔目下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・越调/金蕉叶","p":"","d":"元代","a":"高文秀","c":["你看他那说话处阿，（带云）我才说道恕生面少拜识，（唱）他做多少去眉弄色。", "（搽旦云）你看我这几步儿走，（正末唱）你看他那行动处呵，（带云）娘也，又不是那小脚儿，竖里一尺，横里五寸。", "（唱）做多少家鞋弓袜窄，可怕不打扮得十分像路？（带云）哥哥，不是你兄弟口歹也，（唱）你可敢记着一场大来大小利害。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・幺篇","p":"","d":"元代","a":"高文秀","c":["哎，你个嫂嫂莫得见责，也则是亏着俺为人在客，我恰才嘱付了三回五解。", "（搽旦扯孔目科，云）孔目，你早些儿回来。", "（孙孔目云）我就回来也。", "（正末扯孔目做走科，云）嫂嫂不索说，我和哥哥使来。", "我恰才嘱付了店家安抚了嫂嫂，天色将晚也。", "（唱）则去兀那泰安州寻一个家头房子去来。", "（同下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・仙吕/点绛唇","p":"","d":"元代","a":"高文秀","c":["柳絮堪扯，似飞花引惹，纷纷谢。", "莺燕调舌，此景宜游冶。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・油葫芦","p":"","d":"元代","a":"高文秀","c":["三月春光景物别，好着我难弃舍，怎当这佳人士女醉扶者？你看那桃花杏花都开彻，更和那梨花初放如银叶。", "（白衙内同搽旦上）（衙内云）大姐，咱行动些。", "（正末唱）我这里七留七林行，他那里必丢不搭说。", "又被那伙乔男乔女将咱来拽，（白衙内做撞正末科）（白衙内云）不中，走、走、走！（同下）（正末唱）这田地上赤留兀刺那时节。", "（云）甚么人伴我这一脚？不是赶俺哥哥忙呵。", "我不道的饶了你也。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・醉扶归","p":"","d":"元代","a":"高文秀","c":["则俺这拳起处如刀切，恨不得打塌这厮太阳穴。", "（孔目扳正末科，云）兄弟也，干他甚么事？（正末云）哥也，你放手。", "（唱）你将我这臂膊休扳住了者，（带云）我不打这厮别的，（唱）只打这厮强夺人妻妾。", "（带云）兀那厮，可不道\"寄在不寄失\"？（唱）你是个小主人家，可不道管着一个甚也？我恨不得一把火刮刮匝匝烧了你这村房舍！（云）哥也，我见来，我见来！一个男子汉，一个妇人，两上叠骑着马。", "我正行走着哩，被那马撞了我一脚。", "我待要赶去来。", "因为赶着哥哥，不曾去得。", "哥也，打与你一个模状儿，我见那厮的衣裳鞍马，说起来看是也不是？（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・一半儿","p":"","d":"元代","a":"高文秀","c":["我适才途中马上见他些，那一个妇人叠坐着鞍儿把身体趄，那一个乔才横摔着鞭儿穿插的别。", "我打个模状儿说，可不道有一半几朦胧倒有一半儿切！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・醉扶归","p":"","d":"元代","a":"高文秀","c":["那妇人呵，他唱一句为关节，那乔才呵，他应一句到来也。", "两下里惯速速怕甚么途路赊，必然个宽打着大周折。", "我和你疾忙赶上者，将他一双的在马前拽。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・赚煞尾","p":"","d":"元代","a":"高文秀","c":["我也不用一条枪，也不用三尺铁，则俺这壮士怒目前见血。", "东岳庙磕塔的相逢无话说，把那厮滴溜扑马上活挟。", "他若是与时节。", "万事无些；不与阿，山儿待放会劣忄敞。", "恼起我这草坡前倒拖牛的性格，强逞我这些敌官军勇烈，我把那厮脊梁骨各支支生撅做两三截！（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・双调/新水令","p":"","d":"元代","a":"高文秀","c":["我可便为哥哥打扮个丑容仪，（带云）有那等不认得我的，他道我是个呆厮，呆厮；有那等认得我的，他便道我那里是真呆厮，倒是个真贼。", "（唱）怎知道我是那家公明的兄弟？可也自有咱心上事，不许外人知。", "将我这饭罐儿忙提，山儿也，可用着你那贼见识入牢内。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・落梅风","p":"","d":"元代","a":"高文秀","c":["我这里高声的叫，叫到那五六口；哥哥你便开门，呆厮可便与哥哥支揖。", "（牢子打科，云）这呆厮好无礼也，你怎么抱住我两只手臂？我打这个弟子孩儿。", "（正末唱）做甚么恶哏哏怒从你那心上起？叔待，呆厮不曾汤着你，不索你没来由这般叫天吖地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・夜行船","p":"","d":"元代","a":"高文秀","c":["俺家里要打水浇畦，（带云）打罢那水，浇罢那畦，俺娘道：\"果厮，你还不往田里去。", "\"（唱）我又索与他压耙扶犁。", "（牢子云）好也，他把我当耕牛使用。", "（正末唱）我家里还待要打柴刈苇，织履编席，倒杼翻机。", "俺做庄家忒老实，俺可也不谎诈不虚脾。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・甜水令","p":"","d":"元代","a":"高文秀","c":["俺那时节因纳税当差，曾离乡下到来城内，（牢子云）这个也是认的兄弟，打甚么紧？（正末唱）因此上认义我做相识。", "（牢子云）若是要见他，须是替他将油灯钱、苦恼钱都与我些。", "（正末唱）我待要与俺哥哥送些茶饭，见些情义，俺两个又不是那真个亲戚。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・得胜令","p":"","d":"元代","a":"高文秀","c":["呀，便问我要东西。", "叔待，则你那没梁桶儿便休提。", "不比你财主们多周济，量俺这穷庄家有甚的？俺真个堪嗤，俺孩儿每卧土坑披麻被，你可也争知？（带云）还有精着腿，无个裤儿穿的。", "（唱）谁有那闲钱补笊篱？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・归塞北","p":"","d":"元代","a":"高文秀","c":["他前面引只，我背后把他跟随。", "我将这田地儿踏，窝蛇儿来记，呀！谁知道一步步走入那棘针根底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・雁儿落","p":"","d":"元代","a":"高文秀","c":["-那坨儿里墙较低，那坨儿里门不闭。", "那坨儿里得空便，那坨儿里无寻觅。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・川拨棹","p":"","d":"元代","a":"高文秀","c":["跟着他入牢内，使尽我这贼见识。", "哭哭啼啼，切切悲悲。", "则俺那孔目哥哥在那里？你可也思量些甚饭食？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・七兄弟","p":"","d":"元代","a":"高文秀","c":["我这里唤你，倒问我是谁？唤你的是王重义。", "（云）哎哟，哥哥也。", "（孙孔目云）兄弟也，你在那里来？（牢子打科，云）休要大惊小怪的！（正末唱）阁不住两眼忄西惶泪，俺哥哥含冤负屈有谁知？兀的不断送在高墙厚壁矮门内？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・梅花酒","p":"","d":"元代","a":"高文秀","c":["哥，这罪也自省的，使不着你精细，使不着你伶俐，竟不知你甚日脱离？告押衙作疑惑，辨别个是和非。", "有关防无势力，把平人下在死田地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・喜江南","p":"","d":"元代","a":"高文秀","c":["呀；俺哥哥又不是打家截道的杀人贼，倒赔了个如花似玉的好娇妻，送与你这倚权挟势白衙内。", "到今朝这日，才得我非亲是亲的送那碗饭儿吃。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・归塞北","p":"","d":"元代","a":"高文秀","c":["俺哥哥三朝的五日，可便忍饿耽饥。", "五六日不曾尝着水米，常言道饥饱劳役。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・鸳鸯煞","p":"","d":"元代","a":"高文秀","c":["这厮他两三番会使拖刀计，咱安排下搭救哥哥智。", "只在今日明朝，得胜而归。", "畅道天理难欺，人心怎昧？则他这肉眼愚眉，把一个黑旋风爹爹敢来也认不得。", "（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・中吕/粉蝶儿","p":"","d":"元代","a":"高文秀","c":["酒果做缘由，安排下这场歹斗，两事家不肯干休。", "打这厮，损别人，安自己，他直吃到上灯前后。", "猛可里抬头，不觉的助杀气冷风吹透。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・醉春风","p":"","d":"元代","a":"高文秀","c":["我想那一个滥如猫，这一个淫似狗。", "端的是泼无徒贼子，更和着浪包娄，出尽了丑、丑。", "情理难容，杀人可恕，怎生能够。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・幺篇","p":"","d":"元代","a":"高文秀","c":["争知道他在我面前，不提防我在他背后。", "只见他手脚张狂，左右拦当，何处奔投？则为这吃剑头，送得俺哥哥牢内囚，风也不透。", "（做揪白行内科，云）我不杀你，你唱波。", "（白衙内云）着我唱甚么？（正来唱）可唱你那\"夫妻每醉了还依旧\"。", "（正末杀白衙内科，云）我把两颗头都拿将来，做一搭里放者。", "再将他衣服上扯下一块来，捻做个纸捻，去腔子里蘸着热血，在白粉壁上写道：是宋江手下第十三个头领黑旋风李逵杀了这白衙内来。", "（诗云）从来白衙内，做事忒狡猾。", "拐了郭念儿，一步一勾搭。", "恼犯黑旋风，登时人性发。", "随你问旁人，该杀不该杀？写是写了，不免将着这二颗头，到梁山油上宋江哥哥根前献功去来。", "（唱）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・小梁州","p":"","d":"元代","a":"高文秀","c":["谁着你一世为人将妇女偷，见不得皓齿星眸，你道有闲茶浪酒结绸缎，天缘楱，不枉了好风流。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・幺篇","p":"","d":"元代","a":"高文秀","c":["虽则是婚姻注定前生有，到的我黑爹爹一笔都匀。", "那里也月下客，冰上叟，多管是杀人的领袖，（云）俺如今回去见宋江哥哥，他问道：\"山儿，你那泰安州的事怎么了？\"我可也不说别的，（唱）则献上这血沥沥两颗活人头！（下）。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・满庭芳","p":"","d":"元代","a":"高文秀","c":["奉哥哥元戎帅首，着我山儿、孔目，同去泰岳神州。", "又谁知草参亭上刚回后，早不见了泼贼淫囚。", "（带云）元来他与白衙内呵，（唱）他两个笑吟吟成双做偶，背地里悄促促设计施谋。", "（宋江云）他可设甚计谋来？（正末云）比时孙孔目哥哥赶上去，正要寻个大衙门告他下来，岂知白衙内那厮早借一座大衙门坐着，专等他来告状，就一把拿住，发下死回牢里。", "指望将他禁死了，与他浑家做了永远夫妻，可不好那。", "（唱）专等待来追究，便将他牢监固守，只落得尽场儿都做了鬼胡由。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・十二月","p":"","d":"元代","a":"高文秀","c":["因此上装一个送饭的沾亲带友，那一个管牢的便不乱扯胡揪。", "他见了咱拿着的是饭羹羊肉，就待要一气儿呷上两盏三瓯。", "他怎知道下的有砒霜巴豆，但吃着早麻撒撒，害得个魄丧魂丢。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・尧民歌","p":"","d":"元代","a":"高文秀","c":["那时节先打发了孙家孔目出牢囚，我就直到他衙门里面报冤仇。", "只见他两个醉中情意正相投，更遇着我为他取到沽来酒。", "清也波讴，清讴乐未休，只这两句是他死时候。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黑旋风双献功・随尾","p":"","d":"元代","a":"高文秀","c":["他、他、他，也会一骑马双驮着走，怎知俺两板斧劈下了头。", "这都是亲身作业亲身受，不枉了立军状的山儿果应了口。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・迎仙客暮春","p":"","d":"元代","a":"李致远","c":["吹落红，楝花风，深院垂杨轻雾中。", "小窗闲，停绣工。", "帘幕重重，不锁相思梦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・朝天子秋夜吟","p":"","d":"元代","a":"李致远","c":["梵宫，晚钟，落日蝉声送。", "半规凉月半帘风，骚客情尤重。", "何处楼台，笛声悲动？二毛斑，秋夜永。", "楚峰，几重，遮不断相思梦。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・红绣鞋晚春","p":"","d":"元代","a":"李致远","c":["杨柳深深小院，夕阳淡淡啼鹃，巷陌东风卖饧天。", "才社日停针线，又寒食戏秋千，一春幽恨远。", "春闺情红日嫩风摇翠柳，绿窗深烟暖香篝，怪来朝雨妒风流。", "二分春色去，一半杏花休，归期何太久？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・红绣鞋晚秋","p":"","d":"元代","a":"李致远","c":["梦断陈王罗袜，情伤学士琵琶，又见西风换年华。", "数杯添泪酒，几点送秋花，行人天一涯！。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"中吕・卖花声月夜","p":"","d":"元代","a":"李致远","c":["云消皎月筛帘影，梦破惊乌绕树声，挑灯起诵《太玄经》。", "竹轩风定，桂窗人静，快诗人一襟清兴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"商调・梧叶儿","p":"","d":"元代","a":"李致远","c":["佩解螭文玉，衾闲鸳序锦，钗折凤头金。", "夜雨留荷泪，西风吼树音，秋月弄桐阴，梅花谢别来到今。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・折桂令春闺","p":"","d":"元代","a":"李致远","c":["柳阴深黄鸟绵蛮，勤惜韶华，似罢红悭。", "绣草花飞，分香蝶闹，感旧人闲。", "奇兵破愁城酒盏，离情纟全恨锁眉山。", "沉水烧残，绣被熏兰，只是春寒。", "山居枕琴书睡足柴门，时有清风，为扫红尘。", "林鸟呼名，山猿逐妇，野兽窥人，唤稚子涤壶洗樽，致邻僧贳酒论文。", "全我天真，休问白鱼，且醉白云。", "读史慨西风壮志阑珊，莫泣途穷，便可身闲。", "贾谊南迁，冯唐老去，关羽西还。", "但愿生还玉关，不将剑斩楼兰。", "转首苍颜，好觅菟裘，休问天山。", "秋景秋声先到梧桐，挂雨雌霓，拂槛雄风。", "几点青山，一泓素月，满地丹枫。", "肠缕断情欺醉容，漏声迟霜满愁红。", "长笛声中，罨画楼东，泪洒征鸿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・清江引即席赠妓","p":"","d":"元代","a":"李致远","c":["碧云欲低香雾阻，回首多情处。", "梨花二月初，柳絮三春暮，今宵月明何处宿？樽前有人颜似玉，笑索多情句。", "歌残林叶飞，舞罢庭花妒，冰弦一霎秋夜雨。", "东风又来供暮愁，吹上蛾眉皱。", "应知弄玉心，相道东阳瘦，花落燕飞人病酒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・落梅风","p":"","d":"元代","a":"李致远","c":["斜阳外，春雨足，风吹皱一池寒玉。", "画楼中有人情正苦，杜鹃声莫啼归去。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・水仙子春怀","p":"","d":"元代","a":"李致远","c":["水边垂柳赤栏桥，洞里神仙紫玉箫。", "东风吹断闲花草，碧云深春梦悄，久别来朱户萧条。", "半帘明月，一溪绛桃，万里黄鹤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・水仙子道情","p":"","d":"元代","a":"李致远","c":["瓮头春色是长生，枕上华胥当解酲。", "常将造物合心镜，后庭闲留月明，得工夫休写《黄庭》。", "怕萧郎夫妇，茅家弟兄，邂逅瑶京。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・拨不断夏宿山亭","p":"","d":"元代","a":"李致远","c":["立峰峦，脱簪冠，夕阳倒影松阴乱。", "太液澄虚月影宽，海风汗漫云霞断，醉眠时小童休唤。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南吕・一枝花送人入道","p":"","d":"元代","a":"李致远","c":["白云留故山，晓月流清涧。", "西风吹渭水，落叶满长安。", "龙虎痴顽，正要别真赝，都来方寸间。", "内丹成未饮刀圭，宦情远不登仕版。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州・无中有娇儿姹女，有中无火枣金丹。温温铅鼎清光烂。一泓水静，","p":"","d":"元代","a":"李致远","c":["一片云闲。", "一轮月满，一点神安。", "断七情宝剑光寒，避三尸午夜更残。", "秘天真离坎交驰，纵玄旨乙庚配绾，炼希夷金木间关。", "药阑，岁晚，黄精满地和烟拣，安排净蚌珠灿。", "耿耿灵台照夜阑，去蕙留兰。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・辨清浊不在青白眼，夸悬解何劳道上肝。银海澄澄洞诸幻，快还，","p":"","d":"元代","a":"李致远","c":["九山，满地松风洞天晚。", "孤闷花梢消杜宇魂，藕丝系鸳鸯足。", "春风丹凤只，夜月翠鸾孤。", "对景萧疏，空忆如簧语，最添心上苦。", "冷清清沉水香残，昏惨惨灯花穗吐。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州・东墙女空窥宋玉，西厢月却就崔姝。便休题月下老姻缘薄。风流偏","p":"","d":"元代","a":"李致远","c":["阻，好事多辜。", "蓝田隐璧，沧海遗珠。", "桃源洞山谷崎岖，阳台路云雨模糊。", "书斋中勉强韩香，兰房中生疏郑五，泾河边不寄龙书。", "怨苦，自取。", "世间情知他是甚娘般物，自嗟叹静思虑。", "直教柳下惠开门不秉烛，薄命寒儒。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・一天愁寻杀裴生杵。千点泪啼斑湘女竹。一轮皓月当空正隐在云雾。","p":"","d":"元代","a":"李致远","c":["量半幅，素楮，诉不尽燕燕莺莺半分语。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"醉春风・想聚散若浮云，叹光阴如过隙。不如闻早赋归欤，畅是一个美，","p":"","d":"元代","a":"李致远","c":["弃职归农，杜门修道，早则死心搭地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"上小楼・我则待逐朝每日，无拘无系。我则待从事西畴，寄傲南窗，把酒","p":"","d":"元代","a":"李致远","c":["东篱。", "三径就荒，松菊犹存，规模不废，策扶老尚堪流憩。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・引壶觞以自酌，眄庭柯以自怡。有酒盈樽，门设常关，景幽人寂。或","p":"","d":"元代","a":"李致远","c":["命巾车，或棹孤舟，从容游戏，比着个彭泽县较淡中有味。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"耍孩儿・溪泉流出涓涓细，木向阳欣欣弄碧。登东皋舒啸对斜晖，有两般","p":"","d":"元代","a":"李致远","c":["儿景物希奇。", "觑无心出岫云如画，见有意投林鸟倦飞。", "草堂小堪容膝，说亲戚之情话，乐琴书以忘机。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"幺・或寻丘壑观清致，或自临清流品题。我为甚绝交游待与世相违，须是","p":"","d":"元代","a":"李致远","c":["我傲羲皇本性难移。", "想人间富贵非吾愿，望帝里迢遥不可期。", "已往事都休记，度晚景乐夫天命，其余更复奚疑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾声・辞功名则待远是非，守田园是我有见识。闲悠悠无半点为官意，一","p":"","d":"元代","a":"李致远","c":["任驷马高车聘不起。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"双调・新水令离别","p":"","d":"元代","a":"李致远","c":["离鸾别凤又经年，一番春一番新怨。", "青琐畔，绣帏前，少个婵娟，酬不了少年愿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"德胜令・今日小亭轩，羞到杏花边。黯黯愁成阵，厌厌日胜年。嫣然，一","p":"","d":"元代","a":"李致远","c":["笑春风面；无缘，灯前云髻偏。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"水仙子・别来几见月儿圆，每为嫦娥惜少年。画堂深隔断归来燕，玉钩闲","p":"","d":"元代","a":"李致远","c":["帘未卷，一天情着个谁传？想一饷心间事，写一幅肠断篇，等一个孤雁回旋。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"挂玉钩・爱杀槎头缩项鳊，皆上金盘荐；笑杀池中并蒂莲，未许东风见。","p":"","d":"元代","a":"李致远","c":["援紫毫，磨端砚。", "屈曲银钩，细草鸾笺。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"尾・沉沉烟锁垂杨院，迟迟月上桃花扇。罗帕新词，聊寄情缘。唱道张京","p":"","d":"元代","a":"李致远","c":["兆心专，周琼姬苦意坚。", "怕几阵东风吹落残花片，恁时绿暗红嫣，兀谁管春山翠眉浅。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"满庭芳","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["白发相催，青春不再，劝君莫羡精神。", "赏心乐事，乘兴莫因循。", "浮世落花流水，镇长是会少离频。", "须知道，转头吉梦，谁是百年人？雍容弦诵罢，试追搜占传，往事闲凭。", "想像梨园格范。", "编撰出乐府新声。", "喧哗静。", "伫看欢笑，和气蔼阳春。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"满庭芳","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["昔日孙家，双名必达。", "花朝行乐春风。", "琼梅李氏，卖酒亭上幸相逢。", "从此娉为夫妇。", "兄弟谋苦不相从。", "因往外，琼梅水性，再续旧情浓。", "暗去梅香首级，潜奔它处，夫主劳笼。", "陷兄弟必贵，盆吊死郊中。", "幸得天教再活，逢嫂妇说破狂踪。", "三见鬼，一齐擒住，迢断在开封。", "(末下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"粉蝶儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["生长开封，诗书尽皆历遍，奈功名五行薄浅。", "论荣华,随分有，称吾心愿。", "且开怀，共诗朋酒侣欢宴。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"惜奴娇","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["同出西郊，听乳莺枝上，一声啼起。", "萦情惹恨，恰似报人明媚。", "偏宜，两两三三穿花去，载传樽酬乐意。", "(和)我共你趁此青春，日日宴酌，对花沉醉。", "(净)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前换头","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["欢聚。", "草嫩轻黄，弄丝丝暗织，素肠千缕。", "夭桃张锦，无烟禁火烧拔。", "凝觑，万卉争开春罗绮，步芳郊真得趣。", "(和同前)(末唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锦衣香","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["见浪子，闲游戏。", "并艳质，闲游戏。", "都趁玉勒金鞍，共寻佳致。", "小桥芳草柳荫堤，鼎沸笙歌，随簪遗珥。", "玩江山景致，此身在画图里。", "(和)马嘶芳草地，粉蝶交飞。", "双双往来，游人如蚁。", "(生)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["傍柳边莺飞，度小桥，临绿水。", "一簇魏紫姚黄，竞舒罗绮。", "海棠枝上染胭脂，是谁家院宇？燕子来去，引青春浪子，小苍头斗草携垒。", "(和)看双双秋千架起。", "粉墙阴笑声鼎沸。", "(同唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"浆水令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["四时中春光最美，共游赏更莫待迟。", "暖风逐日好天气，莫蹉跎过了，谩自伤悲。", "花深处，酒望垂，可惜解貂留佩。", "同欢会。", "同欢会，同欢醉归。", "扶归去，扶归去，带好花枝。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"破阵子","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["自怜生来薄命，一身误落风尘。", "多想前缘悭福分，今世夫妻少至诚，何时得称心？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"破阵子","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["天若怜人孤苦，令樽前遇个良人。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"渔家傲","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["长吁嗟辜负朱颜枉度春，愁听得别院垂杨，黄鹂数声。", "两眉暗锁新愁恨，自慵临鸾镜。", "奈天不早从人，镇常是泪雨愁云，对东风泪滴新愁间旧愁。", "(梅唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"剔银灯","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["春映秋波暗动情，何须虑孤衾闲枕？香醪路远人沽饮，娇貌美风流厮称。", "日日，同欢共饮，尤强似嫦娥不嫁人。", "(旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"地锦花","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["懒能临掠乌云鬓，慵点绛唇。", "对谩当垆效学文君。", "暗想文君，何时迎得知音？一片至诚心，奈何天也不由人。", "(同唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"麻婆子","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["对景对景空题恨，赢得闷上心。", "止愁止愁青春过，年华暗逐人。", "殷勤回首问东君：桃花开谢逢春，怕奴容颜老，何时遇个人？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"水底鱼儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["柳绿花红，名园甲风景多。", "杏开如锦绣，天桃如喷火。", "王孙仕女，笑嬉嬉同宴乐。", "寻芳拾翠，拚倾杯沉醉呵。", "(生末净相见行令介)(旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"乔合笙","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["群花破蕊，破蕊红白竞妆，无限春光明媚。", "香醪韵恁奇，不须推拒。", "(和)共陪笑语，君还有意，作画栏为花主。", "(梅)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["官人看取。", "看取蜂蝶对对，相逐花间游戏。", "何妨对此时，猛拚沉醉。", "(和同前)(生唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"忒忒令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["燕呢喃雕梁上对语，未知它诉着何意？料应说着，衷肠如是：两个镇双飞，双双来，双双去。", "算何时似你？(末)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["算人生百年有几，不欢乐更待何时！大都三万六千日，何不遇花遇酒，花前饮，花下醉？且开怀自舒。", "(旦唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红绣鞋","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["谢得东君留意，留意；将来头醉霞王危，霞王危。", "赏芳菲，惜花意。", "不妨做，锦屏围。", "莫令人，乱攀折。", "(生)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["幸得花□相会，相会；好似崔生觅水。", "觅水。", "怕别后，忆年时。", "桃面花，两东西。", "甚时节，再相会？(同唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"刮鼓令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["花影渐移，红日相将坠。", "对花一恁拚沉醉，共插着花几枝。", "花篮轿儿香韵奇，花阴柳下人渐稀。", "当歌对酒醺醺地，教人道醉扶归。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"金鸡叫","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["老景催人去，年华事暗随流水。", "愿家筵无虑萦心绪，晨夕清香，一炷谢人地。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"铧锹儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["从来你行惯，曾途中历遍。", "今日此行，须是意莫留连。", "遣我朝夕恁忧煎，望得孩儿眼穿。", "子母心，两处悬。", "(和)鸿飞不到处，总被利名牵(末)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["孩儿告娘。", "休得忧怨。", "人言小富由命，大富由天。", "但得安乐是的前缘，坐享不能门然。", "暂离家，即便转。", "(和)去处莫迟延，娘亲望眼穿。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"天下乐","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["一种相思聚两眉，因娇卖酒。", "此妇人生得肌莹琼台片雪，脸如红杏鲜妍。", "见它不觉惹起鸳鸯之恨，欲求鸾凤之欢。", "说道：若得落籍除名，愿为夫妇。", "如今不免多将些金帛，前往衙前，寻那旧契张面前，去那本官根前说则个。", "(末上白)昨晚那孙必达所托之事，已自从本官根前覆过了。", "今日特来这里，说与那人知道。", "(末见生介)(生)张面前，昨日所托之事如何？(末)昨晚已曾本官根前说过了当，请哥哥来。", "(生)小生不多，先有银子两锭，上下使用。", "哥根前小生当自重重拜谢！(末)不须如此。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"光光乍/同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["夫妻是宿缘，当与你作宛转。", "放下心肠休忧虑，管教你成姻眷。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"西地锦","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["下官心平公正，卑职掌开封。", "但民歌千里明忠，正报和气春风。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"风马儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["闻得提携寸心喜，来厅下听台旨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"鹅鸭满渡船","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["谢得恩官，且免妾为娼妓。", "这些恩德处，怎忘之！甚时能结学韩珠？(和)从今系籍名字除，付凭据从此上。", "免怨嗟，琉璃井。", "幸脱离。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["自来不心地，为你多娇媚。", "堕落烟花内，本无礼。", "快疾速移改迟便追！(和同前)(净)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["今日除名字，皆是我恩德。", "(旦)人非土木的，不敢忘恩义。", "(和)幸然脱得花门去，心欢喜鸳鸯情，免沉迷。", "如花貌，绝风雨(外)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["本官心地，事由公理。", "踢脱这些儿，果有阴德处。", "(和同前)(梅)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["念奴娘子，本是良人女。", "早晚办名香，答谢天和地。", "(和同前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"北曲一枝花","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["山遥江水长，人远天涯近。", "去驼登紫陌，迤逦践红尘。", "自离家乡，寂寞无人问。", "朝朝愁闷损。", "然虽路上堪行，俺则是心中未稳。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州第七","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["蓦蓦地古道西风峻岭，过了夕阳流水孤村，如今尘随马足何年尽！常就劳落，不必艰辛。", "几番回首，几度忘魂。", "只为家中年老慈亲，朝夕侍奉无人。", "明知孝悌人之大本，想着受煦劳育我全身，不能勾落业安平。", "自俺甫临行，曾把哥哥禀．常侍奉莫因循。", "只怕哥哥把话不准，迷恋着红裙。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"黄钟尾","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["如今未遭际汉风雷信，有一日得到家乡桃李春。", "打旋回来分，参拜了母亲，答谢了众神，便受了奔波正的本。", "(下)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"凤时春","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["得失荣枯在命，夫妻事岂非天为。", "我的孩儿今成夫妇，论此因缘，事皆前定。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"迎仙客","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["谢娘子，恁提携，料想前生曾会伊。", "燕双飞，一对儿。", "(和)算来因契，斗合非容易。", "(旦上唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["念奴家，好人女，幸遇君家才貌奇。", "似鸾凤。", "-对儿。", "(和同前)(婆)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["我孩儿，恁聪惠，娶得媳妇百事宜。", "郑州梨，一对儿。", "(和同前)(梅上唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["我娘子，果娇媚，幸遇官人俊貌美。", "似鸳鸯，一对儿。", "(和同前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["必达告娘行听启：因缘事非容易，今日里情分和谐，妈妈免得忧虑。", "难比，艳妆娇貌多俊美，论西施则如是。", "(和同前)(旦)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["奴自小良人女．谢君家提携到这里。", "不弃取甘为箕帚，只愿尽老连理。", "和你，共谐百岁直到底，更无二心三意。", "(和同前)(梅)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["听取梅香拜启：幸今日到此岂非容易。", "今日里惜分和谐，谢恩家不惜千金买断花为主。", "应是，此生缘分天际会，愿百岁永同龟水。", "(和同前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"朱哥儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["哥哥听兄弟拜启：它须烟花泼妓，水性从来怎由己，缘何会做得人头妻？伊不听，兄弟劝时，也须看前人例。", "(生)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["我兄弟说得自是，它如今须脱了名籍。", "我见它真实娶它归，娘亲老待它看侍。", "(和)今日里，成亲爱喜，休口快胡言语。", "(旦)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["叔叔好不傍道理，奴元是好人儿女。", "坠落烟花怎由己？将奴骂泪珠偷滴。", "(和同前)(婆)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["劝孩儿休得要恁地，你嫂嫂看来也贤德。", "自今一家要和气，改日与你娶房妻儿。", "(和同前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["休得听闲说是非，劝娘行也休得呕气。", "这般闲争甚巴臂，傍人听是何张志。", "(和同前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梁州令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["一对鸾凰共宴乐。", "恨连日抛弹。", "这冤家莫竟信刁唆，把奴家，恩和爱，尽奚落。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧桐树","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["思量闷上心，人去无踪影。", "悄似随风柳絮无凭准，却与旧日心不应。", "误我良宵寂寞守孤灯，数尽更筹夜长人初静，教人恨杀活短命。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"北曲新水令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["却踏过满庭芳草看花问．怨正孙不思折桂。", "每日上小楼沽美酒，销金帐卫共传杯。", "吃洒沉醉扶归，不由我不伤情苦萦系。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南曲风人松","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["记前日席上泛绿蚁，做夫妻永同连理。", "谁知每日贪欢会？醺醺地不思量归计。", "你那里谁人共美？教奴自守孤帏。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"北曲折桂令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["几回价守定香闺，转无眠情绪如痴。", "直哭得绛蜡烟消，银蟾影坠，宝篆香微。", "才听得促织儿声沉四壁，又听得叫残早报晓邻鸡。", "只影孤凄，心下伤悲。", "一弄儿凄凉，总促在愁眉。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南曲风人松","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["我一心指望你攻书。", "要改换门闾。", "如今把奴成抛弃，朝朝望朝朝不至。", "好教人鸳衾坦冷落，须闲了我一个枕头儿。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"北曲水仙子","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["好因缘间阻武陵溪，辜负花前月下期，彩云易散琉璃脆，亏心底不似你，担阁了少年夫妻。", "不枉了真心真诚意，不把我却寒知暖妻。", "不能勾步步相随。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"北曲雁儿落","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["谁同莺燕期？谁展鸳鸯被？谁双斟鹦鹉觞？谁匹配鸾凤对？(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南曲风人松","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["细思量教我泪双垂，使奴虚度良时。", "绣房懒入拈针指，终朝里没情没绪。", "枕屏边声声叫你，情脉咏转九语。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"北曲得胜令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["则笑卓氏女忒心痴，它被这睡魔正厮禁持。", "则想醉里乾坤大，全不想花间云雨期。", "身靠着屏围，魂梦谁根底？酒病好难医，今朝醒觉迟。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"南曲风人松","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["看刘伶酒自半醒时，不似你沉醉如泥。", "当初李白曾题记，它得遇唐朝皇帝。", "(白)李太白醉时，杨妃捧砚，力士脱靴，龙巾拭唾，御手调羹。", "今日也是醉，(唱)枉教人千般告你，别寻个解绦底。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"石榴花","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["奴家从小流落在风尘，几番和你共枕同衾。", "如今踢脱做良人，谁知到此，倍觉伤情。", "幸君家殷勤到这里，想因缘已曾结定。", "(和)花前宴乐同欢会，伊和我两同心。", "(净)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["娘子貌美铅华鬓堆云，梳妆巧煞精神。", "金莲三寸太轻盈，言淡举止多风韵。", "咱庞儿青春，青春俏勤，教人道果然厮称。", "(和同前)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"驻马听","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["洒困沉沉，睡里听得人斗争。", "是我荒惊恼觉，自觉一身，战战兢兢。", "方知欲问这元因，忽然见兄弟持刀刃，连叫两三声。", "莫不是嫂嫂不钦敬？(末)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["哀告君听：奴在房儿卫欲睡寝？怎知叔叔来此，巧言花语，扯奴衣襟。", "(末白)孙二须不是这般样人。", "(旦连唱)因奴家不肯便生嗔，将刀欲害伊家命。", "(末白)哥哥休听它家说，孙二不敢。", "(旦连唱)只得叫邻人，将奴赶得没投奔。", "(生)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["此事难凭，两下差池人怎明？(末白)哥哥，甚不明处？养着奸夫。", "(旦接唱)叔叔声声只道，养着奸夫。", "奸夫你说是何人？(末白)明养着奸夫。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"转山子","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["因甚家中闹声沸？听言沿差池。", "心下探自觉猜疑，还未知何般凶吉？到堂前探取，免心下多虑。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"挂真儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["东岳灵祠几程路，还心愿只得前去。", "只虑家中，无人看觑，叫出孩儿说与。", "(生上唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["燕尔新婚正欢聚，何曾肯暂离一步。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"柰子花","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["相将岳帝生乾日，欲同去烧香献纸。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["如今即便登途，家缘事分付汝。", "(生)告妈妈宽心行路，两下里休虑忆。", "(旦)妈妈须是早早回归，路途上自宜小心。", "(和同前)(末上唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"赚","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["听娘有旨，目今要往东岳去。", "(旦)恨分离，家中无人管顾奴。", "(生)我如今，相送娘行出外去，侧耳先回故里。", "(末)更莫待迟。", "(旦)叫梅香安排数杯。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红芍药","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["今去东岳，一杯助和气。", "(婆)梅香媳妇在房帏，须是照管家计。", "(旦)三人路途须仔细，不妨早作归计。", "(和)名香一炷告神柢，合家保无危。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前换头","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["酌酒东郊已先醉，门前早已排轿儿。", "两日三朝望你归□。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"梧叶儿","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["欲说破，有谁听，不记暗叮咛。", "飘然去，悄如水上萍。", "尽把恩情，悄似梧叶儿一片轻。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["娘休虑，且宽心，何必自伤情。", "(旦)虽然出去便回程，房儿里好凄清。", "长叹两三声，它热如火我冷如冰。", "(旦)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["休只管，恋它每，入眼便为勤。", "不须急性，有日称心，莫把恩情悄似冰。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"淘金令","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["灯前报蕊，鹊噪檐前喜。", "今日见你，果是非容易。", "浅斟低唱，放些娇痴，怕甚花梢风雨。", "办坚着意，-杯劝君须记取。", "(和)同携素手，并着香肌，共入罗帏效连理。", "(净)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"桃李争放","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["听得叫梅香，只得堂前听取使。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"锦天乐","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["且停威，告恩官略慈念。", "昨日我萱亲去烧香，卑人送到半途回转。", "谁把我妻谋骗？首级无有鲜血染，望恩官乞赐明验。", "回心转，言念无辜，怎生屈受刑宪？(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"上小楼","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["公吏人排列两边，不由我心惊胆战。", "怎推这铁锁沉枷，麻捶撒子？受尽熬煎。", "假若使心似铁，这官法如炉烧炼。", "休悲我枉屈后，死而无怨。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前换头","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["列今日怎知道，番成罪愆？略略望哀怜，常言道公门可行方便。", "人易唬，天须见，拷打千般神魂乱。", "空有日月须明，不照覆盆下面，便招作鬼死也埋冤。", "(又唱)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"红绣鞋","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["拷的我魂飞魄散，打的我肉烂皮穿。", "告你个有鉴察曹司，望周全。", "你是一纸教天赦，飞下九重天，杀人罪愆，怎的免？。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"四边静","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["将它短招读一遍，把词因好生看。", "休要顺人情，依法自行遣(和)。", "这场罪愆，怎生觯免？一一与招成，三年待决断。", "(生)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"同前","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["谁知命运遭乖蹇，今朝受刑宪。", "免教受扌朋扒，感恩即非浅。", "(和同前)(净)。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"},
  {"t":"一撮棹","p":"","d":"元代","a":"萧德祥《小孙屠》","c":["吃黄连，心苦向谁言？无处语，莫得告苍天。", "(外)枷收了，明日要归勘。", "将就理，实说早周全。", "(生)怎禁枷和锁，铁心肠泪涟涟。", "情最苦，身落在罪办禁。"],"tags":["元曲"],"z":"","y":"","s":"","k":"曲"}
];